window.EVENTS_E=[{"id":"E-001","branch":"E","stage":1,"day":1,"shichen":"辰时","checkpoint":"投亲不遇","scene":"天蒙蒙亮，你随着粮船过了虹桥，汴京的晨雾里有炊饼香。包袱里一把木梳、三贯钱，是你全部的家当。","options":[{"text":"先寻亲戚家落脚","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"投奔是正理。你攥紧写着地址的纸，往州西寻去。","source":"《东京梦华录》记汴河漕船晨昏不绝。"},{"text":"先在街上逛一圈","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"街景虽好，日头一高，肚里先叫了。","source":"《东京梦华录》记御街商铺黎明即开。"}],"difficulty":1,"npc":[],"foreshadow":"地址上那家人，未必肯认这门亲"},{"id":"E-001-戌","branch":"E","stage":1,"day":1,"shichen":"戌时","checkpoint":"投亲不遇·二","scene":"天黑了，客店最便宜的通铺也要十五文。你在州桥边来回走，桥头石狮子被夜市的灯笼照得发亮。","options":[{"text":"咬牙住通铺，留钱应急","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一夜听着鼾声，你抱着包袱想：总得先活下来。","source":"《东京梦华录》记州桥一带邸店密集。"},{"text":"桥洞下将就一夜","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"省下十五文，夜里露水重，冻得没睡踏实。","source":"《东京梦华录》记州桥夜市至三更方散。"}],"difficulty":1,"npc":[],"foreshadow":"州桥这方地界，日后是她的根"},{"id":"E-001-未","branch":"E","stage":1,"day":1,"shichen":"未时","checkpoint":"投亲不遇·三","scene":"巷子深处找到舅家，门房上下打量你浆洗发白的布裙，说舅老爷赴任去了，归期未定。","options":[{"text":"讨碗水喝，体面告辞","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"门房倒了碗温水。你没哭，转身时脊梁挺得直。","source":"宋人笔记常记投亲不遇、门房挡驾之事。"},{"text":"坐门槛上等舅父回来","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"等到掌灯被婉言劝走，日头白晒了一下午。","source":"宋人笔记常记投亲不遇、门房挡驾之事。"}],"difficulty":2,"npc":["门房"],"foreshadow":"舅家嫌贫，后文还会翻脸"},{"id":"E-002","branch":"E","stage":1,"day":2,"shichen":"辰时","checkpoint":"投亲不遇·四","scene":"清晨你在通铺角落梳头。娘留的木梳缺了个齿，梳齿划过头皮，一下一下，像娘还在。","options":[{"text":"收好木梳，出门找活","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"把念想收进怀里，人得往前看。你出了店门。","source":"宋代女子以梳篦为随身心爱之物。"},{"text":"多坐一会，缓一缓","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"允许自己想娘一刻钟，然后抹把脸出门。","source":"宋代女子以梳篦为随身心爱之物。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"木梳是全线的念想信物"},{"id":"E-002-戌","branch":"E","stage":1,"day":2,"shichen":"戌时","checkpoint":"投亲不遇·五","scene":"洗到掌灯，掌柜娘子多给了五个文钱：「手勤，明日还来。」你攥着二十五文，觉得比三贯钱还沉。","options":[{"text":"道谢，明日早些来","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"一句应承，在这条街算挂上了号。","source":"宋代市井重信诺，口头约定即为凭。"},{"text":"问问能不能管顿饭","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘子愣了下，给了个剩炊饼，神色淡了些。","source":"宋人笔记记雇工与主家讲究分寸。"}],"difficulty":1,"npc":["掌柜娘子"],"foreshadow":"掌柜娘子是她第一个市井贵人"},{"id":"E-002-未","branch":"E","stage":1,"day":2,"shichen":"未时","checkpoint":"投亲不遇·六","scene":"茶坊门口贴了招浆洗妇的红纸。掌柜娘子问你：一天洗三十件，二十文，做不做？","options":[{"text":"应下，再讨口水喝","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"手泡得发白，可第一天的饭钱有了着落。","source":"《东京梦华录》记汴京茶坊多用雇工。"},{"text":"嫌工钱少，再看看","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"转了一圈，别家要么不招人，要么要保人。","source":"宋代雇工多需铺保或熟人引荐。"}],"difficulty":1,"npc":["掌柜娘子"],"foreshadow":"浆洗攒下第一笔本钱"},{"id":"E-003","branch":"E","stage":1,"day":3,"shichen":"辰时","checkpoint":"立足求生","scene":"井边打水，一个瘦小的乞儿盯着你的炊饼咽口水，眼睛亮得像两颗黑豆。","options":[{"text":"掰一半给他","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"他三口两口吞了，冲你咧嘴笑，露出豁牙。","source":"《东京梦华录》记汴京街市有贫儿乞食。"},{"text":"自己还不够吃，不理","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你硬起心肠吃完，饼渣咽得有点哽。","source":"《东京梦华录》记汴京街市有贫儿乞食。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"乞儿小豆子，日后帮她跑腿探消息"},{"id":"E-003-戌","branch":"E","stage":1,"day":3,"shichen":"戌时","checkpoint":"立足求生·二","scene":"夜市起来了，州桥上灯火连成一条河。你帮掌柜娘子收完最后一批衣裳，站在桥边看了会灯。","options":[{"text":"记下哪个摊子人多","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"食摊最聚人，翻台快。你心里记下一笔账。","source":"《东京梦华录》记州桥夜市食摊至三更。"},{"text":"早些回店睡觉","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"歇得早是好的，只是错过了一课生意经。","source":"《东京梦华录》记州桥夜市食摊至三更。"}],"difficulty":2,"npc":[],"foreshadow":"她动了摆摊的念头"},{"id":"E-003-未","branch":"E","stage":1,"day":3,"shichen":"未时","checkpoint":"立足求生·三","scene":"午后送洗好的衣衫去主顾家，路过脚店，羊汤的香气勾得你脚步一顿。你摸摸怀里的铜钱。","options":[{"text":"买碗最便宜的素汤","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"热汤下肚，人才像重新活了过来。","source":"《东京梦华录》记州桥脚店食摊林立。"},{"text":"忍着，省下三文钱","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"省是省了，下午洗衣时眼前直冒金星。","source":"《东京梦华录》记州桥脚店食摊林立。"}],"difficulty":1,"npc":[],"foreshadow":"脚店羊汤，是 CP 缘起的味道"},{"id":"E-004","branch":"E","stage":1,"day":4,"shichen":"辰时","checkpoint":"立足求生·四","scene":"天没亮你就到了茶坊。掌柜娘子打着哈欠开门，见你已经把井水打满了，挑了挑眉。","options":[{"text":"趁手快多揽些活","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"多洗十件多七文，手快的人饿不着。","source":"宋代雇工多按件计酬。"},{"text":"按昨日的量做就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"稳妥是稳妥，攒本钱却慢了一截。","source":"宋代雇工多按件计酬。"}],"difficulty":1,"npc":["掌柜娘子"],"foreshadow":"勤快名声传开，活路渐宽"},{"id":"E-004-戌","branch":"E","stage":1,"day":4,"shichen":"戌时","checkpoint":"立足求生·五","scene":"回店路上，小豆子蹿出来，塞给你半块还温的胡饼：「姐姐给的，我都记着呢。」","options":[{"text":"分他一半，一起吃","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"桥洞风凉，两个人分一块饼，倒是暖的。","source":"《东京梦华录》记胡饼为汴京常见吃食。"},{"text":"让他自己吃，摸摸头","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子吃得香，你看着，忽然不那么想家了。","source":"《东京梦华录》记胡饼为汴京常见吃食。"}],"flavor":true,"difficulty":1,"npc":["小豆子"],"foreshadow":"市井里结下的善缘都会还回来"},{"id":"E-004-未","branch":"E","stage":1,"day":4,"shichen":"未时","checkpoint":"立足求生·六","scene":"绸缎庄的伙计抱来一摞贵客的罗衫，特意叮嘱：皂角轻揉，不可使蛮劲，洗坏一件赔不起。","options":[{"text":"请教掌柜娘子诀窍","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"娘子教你米汤水浆、阴凉处晾，罗衫无损。","source":"宋代浆洗以皂角、米汤为常法。"},{"text":"照自己的法子洗","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"一件起了毛，工钱扣了一半，心疼半天。","source":"宋代浆洗以皂角、米汤为常法。"}],"difficulty":2,"npc":["掌柜娘子","绸缎庄伙计"],"foreshadow":"一手好浆洗，日后能接体面人家的活"},{"id":"E-005","branch":"E","stage":1,"day":5,"shichen":"辰时","checkpoint":"首夜安身","scene":"掌柜娘子说，茶坊后头有间堆柴的小耳房，月钱二百文，你要愿意，收拾出来住，比通铺便宜安稳。","options":[{"text":"当下应下，先打扫","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"扫出三簸箕灰，挂上草帘，这是个家了。","source":"宋代汴京租房称'赁屋'，市井常见。"},{"text":"再想想，怕欠人情","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"犹豫一天，娘子把房许给了别人，懊悔。","source":"宋代汴京租房称'赁屋'，市井常见。"}],"difficulty":2,"npc":["掌柜娘子"],"foreshadow":"柴房小家，是她立足的第一块砖"},{"id":"E-005-戌","branch":"E","stage":1,"day":5,"shichen":"戌时","checkpoint":"首夜安身·二","scene":"第一夜睡在自己的小屋里。窗外是汴京的市声，你把木梳放在枕边，轻声说了句：娘，我有地方住了。","options":[{"text":"睡个踏实觉","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"五天来第一觉睡到天光，醒来眼里有神。","source":"《东京梦华录》记汴京民居紧邻市声。"},{"text":"点油灯再盘盘算算","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"灯花爆了一下，账上的数让你心安。","source":"《东京梦华录》记汴京民居紧邻市声。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"checkpoint 收官：首夜安身"},{"id":"E-005-未","branch":"E","stage":1,"day":5,"shichen":"未时","checkpoint":"首夜安身·三","scene":"收拾屋子时，你在柴堆后捡到个豁口陶碗，洗洗干净，又从街上淘了张旧苇席。三贯钱原封没动。","options":[{"text":"记一笔收支小账","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"炭条在墙皮上记账：进来多少，该攒多少。","source":"宋代市井买卖人皆有记账之习。"},{"text":"过日子心里有数就行","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"到月底才发现，铜钱比想得溜得快。","source":"宋代市井买卖人皆有记账之习。"}],"difficulty":2,"npc":[],"foreshadow":"记账的墙皮，陪她从柴房到摊子"},{"id":"E-006","branch":"E","stage":1,"day":6,"shichen":"辰时","checkpoint":"立足求生·七","scene":"隔壁货郎担大嫂看你就着凉水啃饼，塞给你一勺自家腌的酱瓜：「小娘子，饭要趁热吃。」","options":[{"text":"道谢，改日帮她看摊","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"一来一往，街面上多个替你说话的人。","source":"宋代市井邻里互济，笔记中屡见。"},{"text":"推辞不过，只收下","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"酱瓜很香，只是人情欠着，心里不踏实。","source":"宋代市井邻里互济，笔记中屡见。"}],"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"大嫂日后带她入行摆摊"},{"id":"E-006-戌","branch":"E","stage":1,"day":6,"shichen":"戌时","checkpoint":"立足求生·八","scene":"夜里盘账：今日浆洗二十八文，帮厨下洗食盒多得了六文。墙皮上的数字，一点点往上爬。","options":[{"text":"把三贯钱照旧存着","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"这是压箱底的底气，不到万不得已不动。","source":"宋代小钱贮蓄多以陶罐埋藏。"},{"text":"取些钱换床薄被","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"夜里凉，对自己好一点，不算糟蹋钱。","source":"宋代小钱贮蓄多以陶罐埋藏。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"三贯钱何时动用，是个扣子"},{"id":"E-006-未","branch":"E","stage":1,"day":6,"shichen":"未时","checkpoint":"立足求生·九","scene":"州桥脚店门口，洗碗的老仆闪了腰，一摞碗眼看要倒。你三步并两步扶住了。","options":[{"text":"顺手帮他把碗洗了","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老仆连声道谢，后厨一个青年探出头看了一眼。","source":"《东京梦华录》记脚店后厨佣作之景。"},{"text":"扶稳就走，不逗留","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"做了好事没留名，倒也没什么可惜。","source":"《东京梦华录》记脚店后厨佣作之景。"}],"difficulty":1,"npc":["老仆陈伯"],"foreshadow":"后厨那个青年，就是陈七郎"},{"id":"E-007","branch":"E","stage":1,"day":7,"shichen":"辰时","checkpoint":"立足求生·十","scene":"茶坊来了差役，说要查赁屋的户籍。掌柜娘子替你担保：「这是我家的帮工，本分人。」","options":[{"text":"备齐说辞，坦然应对","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"差役记下姓名里贯，没再为难，走了。","source":"宋代城市编户、客籍登记皆有定制。"},{"text":"躲进柴房不露面","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"越躲越惹疑，娘子替你赔了不少好话。","source":"宋代城市编户、客籍登记皆有定制。"}],"difficulty":2,"npc":["掌柜娘子","差役"],"foreshadow":"客籍孤女，身份是她软肋"},{"id":"E-007-戌","branch":"E","stage":1,"day":7,"shichen":"戌时","checkpoint":"立足求生·十一","scene":"守摊到掌灯，大嫂回来数钱，硬是多分了你两文：「守摊守出了精气神，该多拿。」","options":[{"text":"收下，请大嫂喝浆","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"两碗蜜浆，喝出了师徒的意思。","source":"《东京梦华录》记街头卖浆者众多。"},{"text":"推回多给的两文","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大嫂笑你犟：「人在外，该拿的得拿。」","source":"《东京梦华录》记街头卖浆者众多。"}],"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"大嫂会教她摆摊的门道"},{"id":"E-007-未","branch":"E","stage":1,"day":7,"shichen":"未时","checkpoint":"立足求生·十二","scene":"大嫂的货郎担缺人照看，她要去进货，问你能不能替她守半天摊，卖出去的钱分你一成。","options":[{"text":"应下，学着吆喝","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"头一嗓子喊劈了，第三声就有了样子。","source":"《东京梦华录》记汴京叫卖之声各具腔调。"},{"text":"怕生，只守不吆喝","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"守是守住了，半天只卖出去两根头绳。","source":"《东京梦华录》记汴京叫卖之声各具腔调。"}],"difficulty":2,"npc":["邻摊大嫂"],"foreshadow":"第一次摆摊练手，胆量渐长"},{"id":"E-008","branch":"E","stage":1,"day":8,"shichen":"辰时","checkpoint":"立足求生·十三","scene":"一早去脚店送洗好的围裙。后厨蒸笼掀开，白汽腾起，那个青年正手忙脚乱地片羊肉，刀工笨但下刀很稳。","options":[{"text":"放下东西就走，不看","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"余光里见他冲你点了点头，耳朵有点红。","source":"《东京梦华录》记脚店厨作晨备之景。"},{"text":"搭句话再交活","correct":false,"tags":["自主","感情"],"dims":{"自主":1,"情缘":1},"feedback":"「衣裳浆好了。」他「嗯」了一声，刀差点片到手。","source":"《东京梦华录》记脚店厨作晨备之景。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"CP 陈七郎正式照面"},{"id":"E-008-戌","branch":"E","stage":1,"day":8,"shichen":"戌时","checkpoint":"立足求生·十四","scene":"打烊前你去还汤钱，青年摆摆手不肯收，憋了半天说：「汤是剩的，倒了可惜。」灶火映着他的侧脸。","options":[{"text":"钱放灶台上就走","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"情缘":1},"feedback":"他在后头喊「欸」，你没回头，嘴角翘着。","source":"宋代市井男女交谈多隔柜答话，守礼。"},{"text":"帮他刷了锅抵债","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"情缘":1},"feedback":"一口大锅两个人刷，水汽里谁都没多话。","source":"宋代市井男女交谈多隔柜答话，守礼。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"还汤钱这一笔，他记在了心里"},{"id":"E-008-未","branch":"E","stage":1,"day":8,"shichen":"未时","checkpoint":"立足求生·十五","scene":"晌午你的铜钱见底，离发工钱还有两天。站在脚店门口，羊汤的香气一阵一阵往外涌。","options":[{"text":"赊一碗汤，说明日还","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"青年愣了愣，盛了满满一碗：「不急，先喝。」","source":"宋代市井赊账寻常，称'赊欠'。"},{"text":"饿着，等发工钱","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"骨气是足了，下午搬水时眼前发黑。","source":"宋代市井赊账寻常，称'赊欠'。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"赊一碗汤，是两人缘分的引子"},{"id":"E-009","branch":"E","stage":1,"day":9,"shichen":"辰时","checkpoint":"立足求生·十六","scene":"掌柜娘子说脚店想找个人替病了的帮厨送菜，一天十五文管一顿晌饭，问你去不去。","options":[{"text":"去，两边活都接着","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一天两份工，累归累，钱袋子眼见鼓起来。","source":"宋代市井打短工称'觅佣'，极常见。"},{"text":"怕忙不过来，推了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"错过了管饭的好活，也错过了某个人。","source":"宋代市井打短工称'觅佣'，极常见。"}],"difficulty":1,"npc":["掌柜娘子"],"foreshadow":"进脚店帮工，与七郎日日相见"},{"id":"E-009-戌","branch":"E","stage":1,"day":9,"shichen":"戌时","checkpoint":"立足求生·十七","scene":"脚店打烊，七郎把一碟没卖完的旋煎羊白肠推给你：「剩的。」你尝了一口，外焦里嫩，香得很。","options":[{"text":"夸他手艺好","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"他搓着围裙角笑：「明儿……还给你留。」","source":"《东京梦华录》记州桥夜市卖旋煎羊白肠。"},{"text":"问这菜怎么做的","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"他讲得颠三倒四，你倒听出了七八分门道。","source":"《东京梦华录》记州桥夜市卖旋煎羊白肠。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"旋煎羊白肠，日后是她摊上的招牌"},{"id":"E-009-未","branch":"E","stage":1,"day":9,"shichen":"未时","checkpoint":"立足求生·十八","scene":"送菜路上遇着绸缎庄的管事娘子，说府上宴席缺个打杂的，三日三十文，问你愿不愿意去。","options":[{"text":"应下，互相搭着做","correct":true,"tags":["才华"],"dims":{"才华":1,"自主":1},"feedback":"宴席上见识了大户人家的排场，开了眼。","source":"《东京梦华录》记汴京筵席假赁之盛。"},{"text":"怕误了脚店的活","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"稳稳当当，只是少了一份见识和进项。","source":"《东京梦华录》记汴京筵席假赁之盛。"}],"difficulty":2,"npc":["管事娘子"],"foreshadow":"宴席帮工，攒本钱也快些"},{"id":"E-010","branch":"E","stage":1,"day":10,"shichen":"辰时","checkpoint":"立足小成","scene":"进城第十天。你数了数：工钱加零碎进项，除去嚼用，净攒一百二十文，三贯本钱纹丝未动。","options":[{"text":"给自己加个蛋","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"热腾腾的熟鸡蛋下肚，是对自己十天的犒赏。","source":"《东京梦华录》记汴京晨市卖熟鸡蛋。"},{"text":"一文不动全攒着","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"攒是攒下了，只是人绷得像根弦。","source":"《东京梦华录》记汴京晨市卖熟鸡蛋。"}],"difficulty":1,"npc":[],"foreshadow":"checkpoint 收官：立足小成"},{"id":"E-010-戌","branch":"E","stage":1,"day":10,"shichen":"戌时","checkpoint":"立足小成·二","scene":"夜里你躺在小屋里，听着州桥方向的市声。十天前你在桥洞边挨冻，十天后你有了家、有了活、有了盘算。","options":[{"text":"对木梳说说心里话","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「娘，汴京很大，容得下一双肯做事的手。」","source":"《东京梦华录》记汴京百业兴旺之盛。"},{"text":"写封寄不出的信","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"字歪歪扭扭，写完压在枕下，心里敞亮。","source":"宋代民间书信多为口述代笔。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"全线题眼第一次点出"},{"id":"E-010-未","branch":"E","stage":1,"day":10,"shichen":"未时","checkpoint":"立足小成·三","scene":"大嫂拉你到桥边一处空档：「这儿夜里人流最旺，我瞧着，你支个小食摊正合适。敢不敢？」","options":[{"text":"动心，先算笔账","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"本钱、家伙、食材……墙皮上列了一排数。","source":"《东京梦华录》记州桥夜市摊点密布。"},{"text":"摆手，摆摊风险大","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大嫂也不劝：「想通了随时来找我。」","source":"《东京梦华录》记州桥夜市摊点密布。"}],"difficulty":2,"npc":["邻摊大嫂"],"foreshadow":"摆摊的念头落了地"},{"id":"E-011","branch":"E","stage":1,"day":11,"shichen":"辰时","checkpoint":"支摊首日","scene":"你取出三贯钱中的一贯，置办小泥炉、铁锅、竹签和两张矮凳。大嫂陪你置办了一上午，分文没要。","options":[{"text":"给大嫂带份点心","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"一包蜜煎果子，大嫂笑得眼睛眯成缝。","source":"《东京梦华录》记汴京果子行所售蜜煎。"},{"text":"省着，开张要紧","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"钱是省了，回头想谢，反倒不知从何谢起。","source":"《东京梦华录》记汴京果子行所售蜜煎。"}],"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"三贯钱第一次动用"},{"id":"E-011-戌","branch":"E","stage":1,"day":11,"shichen":"戌时","checkpoint":"支摊首日·二","scene":"夜市开摊。你支起小炉，炭火噼啪。头一个客人要了俩炊饼，你收钱的手有点抖，铜钱碰得叮当响。","options":[{"text":"多送一碟酱菜","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"客人一愣，笑了：「这小摊，会来事。」","source":"《东京梦华录》记食摊多佐以酱菜。"},{"text":"规规矩矩收钱递饼","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"本分开张，第一晚卖出十七个饼。","source":"《东京梦华录》记食摊多佐以酱菜。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"checkpoint 收官：支摊首日"},{"id":"E-011-未","branch":"E","stage":1,"day":11,"shichen":"未时","checkpoint":"支摊首日·三","scene":"试灶。第一锅炊饼烙得外圈焦黑，中间还生。小豆子蹲在边上，很给面子地啃了一个：「糊的香！」","options":[{"text":"反复试，摸清火候","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"烙到第七个，饼面金黄起酥，成了。","source":"宋代炊饼以炉烙制，火候为先。"},{"text":"凑合着开张再说","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"手艺是摊子的命，凑合不得——你心里清楚。","source":"宋代炊饼以炉烙制，火候为先。"}],"difficulty":2,"npc":["小豆子"],"foreshadow":"炊饼手艺是安身立命的本钱"},{"id":"E-012","branch":"E","stage":1,"day":12,"shichen":"辰时","checkpoint":"摆摊起色","scene":"一早去肉行买羊肠，摊主看你面生，报的价却比旁人高两成，还说是「时价如此」。","options":[{"text":"先比价再回头谈","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"问了三家回来，摊主讪讪地按实价称了。","source":"宋代肉行由行户定价，外来者常被欺生。"},{"text":"认下，怕得罪人","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"多花了三十文，滋味比羊肠还苦。","source":"宋代肉行由行户定价，外来者常被欺生。"}],"difficulty":2,"npc":["肉行摊主"],"foreshadow":"进货渠道立稳，成本才压得住"},{"id":"E-012-戌","branch":"E","stage":1,"day":12,"shichen":"戌时","checkpoint":"摆摊起色·二","scene":"七郎下工路过你的摊，站着看了半天，要了一份羊白肠。吃完憋出一句：「比我煎的好。」","options":[{"text":"说是偷师他的","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「师父教得好。」他耳根红了，转身走得飞快。","source":"《东京梦华录》记州桥夜市食摊之盛。"},{"text":"多给他加一份","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「抵那碗汤。」他捧着，半天没动筷。","source":"《东京梦华录》记州桥夜市食摊之盛。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"以肠还汤，旧账清出新意"},{"id":"E-012-未","branch":"E","stage":1,"day":12,"shichen":"未时","checkpoint":"摆摊起色·三","scene":"午后备料，你照记忆里七郎那碟旋煎羊白肠的做法试做：灌、煮、煎。第三锅时，香气把陈伯引来了。","options":[{"text":"请陈伯尝了指点","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「火候对了，煎前抹层薄油更脆。」果然！","source":"《东京梦华录》记旋煎羊白肠为州桥名吃。"},{"text":"自己闷头琢磨","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"试了六锅才摸到门道，多费了两斤肠。","source":"《东京梦华录》记旋煎羊白肠为州桥名吃。"}],"difficulty":2,"npc":["老仆陈伯"],"foreshadow":"招牌菜成型"},{"id":"E-013","branch":"E","stage":1,"day":13,"shichen":"辰时","checkpoint":"摆摊起色·四","scene":"开张第三天，回头客来了。一个轿夫熟门熟路坐下：「昨儿那饼，再烙俩，多搁葱花。」","options":[{"text":"记住老客的口味","correct":true,"tags":["才华"],"dims":{"才华":1,"名声":1},"feedback":"谁吃咸谁吃淡记在心里，回头客越来越多。","source":"宋代食摊以熟客为经营之本。"},{"text":"一视同仁按常例做","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"饼不差，可客人要的正是那份被记着。","source":"宋代食摊以熟客为经营之本。"}],"difficulty":2,"npc":[],"foreshadow":"老客名册，是她最软的护城河"},{"id":"E-013-戌","branch":"E","stage":1,"day":13,"shichen":"戌时","checkpoint":"摆摊起色·五","scene":"收摊数钱，今夜净入八十三文。小豆子帮你搬凳子，你往他手里塞了五文跑腿钱，他蹦得老高。","options":[{"text":"让他明晚还来帮忙","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子有了正经营生，眼睛比灯还亮。","source":"《东京梦华录》记市井小儿常受雇跑腿。"},{"text":"嘱咐他别乱花钱","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"说教出口你就后悔了——他比你会过日子。","source":"《东京梦华录》记市井小儿常受雇跑腿。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"小豆子成了摊上的固定帮手"},{"id":"E-013-未","branch":"E","stage":1,"day":13,"shichen":"未时","checkpoint":"摆摊起色·六","scene":"浆洗的活和摊子的活撞在了一起。掌柜娘子倒痛快：「洗衣裳什么时候都行，摊子别误了夜市。」","options":[{"text":"谢过，把活排开","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"白天浆洗夜里出摊，累，但两份进项。","source":"宋代市井妇人多兼数职以谋生。"},{"text":"辞了浆洗专心摆摊","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"摊子刚起步，断了后路，夜里睡不稳。","source":"宋代市井妇人多兼数职以谋生。"}],"difficulty":2,"npc":["掌柜娘子"],"foreshadow":"多条进项，是抗风险的底"},{"id":"E-014","branch":"E","stage":1,"day":14,"shichen":"辰时","checkpoint":"摆摊起色·七","scene":"舅家遣人传话：舅老爷回京了，让你「得空过去一趟」。传话的婆子撇着嘴，像施舍什么。","options":[{"text":"备份薄礼，自己去","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"礼不重，但你如今是自己挣钱的人。","source":"宋人笔记记亲戚往来重礼数轻情分。"},{"text":"托词忙，先不去","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"躲得了一时，落了个'不懂事'的名声。","source":"宋人笔记记亲戚往来重礼数轻情分。"}],"difficulty":2,"npc":["舅家婆子"],"foreshadow":"舅家这条线开始收紧"},{"id":"E-014-戌","branch":"E","stage":1,"day":14,"shichen":"戌时","checkpoint":"摆摊起色·八","scene":"从舅家出来，天落起小雨。你回到摊前，炉里的炭还旺着，七郎竟蹲在那儿帮你看着火，蓑衣都没披。","options":[{"text":"把伞往他那边倾","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「淋不着。」他说。两人肩碰着肩看火。","source":"《东京梦华录》记汴京夜雨市声不绝。"},{"text":"问他怎么来了","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「路过。」炭火噼啪，谁也没拆穿谁。","source":"《东京梦华录》记汴京夜雨市声不绝。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"雨夜看火，情愫无声"},{"id":"E-014-未","branch":"E","stage":1,"day":14,"shichen":"未时","checkpoint":"摆摊起色·九","scene":"舅父见了你，听说你在夜市摆摊，眉头拧起来：「女孩子家抛头露面，成何体统。好歹是亲戚……」","options":[{"text":"不卑不亢，说明缘由","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「甥女凭手艺吃饭，不辱没谁。」他噎住了。","source":"宋代市井女子经营买卖者比比皆是。"},{"text":"低头认错，求他帮衬","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"他赏了两百文，话里话外却是打发。","source":"宋代市井女子经营买卖者比比皆是。"}],"difficulty":3,"npc":["舅父"],"foreshadow":"嫌贫翻脸，这次只是序曲"},{"id":"E-015","branch":"E","stage":1,"day":15,"shichen":"辰时","checkpoint":"汤饼之约","scene":"大嫂跟你咬耳朵：州桥东边空出个夜市好位子，原来摆摊的老头回乡了，先到先得。","options":[{"text":"当机立断去占位子","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"好口岸客流翻倍，这一步棋走对了。","source":"《东京梦华录》记州桥夜市摊地紧俏。"},{"text":"念旧，守着老地方","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"位子当天就被别人占了，只能等下回。","source":"《东京梦华录》记州桥夜市摊地紧俏。"}],"difficulty":2,"npc":["邻摊大嫂"],"foreshadow":"新口岸，生意要上台阶"},{"id":"E-015-戌","branch":"E","stage":1,"day":15,"shichen":"戌时","checkpoint":"汤饼之约·二","scene":"新摊子第一晚，收摊时夜已深。七郎端来两碗热汤饼：「我家灶上剩的高汤，别糟蹋了。」汤面上浮着葱花。","options":[{"text":"接过，慢慢喝完","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"汤很热，一路暖到心里。这算一个约定了。","source":"《东京梦华录》记夜市汤饼为常食。"},{"text":"约他往后常来尝新","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「我做新品，你来试。」他重重点头：「欸！」","source":"《东京梦华录》记夜市汤饼为常食。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"checkpoint 收官：汤饼之约"},{"id":"E-015-未","branch":"E","stage":1,"day":15,"shichen":"未时","checkpoint":"汤饼之约·三","scene":"七郎休假，竟来帮你搬炉子挪摊，扛东西闷着头干，汗水浸透了后背。大嫂在一旁直笑。","options":[{"text":"烙最好的饼犒劳他","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"葱花烙饼夹羊肠，他吃得头也不抬。","source":"《东京梦华录》记食摊以热食待客。"},{"text":"付他工钱，两清","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他捏着钱愣了半天，默默塞回你钱匣。","source":"《东京梦华录》记食摊以热食待客。"}],"difficulty":1,"npc":["陈七郎","邻摊大嫂"],"foreshadow":"帮工的情分，工钱算不清"},{"id":"E-016","branch":"E","stage":1,"day":16,"shichen":"辰时","checkpoint":"相知渐深","scene":"新口岸果然旺。天没亮你就起来和面，小豆子跑腿买来了头茬的葱，绿得冒水。","options":[{"text":"添样新品试试水","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"炊饼夹馓子，酥上加脆，老客都说妙。","source":"《东京梦华录》记汴京食摊竞相出新。"},{"text":"守住老三样不动","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"稳是稳，可夜市的嘴，是最喜新厌旧的。","source":"《东京梦华录》记汴京食摊竞相出新。"}],"difficulty":2,"npc":["小豆子"],"foreshadow":"摊子的口碑开始往外传"},{"id":"E-016-戌","branch":"E","stage":1,"day":16,"shichen":"戌时","checkpoint":"相知渐深·二","scene":"夜市里有人弹琵琶唱小词，唱的是汴京的灯与桥。你一面翻饼一面听，客人们都不急着走。","options":[{"text":"赏唱曲的两文钱","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"艺人冲你遥遥一拜，摊前人气更聚了。","source":"《东京梦华录》记夜市有路岐人卖艺。"},{"text":"听完继续忙生意","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"曲子在耳边，饼在手里，各有各的圆满。","source":"《东京梦华录》记夜市有路岐人卖艺。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"夜市声色，是苦日子里的一点甜"},{"id":"E-016-未","branch":"E","stage":1,"day":16,"shichen":"未时","checkpoint":"相知渐深·三","scene":"脚店的掌柜嫌七郎嘴笨不会揽客，扣了他工钱。他蹲在后门台阶上择菜，闷得像块石头。","options":[{"text":"陪他坐会，不多问","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"你择一半他择一半。菜择完，他眉头松了。","source":"宋代脚店佣工受克扣，笔记屡见。"},{"text":"替他去找掌柜理论","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"掌柜冷笑，七郎反倒被数落得抬不起头。","source":"宋代脚店佣工受克扣，笔记屡见。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"七郎与脚店东家积怨的种子"},{"id":"E-017","branch":"E","stage":1,"day":17,"shichen":"辰时","checkpoint":"相知渐深·四","scene":"下了一夜雨，早市人少。你正发愁今日食材要剩，绸缎庄管事娘子来订二十个炊饼，给庄里伙计做晌饭。","options":[{"text":"接下，按时送上门","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"热饼准时到，庄里说以后常订。","source":"宋代商铺向食摊订食，市井常事。"},{"text":"怕摊子走不开，推了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"稳妥地错过了一条长期的进项。","source":"宋代商铺向食摊订食，市井常事。"}],"difficulty":2,"npc":["管事娘子"],"foreshadow":"订食生意，旱涝保收的一条线"},{"id":"E-017-戌","branch":"E","stage":1,"day":17,"shichen":"戌时","checkpoint":"相知渐深·五","scene":"收摊后，你和他并排坐在桥头石阶上歇脚。他说起家乡的麦子，你说起娘的木梳，谁都没提明天。","options":[{"text":"静静听他说完","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"话不多的人肯讲旧事，是把心打开了一条缝。","source":"宋人笔记多言市井儿女朴拙之情。"},{"text":"也讲讲你的来路","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"说到投亲不遇，他没接话，只把凳子挪近了些。","source":"宋人笔记多言市井儿女朴拙之情。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"桥头夜话，心事互通"},{"id":"E-017-未","branch":"E","stage":1,"day":17,"shichen":"未时","checkpoint":"相知渐深·六","scene":"七郎休工，在你摊前转了三圈，最后憋出一句：「你那个泥炉……火力不均。我给你改改。」","options":[{"text":"由他动手，打下手","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"一下午敲敲打打，炉膛果然旺得均匀了。","source":"宋代炉具改造，市井匠人常为之。"},{"text":"客气推辞，怕麻烦他","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他「哦」了一声，走的时候肩膀垮着。","source":"宋代炉具改造，市井匠人常为之。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"这只改过的炉子，是定情前的信物"},{"id":"E-018","branch":"E","stage":1,"day":18,"shichen":"辰时","checkpoint":"相知渐深·七","scene":"东街来了个挑担子卖旋煎羊白肠的，价压得比你低两文，摊子前敲锣吆喝，声势很响。","options":[{"text":"不比价，比手艺","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你多煎半分火候，老客尝得出，没走。","source":"《东京梦华录》记州桥同业食摊相竞。"},{"text":"跟着降价抢客","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"薄利伤本，人还累得慌，不值当。","source":"《东京梦华录》记州桥同业食摊相竞。"}],"difficulty":2,"npc":[],"foreshadow":"竞争是夜市常态，守住本心"},{"id":"E-018-戌","branch":"E","stage":1,"day":18,"shichen":"戌时","checkpoint":"相知渐深·八","scene":"今夜生意格外好，饼卖空了，羊肠也见了底。小豆子帮你数钱，数到一半忘了数，又从头来。","options":[{"text":"多给他买个糖瓜","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子举着糖瓜满桥跑，笑声撒了一路。","source":"《东京梦华录》记夜市卖糖瓜蜜饯。"},{"text":"教他重新数一遍","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"数清了，一百四十文。两人都挺得意。","source":"《东京梦华录》记夜市卖糖瓜蜜饯。"}],"flavor":true,"difficulty":1,"npc":["小豆子"],"foreshadow":"进项破百，日子眼见亮堂"},{"id":"E-018-未","branch":"E","stage":1,"day":18,"shichen":"未时","checkpoint":"相知渐深·九","scene":"大嫂悄悄告诉你：那挑担的是外地来的，羊肠是用前一天的剩货做的，吃坏了两个客人，正被人堵着理论。","options":[{"text":"不落井下石，照常经营","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"看客散了，你的摊前反倒排起了队。","source":"宋代市井重商誉，货真价实者立。"},{"text":"趁机吆喝招揽客人","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"客是来了几个，大嫂看你的眼神淡了。","source":"宋代市井重商誉，货真价实者立。"}],"difficulty":2,"npc":["邻摊大嫂"],"foreshadow":"货真价实四个字，值千金"},{"id":"E-019","branch":"E","stage":1,"day":19,"shichen":"辰时","checkpoint":"相知渐深·十","scene":"脚店东家要辞陈伯，说他老了洗不动碗。陈伯收拾包袱时，手抖得系不上绳。","options":[{"text":"留陈伯来摊上帮工","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「老伯替我守着摊，工钱照算。」他眼圈红了。","source":"宋代市井老佣被辞，晚景多艰。"},{"text":"送些钱，另作打算","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"钱他没收，背影比来时更佝偻了。","source":"宋代市井老佣被辞，晚景多艰。"}],"difficulty":2,"npc":["老仆陈伯"],"foreshadow":"陈伯入伙，摊子添了主心骨"},{"id":"E-019-戌","branch":"E","stage":1,"day":19,"shichen":"戌时","checkpoint":"相知渐深·十一","scene":"七郎听说你收了陈伯，下工后默默扛来一袋炭：「人多费火。」放下就走，又折回来：「……缺什么言语一声。」","options":[{"text":"点头，记在心里","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"炭在炉里烧得噼啪，像有人替你壮胆。","source":"宋代市井炭以袋计，为常用之礼。"},{"text":"笑他：你自己呢","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「我……我也快不缺了。」他挠头，话说一半。","source":"宋代市井炭以袋计，为常用之礼。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"七郎似有自立门户的念头"},{"id":"E-019-未","branch":"E","stage":1,"day":19,"shichen":"未时","checkpoint":"相知渐深·十二","scene":"舅家又来了人，这回是表姐要出嫁，让你去「帮几天忙」——说是帮忙，实则是去做不要钱的粗使。","options":[{"text":"送份贺礼，人不到","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"礼到心到，但你的一双手是自己的。","source":"宋人笔记记富亲役使穷亲之态。"},{"text":"抹不开面子，去了","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"忙了三天，连席面都没让你上。","source":"宋人笔记记富亲役使穷亲之态。"}],"difficulty":3,"npc":["舅家婆子"],"foreshadow":"与舅家的情分，只剩礼数了"},{"id":"E-020","branch":"E","stage":1,"day":20,"shichen":"辰时","checkpoint":"相知渐深·十三","scene":"进城二十天。摊上一炉一锅两个人，墙皮上的账越过一贯。你给木梳换了根新红绳。","options":[{"text":"给娘上炷香","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"庙里香烟袅袅，你把近况一桩桩说给她听。","source":"《东京梦华录》记汴京寺观香火之盛。"},{"text":"照常出工不声张","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"心里的话憋着，揉面时格外用力。","source":"《东京梦华录》记汴京寺观香火之盛。"}],"difficulty":1,"npc":[],"foreshadow":"checkpoint 收官前的喘息"},{"id":"E-020-戌","branch":"E","stage":1,"day":20,"shichen":"戌时","checkpoint":"相知渐深·十四","scene":"收摊时七郎送你回柴房，一路无话。到门口他忽然说：「周三郎那边……你夜里收摊早些。」","options":[{"text":"应下，让他也小心","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「嗯。」他站在巷口，看你关了门才走。","source":"宋代夜市三更方散，归途常有宵小。"},{"text":"嘴硬说我不怕","correct":true,"tags":["感情","自主"],"dims":{"情缘":1,"自主":1},"feedback":"「我怕。」他答得太快，你俩都愣住了。","source":"宋代夜市三更方散，归途常有宵小。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"「我怕」二字，胜过千句情话"},{"id":"E-020-未","branch":"E","stage":1,"day":20,"shichen":"未时","checkpoint":"相知渐深·十五","scene":"州桥一带的地痞周三郎，带着两个闲汉在夜市晃荡，挨个摊子「收平安钱」，收到大嫂摊前。","options":[{"text":"记下此事，早作防备","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"大嫂咬着牙交了钱：「迟早收到你头上。」","source":"宋代市井泼皮收'买路钱'，笔记屡见。"},{"text":"事不关己，低头干活","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你看在眼里，心里发沉——躲是躲不掉的。","source":"宋代市井泼皮收'买路钱'，笔记屡见。"}],"difficulty":2,"npc":["周三郎","邻摊大嫂"],"foreshadow":"地痞发难，已在弦上"},{"id":"E-021","branch":"E","stage":1,"day":21,"shichen":"辰时","checkpoint":"地痞发难","scene":"一早，周三郎晃到你摊前，拿竹签剔着牙：「小娘子，这条街的规矩，一晚上三十文，保你平安。」","options":[{"text":"不软不硬，拖一天","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「容我凑凑。」他冷笑应了。你赢得一日喘息。","source":"宋代市井对泼皮多以拖延周旋为先。"},{"text":"当场交钱买平安","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"钱一出手，就等于认下了这无底洞。","source":"宋代市井对泼皮多以拖延周旋为先。"}],"difficulty":3,"npc":["周三郎"],"foreshadow":"硬顶不行，交钱不甘，需寻门路"},{"id":"E-021-戌","branch":"E","stage":1,"day":21,"shichen":"戌时","checkpoint":"地痞发难·二","scene":"夜里出摊，你多留了个心眼，让小豆子留意周三郎一伙的动向，哪几家交了钱、几时来的，都记下。","options":[{"text":"让各摊受害的联个名","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"大嫂第一个按了手印，又有两家跟上。","source":"宋代诉讼重众证，联名状常有。"},{"text":"独自硬扛，不连累人","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"骨气可嘉，可一个人斗不过一条街的地痞。","source":"宋代诉讼重众证，联名状常有。"}],"difficulty":3,"npc":["小豆子","邻摊大嫂"],"foreshadow":"联名状，是后文反击的刀"},{"id":"E-021-未","branch":"E","stage":1,"day":21,"shichen":"未时","checkpoint":"地痞发难·三","scene":"你向大嫂和陈伯讨主意。陈伯压低声音：「州桥归左军巡院管，巡铺的虞候，最恨泼皮坏街面生意。」","options":[{"text":"记下路子，先忍一时","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"官府这条路要攒齐人证物证，急不得。","source":"《东京梦华录》记汴京设军巡铺维护市警。"},{"text":"今晚就去拦虞候喊冤","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"无凭无据，虞候只当你妇人聒噪。","source":"《东京梦华录》记汴京设军巡铺维护市警。"}],"difficulty":3,"npc":["老仆陈伯","邻摊大嫂"],"foreshadow":"军巡铺虞候，是破局关键"},{"id":"E-022","branch":"E","stage":1,"day":22,"shichen":"辰时","checkpoint":"地痞发难·四","scene":"周三郎等得不耐烦，带人来你摊前「捧场」：掀了凳子，踢翻酱菜碟，客人吓得全跑了。","options":[{"text":"护住炉子，记清人数","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"炉没倒，家底就在。几个人的脸你都记住了。","source":"宋人笔记记泼皮滋事，事主多隐忍取证。"},{"text":"抄起烧火棍拼命","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你一个女子对三个闲汉，胳膊被拧得生疼。","source":"宋人笔记记泼皮滋事，事主多隐忍取证。"}],"difficulty":3,"npc":["周三郎"],"foreshadow":"摊子被掀，是第一记重挫"},{"id":"E-022-戌","branch":"E","stage":1,"day":22,"shichen":"戌时","checkpoint":"地痞发难·五","scene":"夜里你没出摊。小屋里点着油灯，大嫂、陈伯、小豆子都来了，挤了满满一屋子。大嫂把一碗热汤塞你手里。","options":[{"text":"把各家证据凑一处","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"时辰、人数、钱数，一条条对上了。","source":"宋代告状需备事实人证，方得受理。"},{"text":"先让大家宽心吃饭","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"一屋子人分一锅粥，倒像是过年了。","source":"宋代告状需备事实人证，方得受理。"}],"flavor":true,"difficulty":1,"npc":["邻摊大嫂","老仆陈伯","小豆子"],"foreshadow":"这间柴房，是她的'衙门'"},{"id":"E-022-未","branch":"E","stage":1,"day":22,"shichen":"未时","checkpoint":"地痞发难·六","scene":"摊子被搅了，今日颗粒无收。你蹲在桥边收拾残局，七郎闻讯赶来，一言不发帮你修被踹坏的矮凳。","options":[{"text":"让他陪着，一起收拾","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"他钉凳子你刷锅，谁也没说丧气话。","source":"宋代市井相扶，患难见真情。"},{"text":"推他走，怕他惹事","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他站在三步外不肯走，你心里又酸又暖。","source":"宋代市井相扶，患难见真情。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"患难之中，情分愈真"},{"id":"E-023","branch":"E","stage":1,"day":23,"shichen":"辰时","checkpoint":"地痞发难·七","scene":"联名状递到了军巡铺。虞候看完，捻着胡须说：「人证物证都有了，可周三郎背后有人，你们要有打持久仗的准备。」","options":[{"text":"应下，回去稳住阵脚","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"至少官府接了状子，就不是没处讲理了。","source":"宋代军巡铺受理市井治安词讼。"},{"text":"追问何时拿人","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"虞候沉了脸——催官办案，是大忌。","source":"宋代军巡铺受理市井治安词讼。"}],"difficulty":3,"npc":["虞候"],"foreshadow":"官府已立案，但风浪未平"},{"id":"E-023-戌","branch":"E","stage":1,"day":23,"shichen":"戌时","checkpoint":"地痞发难·八","scene":"出城进货回来天已黑透，累得两条腿像灌了醋。桥头有盏灯，七郎提着，一句话没说，接过你肩上的担子。","options":[{"text":"让他担着，并肩走","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"担子换了肩，一路都没换回来。","source":"宋代夜市归人，提灯相候为常情。"},{"text":"灯下看清他的脸","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"灯火一晃一晃，他眼底的担心藏不住。","source":"宋代夜市归人，提灯相候为常情。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"提灯接人，心意已是明牌"},{"id":"E-023-未","branch":"E","stage":1,"day":23,"shichen":"未时","checkpoint":"地痞发难·九","scene":"周三郎听说你告了官，放出话来：「叫她这摊子开不下去。」肉行、炭行都不敢再卖货给你了。","options":[{"text":"出城寻别的货源","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"多走十里路到南熏门外进货，断了他的锁。","source":"宋代汴京四郊皆有集市货源。"},{"text":"囤货硬撑等风头过","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"存粮只够三天，坐吃山空最熬人。","source":"宋代汴京四郊皆有集市货源。"}],"difficulty":3,"npc":[],"foreshadow":"城外货源，歪打正着更便宜"},{"id":"E-024","branch":"E","stage":1,"day":24,"shichen":"辰时","checkpoint":"地痞发难·十","scene":"摊子照常支起来了——地痞再横，也横不过饿肚子。老客们听说缘由，竟比往常来得更多。","options":[{"text":"照常做，不加价不卖惨","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「饼还是那价。」客人吃完，都多留了几文。","source":"宋代市井以义相高，舆论自有公断。"},{"text":"挂出被欺压的招牌","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"同情换得一时，长久还得靠饼香。","source":"宋代市井以义相高，舆论自有公断。"}],"difficulty":2,"npc":[],"foreshadow":"民心这杆秤，开始偏向她"},{"id":"E-024-戌","branch":"E","stage":1,"day":24,"shichen":"戌时","checkpoint":"地痞发难·十一","scene":"大战前夜。你把摊子擦得干干净净，炭添得足足的。七郎送来一坛他腌的辣菜：「明日……我请了半天假。」","options":[{"text":"明白他的意思","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"公堂在街心，他要站在人群最前头。","source":"宋代当街勘问，围观者众。"},{"text":"让他别来，怕连累","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「我站着，不吭声。」他把坛子抱得更紧。","source":"宋代当街勘问，围观者众。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"明日勘问，他要在场"},{"id":"E-024-未","branch":"E","stage":1,"day":24,"shichen":"未时","checkpoint":"地痞发难·十二","scene":"虞候差人来传话：三日后巡检司当街勘问，叫联名各户都到场作证。大嫂紧张得直搓手。","options":[{"text":"陪各户对好说辞","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"谁家何时交了多少，一条条捋顺了。","source":"宋代勘问重口供一致，串供则败。"},{"text":"反正有理，临时再说","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"公堂上七嘴八舌，最易被人抓住漏洞。","source":"宋代勘问重口供一致，串供则败。"}],"difficulty":3,"npc":["邻摊大嫂","虞候差人"],"foreshadow":"三日后勘问，决战在即"},{"id":"E-025","branch":"E","stage":1,"day":25,"shichen":"辰时","checkpoint":"阶段一收官","scene":"勘问这日，州桥街心围得水泄不通。周三郎被押上来时还梗着脖子，一见联名状和齐刷刷的人证，蔫了。","options":[{"text":"如实陈词，不添不缩","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"句句是实，虞候当场判他还钱、罚杖、逐出。","source":"宋代对市井泼皮有杖责、编管之罚。"},{"text":"趁机痛骂他一场","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"骂是痛快，虞候皱眉：公堂不是撒气处。","source":"宋代对市井泼皮有杖责、编管之罚。"}],"difficulty":3,"npc":["周三郎","虞候"],"foreshadow":"周三郎背后的人，还没露头"},{"id":"E-025-戌","branch":"E","stage":1,"day":25,"shichen":"戌时","checkpoint":"阶段一收官·二","scene":"入夜，摊子前的灯笼亮堂堂。七郎帮你收摊，忽然说：「等攒够了钱，我想自己开个小食店。」说完飞快看你一眼。","options":[{"text":"说：我给你打下手","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"他猛地停手，灯笼的光在你俩之间晃了晃。","source":"宋代市井合伙开店，夫妇经营常见。"},{"text":"笑他志向不小","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「不大。」他看着你的炉子，「两个人正好。」","source":"宋代市井合伙开店，夫妇经营常见。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"stage2 暗线：合开一家食店"},{"id":"E-025-未","branch":"E","stage":1,"day":25,"shichen":"未时","checkpoint":"阶段一收官·三","scene":"散场后，各摊主凑钱要在脚店摆一桌谢你。你摆摆手，最后只说：「往后谁家有事，言语一声。」","options":[{"text":"把钱退了，领情就好","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"「州桥小娘子」的名号，这天传开了。","source":"宋代市井重义名，德望即资本。"},{"text":"收下钱贴补损失","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"钱该收，可众人眼里的光，淡了些。","source":"宋代市井重义名，德望即资本。"}],"difficulty":2,"npc":["邻摊大嫂","老仆陈伯"],"foreshadow":"'州桥小娘子'名号，stage2 的阶梯"},{"id":"E-026","branch":"E","stage":2,"day":26,"shichen":"辰时","checkpoint":"名号渐响","scene":"胜诉后第一天出摊，天没亮摊前就排上了队。有人专程从马行街过来：「尝尝州桥小娘子的饼。」","options":[{"text":"趁热加量备料","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"多和了两盆面，不到二更全卖空。","source":"《东京梦华录》记名食摊客络绎不绝。"},{"text":"照旧分量，稳着来","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"早早售罄，排队的客人散了，可惜。","source":"《东京梦华录》记名食摊客络绎不绝。"}],"difficulty":2,"npc":[],"foreshadow":"名气来了，要接得住才算数"},{"id":"E-026-戌","branch":"E","stage":2,"day":26,"shichen":"戌时","checkpoint":"名号渐响·二","scene":"收摊路上，七郎照旧提着灯等你。你说了白天那伙人的事，他沉默半晌：「周三郎进去前，就是跟他混的。」","options":[{"text":"记下孙三这个名字","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"敌在明处了，反倒没那么怕。","source":"宋人笔记记市井牙人盘结账面之事。"},{"text":"说以后多绕路走","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"躲得开人，躲不开事——你心里明白。","source":"宋人笔记记市井牙人盘结账面之事。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"牙人孙三，本阶段的主要对手"},{"id":"E-026-未","branch":"E","stage":2,"day":26,"shichen":"未时","checkpoint":"名号渐响·三","scene":"几个穿绸衫的闲汉在摊前晃，为首的瘦高个眯眼打量你的炉子：「小娘子最近，风头很劲啊。」","options":[{"text":"装不懂，照常做生意","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"不搭话不示弱，他讨了个没趣，走了。","source":"宋代街市牙人闲汉结伙生事，笔记屡见。"},{"text":"请他吃饼套近乎","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"饼他吃了，临走撂下一句「识相就好」。","source":"宋代街市牙人闲汉结伙生事，笔记屡见。"}],"difficulty":2,"npc":["牙人孙三"],"foreshadow":"周三郎背后的人露头了"},{"id":"E-027","branch":"E","stage":2,"day":27,"shichen":"辰时","checkpoint":"名号渐响·四","scene":"陈伯一早去进炭，回来时脸色不对：炭行的伙计支支吾吾，说炭价「涨了」，只有你的摊子涨。","options":[{"text":"查明是孙三打了招呼","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"不吵不闹，城外货源上次已经趟出来了。","source":"宋代行户受牙人把持，操纵物价常见。"},{"text":"找炭行理论","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"伙计两手一摊：「行里的规矩，找谁理论？」","source":"宋代行户受牙人把持，操纵物价常见。"}],"difficulty":3,"npc":["老仆陈伯"],"foreshadow":"孙三的打法：掐货源，不动手"},{"id":"E-027-戌","branch":"E","stage":2,"day":27,"shichen":"戌时","checkpoint":"名号渐响·五","scene":"夜里摊照旧支着。七郎下工后绕过来，把一小包东西塞进你钱匣底下：「我攒的。万一要用钱……别跟我客气。」","options":[{"text":"收下，记一笔账","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"墙皮账上多了一栏：七郎，八十文。他看见了，傻笑。","source":"宋代市井相知者互通缓急，称'周济'。"},{"text":"推回去让他自己攒","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「我的就是你的。」他说完自己先红了脸。","source":"宋代市井相知者互通缓急，称'周济'。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"合开食店的本钱，从他这八十文起"},{"id":"E-027-未","branch":"E","stage":2,"day":27,"shichen":"未时","checkpoint":"名号渐响·六","scene":"大嫂拉着你在茶坊坐下：「孙三是街市上有名的掮客，欺行霸市惯了。硬碰不行，得想软的法子。」","options":[{"text":"摸清他的营生软肋","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"让小豆子去打听：他靠什么吃饭，怕什么。","source":"宋代市井相争，先探底细再出手。"},{"text":"再告一次官","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孙三没动手没收钱，官府拿他没办法。","source":"宋代市井相争，先探底细再出手。"}],"difficulty":3,"npc":["邻摊大嫂","小豆子"],"foreshadow":"对孙三，打的是情报战"},{"id":"E-028","branch":"E","stage":2,"day":28,"shichen":"辰时","checkpoint":"名号渐响·七","scene":"小豆子带回了消息：孙三表面做牙人生意，暗地里放印子钱，好几家摊主都欠着他的债，利滚利。","options":[{"text":"记下欠债的都是谁","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"欠印子钱的人，是最恨他的人。","source":"宋代高利贷称'印子钱'，官府屡禁。"},{"text":"只管好自己摊子","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"消息烂在肚子里，等于白打听一场。","source":"宋代高利贷称'印子钱'，官府屡禁。"}],"difficulty":3,"npc":["小豆子"],"foreshadow":"印子钱，是孙三的死穴"},{"id":"E-028-戌","branch":"E","stage":2,"day":28,"shichen":"戌时","checkpoint":"名号渐响·八","scene":"婆子走后你心里堵。出摊时手一抖，一屉饼烙过了火。老客尝出来，只说：「小娘子今日有心事？饼焦了也香。」","options":[{"text":"赔笑重做一屉","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"重做的不收钱，老客反倒多留了几文。","source":"宋代食摊重口碑，失手即补为常例。"},{"text":"跟大家说说烦心事","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"听完众人义愤：「摊不许收！我们都来！」","source":"宋代食摊重口碑，失手即补为常例。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"街坊是她最大的靠山"},{"id":"E-028-未","branch":"E","stage":2,"day":28,"shichen":"未时","checkpoint":"名号渐响·九","scene":"舅家又遣婆子来，这回话说得难听：「老爷说了，亲戚家的姑娘在街上抛头露面，丢的是两家的脸。让你收了摊子，到府上做个针线丫鬟。」","options":[{"text":"婉拒：凭手艺吃饭","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「替我谢舅父美意。甥女的摊，是脸面不是丢人。」","source":"宋代市井女子自营生计者甚多。"},{"text":"撕破脸吵一场","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"痛快是痛快，落了个'顶撞尊长'的话柄。","source":"宋代市井女子自营生计者甚多。"}],"difficulty":3,"npc":["舅家婆子"],"foreshadow":"舅家翻脸，正式开场"},{"id":"E-029","branch":"E","stage":2,"day":29,"shichen":"辰时","checkpoint":"名号渐响·十","scene":"一早，孙三亲自踱到摊前，笑吟吟地：「小娘子，交个朋友。往后你的炭啊面啊，我帮你办，价钱好商量。」","options":[{"text":"笑着应下，只用一回","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"虚与委蛇，先看他出的价、走的道。","source":"宋代市井与牙人周旋，虚实相济。"},{"text":"一口回绝","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他笑容不变，眼神冷下来：「敬酒不吃。」","source":"宋代市井与牙人周旋，虚实相济。"}],"difficulty":3,"npc":["牙人孙三"],"foreshadow":"周旋开局：假意合作，暗中取证"},{"id":"E-029-戌","branch":"E","stage":2,"day":29,"shichen":"戌时","checkpoint":"名号渐响·十一","scene":"收摊后你把白天的事说给七郎听。他握着炉钩的手紧了紧：「跟这种人周旋……你别一个人去。」","options":[{"text":"应他：有事就叫你","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「随叫随到。」四个字，说得比灶火还稳。","source":"宋代市井相扶持，患难与共。"},{"text":"打趣他护得紧","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「那可不。」他理直气壮，你俩都笑了。","source":"宋代市井相扶持，患难与共。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"「随叫随到」，后文会兑现"},{"id":"E-029-未","branch":"E","stage":2,"day":29,"shichen":"未时","checkpoint":"名号渐响·十二","scene":"孙三办的炭送来了，价是比行里低，可一烧就知道——掺了碎炭末，火虚烟大。","options":[{"text":"留样记账，不动声色","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"碎炭封了一包存起来，账上记下日期斤两。","source":"宋代商事纠纷重物证，留存为要。"},{"text":"当场找他退换","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他痛快换了，可你的底牌也亮给他看了。","source":"宋代商事纠纷重物证，留存为要。"}],"difficulty":3,"npc":[],"foreshadow":"掺假的炭，是日后扳他的证物之一"},{"id":"E-030","branch":"E","stage":2,"day":30,"shichen":"辰时","checkpoint":"名号渐响·十三","scene":"满月盘账：摊子净入两贯三百文，加上工钱，手头的活钱过了三贯——比进城时全部家当还多。","options":[{"text":"留一贯做急用金","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"急用金单封存起来，逢事不慌。","source":"宋代小本经营者皆有留备之习。"},{"text":"全投进去扩摊子","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"摊子还没大到那份上，弦别绷太满。","source":"宋代小本经营者皆有留备之习。"}],"difficulty":2,"npc":[],"foreshadow":"checkpoint 收官：名号渐响"},{"id":"E-030-戌","branch":"E","stage":2,"day":30,"shichen":"戌时","checkpoint":"名号渐响·十四","scene":"三十天了。你站在州桥上，看灯火从自己摊前一直亮到桥那头的茶坊——那里也卖着你的饼。","options":[{"text":"给自己放个水灯","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"小小的灯顺水流走，像跟从前的自己道别。","source":"《东京梦华录》记汴水放灯之俗。"},{"text":"把账誊到纸上收好","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"墙皮上的字会掉，纸上的数能传下去。","source":"《东京梦华录》记汴水放灯之俗。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"阶段节点回望，心气更足"},{"id":"E-030-未","branch":"E","stage":2,"day":30,"shichen":"未时","checkpoint":"名号渐响·十五","scene":"掌柜娘子来摊前坐：「我家茶坊夜里想添个食档，你的手艺，愿不愿意把饼供到我店里？分成好说。」","options":[{"text":"应下，写清分成","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"炭条为凭，两家按三七分，多了一条稳进项。","source":"宋代合伙经营以契约为凭。"},{"text":"怕分薄了自己生意","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘子不恼：「想通了言语。」机会却凉了半截。","source":"宋代合伙经营以契约为凭。"}],"difficulty":2,"npc":["掌柜娘子"],"foreshadow":"茶坊供饼，'小娘子'进了店堂"},{"id":"E-031","branch":"E","stage":2,"day":31,"shichen":"辰时","checkpoint":"周旋布局","scene":"茶坊食档开张，头一晚就卖出去四十个饼。掌柜娘子笑：「这买卖成了，你家那摊子倒像是给茶坊打了个招牌。」","options":[{"text":"顺势再添一样汤品","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"饼配热汤，茶坊的客留得更久了。","source":"《东京梦华录》记茶坊兼营吃食。"},{"text":"守好饼这一味就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"稳是稳，可食档的势头还有富余。","source":"《东京梦华录》记茶坊兼营吃食。"}],"difficulty":2,"npc":["掌柜娘子"],"foreshadow":"食档试水，为将来食店练兵"},{"id":"E-031-戌","branch":"E","stage":2,"day":31,"shichen":"戌时","checkpoint":"周旋布局·二","scene":"夜里七郎帮你往茶坊送饼，回来的路上他忽然说：「掌柜今天跟我提了，说州桥有个小食店要盘出去。」","options":[{"text":"停下脚细问","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"一问才知道，他连价钱都替你打听好了。","source":"《东京梦华录》记脚店食店盘兑之俗。"},{"text":"说现在还太早","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他「哦」了一声，灯影里的脚步慢了半拍。","source":"《东京梦华录》记脚店食店盘兑之俗。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"盘店的念想，第一次说出口"},{"id":"E-031-未","branch":"E","stage":2,"day":31,"shichen":"未时","checkpoint":"周旋布局·三","scene":"欠孙三印子钱的卖花婆子被堵在巷口逼债，利钱滚到了本钱的双倍。她看见你，像看见救星。","options":[{"text":"记下债约的条目","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「官府禁过制取息。」婆子眼里有了光。","source":"宋代律令禁高利贷过制取息。"},{"text":"先借她钱还上","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你的钱填了无底洞，孙三只会放得更欢。","source":"宋代律令禁高利贷过制取息。"}],"difficulty":3,"npc":["卖花婆子"],"foreshadow":"印子钱的罪证，一条条在攒"},{"id":"E-032","branch":"E","stage":2,"day":32,"shichen":"辰时","checkpoint":"周旋布局·四","scene":"一大早，舅父亲自来了——没进摊，站在五步外看你烙饼，看了一刻钟，临走撂下一句：「手艺倒不赖。可惜了。」","options":[{"text":"不追不问，继续烙饼","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"他那句'可惜'，可惜的是你不肯低头。","source":"宋人笔记记富亲心态，俯视穷亲。"},{"text":"追上去问个明白","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他上了轿，帘子一放，把你晾在街心。","source":"宋人笔记记富亲心态，俯视穷亲。"}],"difficulty":2,"npc":["舅父"],"foreshadow":"舅父的态度在松动，但嘴硬"},{"id":"E-032-戌","branch":"E","stage":2,"day":32,"shichen":"戌时","checkpoint":"周旋布局·五","scene":"夜市散场，你教小豆子认字——就认摊上那块「旋煎羊白肠」的木牌。他用树枝在地上描，描得歪歪扭扭。","options":[{"text":"每晚教他两个字","correct":true,"tags":["才华"],"dims":{"才华":1,"名声":1},"feedback":"「姐，等我认全了，给你写招牌。」","source":"宋代市井识字者少，孩童习字难得。"},{"text":"说先攒钱再请先生","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子点头：「那我先帮姐把钱攒出来！」","source":"宋代市井识字者少，孩童习字难得。"}],"flavor":true,"difficulty":1,"npc":["小豆子"],"foreshadow":"小豆子认字，日后能记账管店"},{"id":"E-032-未","branch":"E","stage":2,"day":32,"shichen":"未时","checkpoint":"周旋布局·六","scene":"绸缎庄管事娘子带来个消息：你表姐出嫁的那家，婚前忽然退了聘——说是男方打听到女方家「门风小气」。","options":[{"text":"不议论，只安慰","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"表姐再不好，落难时不踩，是你的分寸。","source":"宋代婚约悔退，于女家声名大损。"},{"text":"暗地里觉得解气","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"解气是一瞬间的事，格局是一辈子的事。","source":"宋代婚约悔退，于女家声名大损。"}],"difficulty":2,"npc":["管事娘子"],"foreshadow":"舅家婚事受挫，后文有求于你"},{"id":"E-033","branch":"E","stage":2,"day":33,"shichen":"辰时","checkpoint":"周旋布局·七","scene":"孙三又来「关照」：说他手上有批便宜白面，让你把城外那家货源断了，专吃他的货。","options":[{"text":"两家的货都进","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"鸡蛋不放一个篮子里，他捏不住你的命门。","source":"宋代经营者多源进货以避险。"},{"text":"贪便宜专进他的","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"命脉交到人手里，涨价断供都由他了。","source":"宋代经营者多源进货以避险。"}],"difficulty":3,"npc":["牙人孙三"],"foreshadow":"货源双轨，是周旋的基本功"},{"id":"E-033-戌","branch":"E","stage":2,"day":33,"shichen":"戌时","checkpoint":"周旋布局·八","scene":"收摊后七郎蹲在炉边修炉箅子，修着修着说：「那家要盘的食店，我今日去看了。灶眼大，前堂能摆六张桌。」","options":[{"text":"问他盘价要多少","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「十五贯。」他说完看你，眼里又亮又怯。","source":"《东京梦华录》记食店盘兑之价。"},{"text":"把两人的钱并一处算","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"摊上的、店里的、他攒的，加起来还差大半。他说：「那就接着攒。」","source":"《东京梦华录》记食店盘兑之价。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"十五贯，是两人共同的奔头"},{"id":"E-033-未","branch":"E","stage":2,"day":33,"shichen":"未时","checkpoint":"周旋布局·九","scene":"陈伯出主意：每月逢八，军中退下来的老虞候在州桥茶肆吃茶讲古，最恨牙人鱼肉街市，你不妨去听听。","options":[{"text":"奉茶陪坐，听他说古","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人家喝到痛快处：「这条街的事，我门儿清。」","source":"《东京梦华录》记茶肆为消息汇聚之地。"},{"text":"直接求他帮忙","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"交情未到就求人，老人摆摆手没接话。","source":"《东京梦华录》记茶肆为消息汇聚之地。"}],"difficulty":3,"npc":["老仆陈伯","老虞候"],"foreshadow":"老虞候，是压孙三的最后一手"},{"id":"E-034","branch":"E","stage":2,"day":34,"shichen":"辰时","checkpoint":"周旋布局·十","scene":"早市上，表姐红着眼眶拦住你——退婚的事传开了，她被人指指点点，舅母天天在家摔东西。","options":[{"text":"请她吃碗热汤","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"她捧着汤哭了半晌：「从前……是我不对。」","source":"宋代女子被退婚，处境极窘。"},{"text":"冷淡地应付过去","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"她讪讪地走了，你心里也并不痛快。","source":"宋代女子被退婚，处境极窘。"}],"difficulty":2,"npc":["表姐"],"foreshadow":"表姐这一哭，舅家的墙裂了缝"},{"id":"E-034-戌","branch":"E","stage":2,"day":34,"shichen":"戌时","checkpoint":"周旋布局·十一","scene":"好消息传开，今晚摊前格外热闹。有人喊：「小娘子，恶人自有天收！」你笑着摇头，手上翻饼不停。","options":[{"text":"说：是官府清正","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"话递得漂亮，茶肆里的老虞候听了直点头。","source":"宋代民间称颂官府，为处世之常。"},{"text":"不多言，饼香就行","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"少说多做，这条街上的人都懂你的性子。","source":"宋代民间称颂官府，为处世之常。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"口碑再上一层"},{"id":"E-034-未","branch":"E","stage":2,"day":34,"shichen":"未时","checkpoint":"周旋布局·十二","scene":"大嫂风风火火跑来：孙三在别处吃了官司——他放印子钱逼死过人的旧账，被苦主翻出来告到了开封府。","options":[{"text":"把攒的证物整理好","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"掺炭、债约、人证，时机到了一齐递上。","source":"宋代并案审理，众证齐发力倍增。"},{"text":"立刻去府衙补状","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"案子还在访查，此时递状反倒打草惊蛇。","source":"宋代并案审理，众证齐发力倍增。"}],"difficulty":3,"npc":["邻摊大嫂"],"foreshadow":"孙三的楼，自己开始塌了"},{"id":"E-035","branch":"E","stage":2,"day":35,"shichen":"辰时","checkpoint":"周旋布局·十三","scene":"老虞候遣人来请：茶肆一叙。你净了手，带上新烙的饼去了。他开门见山：「孙三的事，老夫可以递句话，但你得拿真东西来。」","options":[{"text":"呈上全部证物账目","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"他翻完点头：「齐了。等老夫的信儿。」","source":"宋代访案重实证，老吏门生故旧多。"},{"text":"留一手，先给一半","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老人何等精明，脸色淡了：「不全则不动。」","source":"宋代访案重实证，老吏门生故旧多。"}],"difficulty":3,"npc":["老虞候"],"foreshadow":"checkpoint 收官：布局已成，只待收网"},{"id":"E-035-戌","branch":"E","stage":2,"day":35,"shichen":"戌时","checkpoint":"周旋布局·十四","scene":"夜里两人在桥头算「店账」：你的三贯加活钱，他的工钱加分红，离十五贯还差六贯。灯火下两本账并成一本。","options":[{"text":"约定半年为期","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「半年后，锅是我的，勺是你的。」他郑重点头。","source":"宋代市井合伙，多以口头约为信。"},{"text":"在账本上按两个手印","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"两个红手印挨在一起，谁也没说要分开按。","source":"宋代市井合伙，多以口头约为信。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"半年之约，stage3 的倒计时"},{"id":"E-035-未","branch":"E","stage":2,"day":35,"shichen":"未时","checkpoint":"周旋布局·十五","scene":"七郎的脚店东家嗅到风声，忽然对他客气起来——怕他也走。工钱补发了，还许他月底分红。","options":[{"text":"劝他收下，别留死钱","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"该拿的一分不少拿，店还是要盘自己的。","source":"宋代佣工索回欠薪，理直则气壮。"},{"text":"劝他顺势留下来","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"他摇头：「东家今天给的甜，昨天怎么不给？」","source":"宋代佣工索回欠薪，理直则气壮。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"七郎攒店钱的进项多了一笔"},{"id":"E-036","branch":"E","stage":2,"day":36,"shichen":"辰时","checkpoint":"舅家回敬","scene":"舅母亲自来了——退婚之后家宅不宁，她放下身段，想请你去府上「帮着料理几日」，工钱照给。","options":[{"text":"应下三日，按日计酬","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"去是情分，收钱是本分——两不相欠。","source":"宋代雇佣以日计酬，亲族亦然。"},{"text":"记着前嫌，回绝","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"回绝一时爽，这条亲戚的路就彻底断了。","source":"宋代雇佣以日计酬，亲族亦然。"}],"difficulty":3,"npc":["舅母"],"foreshadow":"以德回敬，但不白帮"},{"id":"E-036-戌","branch":"E","stage":2,"day":36,"shichen":"戌时","checkpoint":"舅家回敬·二","scene":"从舅府回州桥已是掌灯。七郎照旧提着灯在桥头，远远看见你，快步迎上来接你手里的食盒。","options":[{"text":"把赏钱分他一半","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「你应得的工钱。」他捏着钱，半天：「那我存进店本里。」","source":"宋代市井相知，钱财分明而心意相通。"},{"text":"讲讲舅府的见闻","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"讲到舅母的态度，他松了口气：「他们总算开眼了。」","source":"宋代市井相知，钱财分明而心意相通。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"店本又厚了一小笔"},{"id":"E-036-未","branch":"E","stage":2,"day":36,"shichen":"未时","checkpoint":"舅家回敬·三","scene":"在舅府帮厨三日，你把宴席的菜色安排得明明白白，采买省下两成银子。管事娘子直咂舌：「这姑娘，是把好手。」","options":[{"text":"把省账的法子留下","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"法子给了舅府，情分是你的，谁也拿不走。","source":"宋代大户宴席采买，善算者省费甚巨。"},{"text":"藏着掖着留一手","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"留一手防的是小人，舅府如今犯不上了。","source":"宋代大户宴席采买，善算者省费甚巨。"}],"difficulty":2,"npc":["舅母","管事娘子"],"foreshadow":"舅母心里那杆秤，彻底调过来了"},{"id":"E-037","branch":"E","stage":2,"day":37,"shichen":"辰时","checkpoint":"舅家回敬·四","scene":"一早，舅父遣人送来一车上好白面和两坛酱——没有字条，没有口信，卸了货就走。","options":[{"text":"收下，回一筐新饼","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"礼尚往来，不欠不收，这是你的规矩。","source":"宋代亲族馈遗，往还各尽其道。"},{"text":"原样退回去","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"退礼等于打脸，刚缓的关系又结冰了。","source":"宋代亲族馈遗，往还各尽其道。"}],"difficulty":2,"npc":[],"foreshadow":"舅父认输的方式：只送东西不说话"},{"id":"E-037-戌","branch":"E","stage":2,"day":37,"shichen":"戌时","checkpoint":"舅家回敬·五","scene":"用舅父送的白面烙饼，起酥格外好。你在木牌上添了行小字——小豆子描的，他如今认得二十几个字了。","options":[{"text":"夸他字有长进","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子挺直腰板：「往后招牌都归我写！」","source":"宋代食摊以木牌标字号。"},{"text":"让他再描正些","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"歪歪扭扭也是招牌，独一份的。","source":"宋代食摊以木牌标字号。"}],"flavor":true,"difficulty":1,"npc":["小豆子"],"foreshadow":"木牌上的字，是这个摊的体面"},{"id":"E-037-未","branch":"E","stage":2,"day":37,"shichen":"未时","checkpoint":"舅家回敬·六","scene":"开封府来人传话：孙三的案子并了你的证物，不日问断。街坊们奔走相告，茶肆里老虞候被围着敬茶。","options":[{"text":"给老虞候送谢礼","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"一坛好酒两盒饼，老人笑得胡须直颤。","source":"宋代酬谢以酒食为常礼。"},{"text":"等案结了再谢","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"礼不在早晚，可人情讲究个趁热。","source":"宋代酬谢以酒食为常礼。"}],"difficulty":1,"npc":["老虞候"],"foreshadow":"孙三案，只差最后一锤"},{"id":"E-038","branch":"E","stage":2,"day":38,"shichen":"辰时","checkpoint":"舅家回敬·七","scene":"孙三被锁拿问断：放印子钱、把持行市、纵仆行凶，杖一百，徒二年。消息传来，半条街放了炮仗。","options":[{"text":"摊子照常，不凑热闹","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"大喜的日子，饼还是那饼，人还是那人。","source":"宋代杖徒之刑，见《宋刑统》。"},{"text":"收摊去看问断","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"解恨是解恨，可少做了一晌生意。","source":"宋代杖徒之刑，见《宋刑统》。"}],"difficulty":2,"npc":[],"foreshadow":"孙三伏法，街市换了一重天"},{"id":"E-038-戌","branch":"E","stage":2,"day":38,"shichen":"戌时","checkpoint":"舅家回敬·八","scene":"庆功似的，今晚你烫了一小壶酒，和七郎、大嫂、陈伯、小豆子分着喝。小豆子只许闻闻味儿。","options":[{"text":"敬这街上一路的人","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"酒不多，人人有份，杯底都见了光。","source":"《东京梦华录》记市井沽酒小饮之俗。"},{"text":"单独敬七郎一杯","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"众人起哄，他端着杯，耳朵红透了。","source":"《东京梦华录》记市井沽酒小饮之俗。"}],"flavor":true,"difficulty":1,"npc":["陈七郎","邻摊大嫂","老仆陈伯","小豆子"],"foreshadow":"这一桌人，是将来食店的班底"},{"id":"E-038-未","branch":"E","stage":2,"day":38,"shichen":"未时","checkpoint":"舅家回敬·九","scene":"没了孙三，街市上牙人的空档露出来。几个老商户来探你口风：「小娘子公道，这撮合买卖的活，你兼着做如何？」","options":[{"text":"婉谢，推给老商户","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「我守好摊子。撮合的事，各位老掌柜在行。」众人更敬你三分。","source":"宋代牙人需官府给帖，非人人可为。"},{"text":"应下来多条进项","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"牙人要吃官帖，更要分心——贪多嚼不烂。","source":"宋代牙人需官府给帖，非人人可为。"}],"difficulty":3,"npc":[],"foreshadow":"不碰牙人生意，守住本分口碑"},{"id":"E-039","branch":"E","stage":2,"day":39,"shichen":"辰时","checkpoint":"攒店本钱","scene":"盘店的东家捎话来：有好几家也看中了那个店面，价可能要抬。七郎急了，一早就在你摊前转磨。","options":[{"text":"约东家面谈锁价","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"先下定钱立字据，十五贯锁死，一年为期。","source":"宋代盘店下定立契，防抬价。"},{"text":"加价先把店抢下","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"价抬到十七贯，攒钱的担子陡然重了。","source":"宋代盘店下定立契，防抬价。"}],"difficulty":3,"npc":["陈七郎"],"foreshadow":"店面锁定了，剩下就是攒钱"},{"id":"E-039-戌","branch":"E","stage":2,"day":39,"shichen":"戌时","checkpoint":"攒店本钱·二","scene":"字据立了，定钱交了。你俩站在那间还没盘下来的食店门口，隔着门板，七郎小声说：「招牌我都想好了。」","options":[{"text":"问叫什么","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「等你起。」他说，「你的名字比我的亮。」","source":"宋代食店多以姓氏名号作招牌。"},{"text":"说一起想","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"门板前人影成双，店还没开，心是齐的。","source":"宋代食店多以姓氏名号作招牌。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"招牌之名，留待 stage3 揭晓"},{"id":"E-039-未","branch":"E","stage":2,"day":39,"shichen":"未时","checkpoint":"攒店本钱·三","scene":"定钱要两贯。你的活钱不够——差四百文。你看着床底下那只陶罐：娘留的三贯钱，还剩两贯原封没动过。","options":[{"text":"动用一贯应急","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"娘的钱用在奔头上，她在天上也会点头。","source":"宋代陶罐贮钱，急用方启。"},{"text":"找大嫂借钱周转","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"大嫂痛快借了，可你一夜没睡踏实。","source":"宋代陶罐贮钱，急用方启。"}],"difficulty":3,"npc":[],"foreshadow":"三贯钱第二次动用，还剩一贯"},{"id":"E-040","branch":"E","stage":2,"day":40,"shichen":"辰时","checkpoint":"攒店本钱·四","scene":"为了攒钱，你把摊子时辰拉长：辰时出早市卖饼夹蛋，专做上工人们的生意。头一天就多了六十文。","options":[{"text":"让陈伯管早市","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"老伯起得比鸡早，早市交给他最放心。","source":"《东京梦华录》记汴京早市天明即开。"},{"text":"自己硬扛全天","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"三天下来人瘦了一圈，七郎急了。","source":"《东京梦华录》记汴京早市天明即开。"}],"difficulty":2,"npc":["老仆陈伯"],"foreshadow":"checkpoint 收官：早市这步棋走活了"},{"id":"E-040-戌","branch":"E","stage":2,"day":40,"shichen":"戌时","checkpoint":"攒店本钱·五","scene":"夜里算店账：定钱交了，手头又紧回来。七郎把他这个月的分红也塞了进来：「离九贯，又近了些。」","options":[{"text":"给他也记工分","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「你的我的，往后还分吗？」你问。他挠头：「不分了。」","source":"宋代市井合伙，账目两讫为信。"},{"text":"说还差得远，别松劲","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「嗯！」他应得响亮，像领了军令。","source":"宋代市井合伙，账目两讫为信。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"「不分了」三个字，比定钱还重"},{"id":"E-040-未","branch":"E","stage":2,"day":40,"shichen":"未时","checkpoint":"攒店本钱·六","scene":"表姐来了，放下一个包袱：里面是她亲手绣的桌围椅披——「往后你们的店开张，用得上。」","options":[{"text":"收下，请她常来","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"她红着眼笑：「我认你这个妹子。」","source":"宋代女子以针黹相赠，情谊深重。"},{"text":"推说太贵重","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"推来推去，她把包袱一放，跑了。","source":"宋代女子以针黹相赠，情谊深重。"}],"difficulty":1,"npc":["表姐"],"foreshadow":"桌围椅披，开张时的体面"},{"id":"E-041","branch":"E","stage":2,"day":41,"shichen":"辰时","checkpoint":"攒店本钱·七","scene":"早市上，一个行商模样的人尝了你的饼，问能不能每日供他一百个，带去相国寺庙会外卖，价钱好商量。","options":[{"text":"先试三日看销路","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"庙会上一抢而空，他当场订了长期。","source":"《东京梦华录》记相国寺万姓交易之盛。"},{"text":"一口应下长期单","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"庙会人一散，单量骤减，白忙一场。","source":"《东京梦华录》记相国寺万姓交易之盛。"}],"difficulty":2,"npc":["行商"],"foreshadow":"相国寺这条销路，进账可观"},{"id":"E-041-戌","branch":"E","stage":2,"day":41,"shichen":"戌时","checkpoint":"攒店本钱·八","scene":"打烊后教杏儿看火。小豆子凑过来要教她认字，被杏儿瞪了一眼：「先把你自己那手狗爬练好！」一屋子笑。","options":[{"text":"由他闹，添油加醋","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"柴房里笑声不断，像个家了。","source":"《东京梦华录》记市井人家邻里亲厚。"},{"text":"一人多教两个字","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"字认多了，账就有人接班了。","source":"《东京梦华录》记市井人家邻里亲厚。"}],"flavor":true,"difficulty":1,"npc":["小豆子","丫头杏儿"],"foreshadow":"小豆子和杏儿，一对活宝"},{"id":"E-041-未","branch":"E","stage":2,"day":41,"shichen":"未时","checkpoint":"攒店本钱·九","scene":"生意越做越开，人手吃紧。大嫂把她家侄女荐来帮工：手脚麻利，人也本分的十四岁丫头。","options":[{"text":"收下，工钱从优","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"丫头唤你'师父'，摊子有了小帮厨。","source":"宋代市井雇工，亲友引荐为常道。"},{"text":"怕教不会，婉拒","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大嫂笑你：「你从前不也是这么过来的？」","source":"宋代市井雇工，亲友引荐为常道。"}],"difficulty":1,"npc":["邻摊大嫂","丫头杏儿"],"foreshadow":"杏儿，食店未来的伙计"},{"id":"E-042","branch":"E","stage":2,"day":42,"shichen":"辰时","checkpoint":"攒店本钱·十","scene":"七郎正式向脚店辞工。东家挽留，开出管事的位子。他回来问你意见，眼神却分明已有答案。","options":[{"text":"支持他辞工","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「锅碗瓢盆早该听你的，不该听东家的。」他重重点头。","source":"宋代厨人辞佣自立，市井常事。"},{"text":"劝他再熬半年","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他应了，可眼底那点火暗了一截。","source":"宋代厨人辞佣自立，市井常事。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"七郎辞工，全力奔食店"},{"id":"E-042-戌","branch":"E","stage":2,"day":42,"shichen":"戌时","checkpoint":"攒店本钱·十一","scene":"晚上七郎试菜，请你做头一个品评人：旋煎羊白肠、插肉面、爊肉。他把脚店学的手艺，一样样亮出来。","options":[{"text":"每样都认真点评","correct":true,"tags":["感情","才华"],"dims":{"情缘":1,"才华":1},"feedback":"「汤咸了半分。」他认真记下，像听先生讲课。","source":"《东京梦华录》记汴京食店菜色名目。"},{"text":"只夸不评","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「你别哄我。」他较真，「开店哄不得。」","source":"《东京梦华录》记汴京食店菜色名目。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"食店菜单，今夜初定"},{"id":"E-042-未","branch":"E","stage":2,"day":42,"shichen":"未时","checkpoint":"攒店本钱·十二","scene":"辞了工的七郎一头扎进筹备：跑窑口订碗碟、寻木匠打桌椅。中午灰头土脸回来，捧着两只粗瓷碗让你挑。","options":[{"text":"挑了便宜耐用的","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「开店初期，钱要花在灶上。」他记下了。","source":"宋代食店器皿，以耐用为先。"},{"text":"挑了好看的那只","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"好看是好看，一只顶三只的价。","source":"宋代食店器皿，以耐用为先。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"店里的碗筷，是一对一对挑的"},{"id":"E-043","branch":"E","stage":2,"day":43,"shichen":"辰时","checkpoint":"攒店本钱·十三","scene":"相国寺庙会逢集，你带杏儿去摆摊。人山人海，香火气混着饼香，一上午卖了三百个饼。","options":[{"text":"给杏儿算提成","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"丫头攥着钱，眼睛亮得像庙前的琉璃瓦。","source":"《东京梦华录》记相国寺庙会百货云集。"},{"text":"工钱照旧月结","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"杏儿嘴上没说，干活的劲头松了些。","source":"《东京梦华录》记相国寺庙会百货云集。"}],"difficulty":2,"npc":["丫头杏儿"],"foreshadow":"庙会的流水，让店本大涨一截"},{"id":"E-043-戌","branch":"E","stage":2,"day":43,"shichen":"戌时","checkpoint":"攒店本钱·十四","scene":"庙会散场，数钱数到手软。你留出一小份，带着小豆子和杏儿去看了场傀儡戏，两个孩子看得直拍手。","options":[{"text":"给孩子们买糖吃","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"辛苦钱换来的甜，最对味。","source":"《东京梦华录》记庙会傀儡戏极盛。"},{"text":"自己也看入了迷","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"你有多久没这样看过一场戏了。","source":"《东京梦华录》记庙会傀儡戏极盛。"}],"flavor":true,"difficulty":1,"npc":["小豆子","丫头杏儿"],"foreshadow":"苦日子里，也要有钱看戏"},{"id":"E-043-未","branch":"E","stage":2,"day":43,"shichen":"未时","checkpoint":"攒店本钱·十五","scene":"庙会上撞见舅家舅父——他陪同僚来上香，看见你的摊前排着队，同僚还夸了句「这饼有名」。","options":[{"text":"大方见礼，送上饼","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"他接过饼，在同僚面前难得有了笑模样。","source":"宋代亲族相见于市，礼数周全为要。"},{"text":"低头装没看见","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"同僚问起来，舅父支吾过去，两头尴尬。","source":"宋代亲族相见于市，礼数周全为要。"}],"difficulty":2,"npc":["舅父"],"foreshadow":"舅父在同僚面前认了她这门亲"},{"id":"E-044","branch":"E","stage":2,"day":44,"shichen":"辰时","checkpoint":"攒店本钱·十六","scene":"盘店的东家又来催：有户开果子行的出价十六贯，问你们加不加。字据在身，他不能直接悔约，但能拖。","options":[{"text":"请老虞候作证提醒","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"字据加老吏的面子，东家讪讪地不再提加价。","source":"宋代契约纠纷，中保人出面调停。"},{"text":"咬牙加一贯","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你退一步，他明日还想再进一步。","source":"宋代契约纠纷，中保人出面调停。"}],"difficulty":3,"npc":["老虞候"],"foreshadow":"店保住了，交钱的日子也近了"},{"id":"E-044-戌","branch":"E","stage":2,"day":44,"shichen":"戌时","checkpoint":"攒店本钱·十七","scene":"深夜核账：庙会进项、早市、茶坊分成、七郎的工钱……店本过了十一贯。再有月余，十五贯就够。","options":[{"text":"在墙上画个记号","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"炭条画到'十一'，七郎添了个小小的圈。","source":"宋代市井以记号记事，随处可见。"},{"text":"合计开张的吉日","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"翻了半天历头，两人头挨着头。","source":"宋代市井以记号记事，随处可见。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"十一贯，胜利在望"},{"id":"E-044-未","branch":"E","stage":2,"day":44,"shichen":"未时","checkpoint":"攒店本钱·十八","scene":"掌柜娘子盘下隔壁一间小屋送你堆货：「将来开店，这儿就当仓房。」分文未取，只说算她入的一股。","options":[{"text":"应下，立个小契","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"亲兄弟明算账，契书写清，情分更长。","source":"宋代合伙入股，书契为凭。"},{"text":"不好意思占便宜","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘子佯恼：「瞧不上我这一股？」","source":"宋代合伙入股，书契为凭。"}],"difficulty":2,"npc":["掌柜娘子"],"foreshadow":"食店有了第一个股东"},{"id":"E-045","branch":"E","stage":2,"day":45,"shichen":"辰时","checkpoint":"临门波澜","scene":"晴天霹雳：七郎前东家反咬一口，说七郎走时带走了店里的「祖传酱方」，要告他偷方。","options":[{"text":"查酱方来历对质","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"方子是七郎自己摸索的，试做的炭条账都在。","source":"宋代技艺归属之讼，以实证为断。"},{"text":"赔钱了事图清净","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"钱一赔，等于认了偷，名声就臭了。","source":"宋代技艺归属之讼，以实证为断。"}],"difficulty":3,"npc":["脚店东家"],"foreshadow":"checkpoint：临门一脚起波澜"},{"id":"E-045-戌","branch":"E","stage":2,"day":45,"shichen":"戌时","checkpoint":"临门波澜·二","scene":"夜里七郎蹲在门口自责：「都怪我，店钱还没齐，又惹上官司。」你递给他一碗热汤。","options":[{"text":"说：当初赊汤的也是你","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「一碗汤赊出这么些事，值了。」他捧着碗笑了。","source":"宋人笔记多言患难相恤之情。"},{"text":"把官司当自己的","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「你的官司就是我的官司。」他没接话，肩膀不抖了。","source":"宋人笔记多言患难相恤之情。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"一碗汤，从 day8 暖到 day45"},{"id":"E-045-未","branch":"E","stage":2,"day":45,"shichen":"未时","checkpoint":"临门波澜·三","scene":"你带着七郎的试酱账、历年的采买单子去见老虞候。老人看完冷笑：「惯用的讹人招数。老夫陪他过过堂。」","options":[{"text":"备齐人证物证应诉","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"陈伯、大嫂都能作证酱是哪天试成的。","source":"宋代诉讼，证人证物齐备则胜算大。"},{"text":"让七郎自己应对","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他嘴笨，堂上三句就被绕进去了。","source":"宋代诉讼，证人证物齐备则胜算大。"}],"difficulty":3,"npc":["老虞候","老仆陈伯"],"foreshadow":"又是这套班底，又是一场硬仗"},{"id":"E-046","branch":"E","stage":2,"day":46,"shichen":"辰时","checkpoint":"临门波澜·四","scene":"过堂这日，脚店东家在堂上说得天花乱坠。老虞候不慌不忙呈上试酱的炭条账——日期一笔笔，比东家说的'祖传'还早两年。","options":[{"text":"静观，不插一言","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"官人当堂斥东家讹告，案子结了。","source":"宋代讹告反坐，见《宋刑统》。"},{"text":"忍不住出声帮腔","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"堂上妇人喧哗，官人皱了眉，多亏证据硬。","source":"宋代讹告反坐，见《宋刑统》。"}],"difficulty":3,"npc":["脚店东家","老虞候"],"foreshadow":"讹告不成，东家名声扫地"},{"id":"E-046-戌","branch":"E","stage":2,"day":46,"shichen":"戌时","checkpoint":"临门波澜·五","scene":"送走客人，两人收拾杯盘。七郎忽然说：「打官司那两天我想明白了——往后天大的事，咱俩一起扛。」","options":[{"text":"嗯，一起扛","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"三个字落地，比什么婚约都郑重。","source":"宋人笔记记市井男女盟誓之朴。"},{"text":"逗他：谁跟你咱俩","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「你！」他急了，你笑出了声。","source":"宋人笔记记市井男女盟誓之朴。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"盟誓已定，只剩明媒这一步"},{"id":"E-046-未","branch":"E","stage":2,"day":46,"shichen":"未时","checkpoint":"临门波澜·六","scene":"官司了结，七郎请老虞候吃酒谢恩。老人喝到半酣：「你们那店开张，头一锅汤，得给老夫留一碗。」","options":[{"text":"应下，奉为座上宾","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"有这位老人坐镇，新店没人敢惹。","source":"宋代食店开张，请耆老为贺。"},{"text":"厚谢金银","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"老人推回来：「老夫图的是一碗汤，不是钱。」","source":"宋代食店开张，请耆老为贺。"}],"difficulty":1,"npc":["老虞候","陈七郎"],"foreshadow":"开张那碗汤，已许出去了"},{"id":"E-047","branch":"E","stage":2,"day":47,"shichen":"辰时","checkpoint":"收官将近","scene":"舅父亲自登门——这次进了你的柴房，坐了那张矮凳。他看着墙皮上的账，沉默良久：「你比你表兄们都强。」","options":[{"text":"沏茶，叙家常","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"不翻旧账，茶沏得热热的。他走时脚步轻了。","source":"宋人笔记记亲族释怨，贵在体面。"},{"text":"提当年的门房之事","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"旧账一翻，满屋的茶都凉了。","source":"宋人笔记记亲族释怨，贵在体面。"}],"difficulty":3,"npc":["舅父"],"foreshadow":"舅父低头，亲缘续上了"},{"id":"E-047-戌","branch":"E","stage":2,"day":47,"shichen":"戌时","checkpoint":"收官将近·二","scene":"摊收得早。你翻出嫁妆要备的东西，七郎帮着拿主意，挑着挑着两人都沉默了——嫁妆这个词，有点烫。","options":[{"text":"打破沉默接着挑","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「布要赭红的。」你俩同时开口，又同时笑了。","source":"宋代嫁妆置办，重在实用体面。"},{"text":"问他将来想要什么","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「一间店，一个你。」他说完就跑出去劈柴了。","source":"宋代嫁妆置办，重在实用体面。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"嫁妆的话题，早晚落到自己身上"},{"id":"E-047-未","branch":"E","stage":2,"day":47,"shichen":"未时","checkpoint":"收官将近·三","scene":"舅父临走时说：表姐的婚事重新有了着落，对方是老实本分的商户，托他问一句——你愿不愿意去送嫁。","options":[{"text":"应下，备一份嫁妆","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"送嫁那日你风风光光去，谁还记得当初的门房。","source":"宋代婚嫁送亲，亲族体面为重。"},{"text":"托词店忙推了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"表姐盼了又盼的眼神，你没接住。","source":"宋代婚嫁送亲，亲族体面为重。"}],"difficulty":2,"npc":["舅父","表姐"],"foreshadow":"送嫁之日，是你的翻身亮相"},{"id":"E-048","branch":"E","stage":2,"day":48,"shichen":"辰时","checkpoint":"收官将近·四","scene":"店本终于凑齐十五贯。可交钱那日，东家支吾着说屋里有些旧物要「折价」，张口又要五百文。","options":[{"text":"动用最后一贯压阵","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"娘留的三贯至此用尽——都用在了刀刃上。","source":"宋代盘店交割，常有零头之争。"},{"text":"当堂跟他掰扯","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"掰扯赢了道理，误了吉时，不值。","source":"宋代盘店交割，常有零头之争。"}],"difficulty":3,"npc":[],"foreshadow":"三贯钱尽数用尽，木梳还在"},{"id":"E-048-戌","branch":"E","stage":2,"day":48,"shichen":"戌时","checkpoint":"收官将近·五","scene":"空店里生起第一炉火。你烙了饼，七郎煎了羊肠，大嫂、陈伯、小豆子、杏儿围坐一圈，算是温锅。","options":[{"text":"给每人派个差事","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"跑堂、采买、灶上、账目，众人笑着领命。","source":"《东京梦华录》记食店开业分工之景。"},{"text":"只说谢谢，红了眼眶","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"大嫂摆手：「谢什么，往后这店也是我们的。」","source":"《东京梦华录》记食店开业分工之景。"}],"flavor":true,"difficulty":1,"npc":["陈七郎","邻摊大嫂","老仆陈伯","小豆子","丫头杏儿"],"foreshadow":"温锅这一夜，食店的魂齐了"},{"id":"E-048-未","branch":"E","stage":2,"day":48,"shichen":"未时","checkpoint":"收官将近·六","scene":"钥匙到手了。推开店门，灶眼、前堂、六张桌的位置，和七郎说过的一模一样。阳光从门板缝照进来，落在灶台上。","options":[{"text":"先扫灶，祭灶神","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"新店先敬灶，烟火才有根。","source":"宋代人家敬灶神，店铺亦然。"},{"text":"里里外外量一遍","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"哪里摆桌哪里砌灶，心里有了图。","source":"宋代人家敬灶神，店铺亦然。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"店，终于是他们的了"},{"id":"E-049","branch":"E","stage":2,"day":49,"shichen":"辰时","checkpoint":"收官将近·七","scene":"开张前两日，表姐出嫁。你穿着新做的干净襦裙去送嫁，抬嫁妆的队伍里，有她送你的那副桌围椅披做回礼。","options":[{"text":"体面风光地送","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"街坊都看见了：投亲不遇的孤女，如今是座上宾。","source":"《东京梦华录》记汴京婚嫁之仪。"},{"text":"低调站在人后","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"表姐特意把你拉到前头：「这是我妹子。」","source":"《东京梦华录》记汴京婚嫁之仪。"}],"difficulty":2,"npc":["表姐","舅父"],"foreshadow":"送嫁亮相，身份彻底翻转"},{"id":"E-049-戌","branch":"E","stage":2,"day":49,"shichen":"戌时","checkpoint":"收官将近·八","scene":"喜宴归来路过新店，七郎正踩着凳子挂灯笼。灯笼上还没写字，映着光，等他下来问你的意思。","options":[{"text":"写下两人的姓氏","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"灯笼上两个姓并排挂着，风一吹，轻轻碰到一起。","source":"宋代食店灯笼书字号，彻夜不熄。"},{"text":"说等开张再写","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「留着压轴。」他仰头看灯笼，像看往后几十年。","source":"宋代食店灯笼书字号，彻夜不熄。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"灯笼上的字，留到 stage3 落笔"},{"id":"E-049-未","branch":"E","stage":2,"day":49,"shichen":"未时","checkpoint":"收官将近·九","scene":"喜宴上，有媒婆凑过来打听你的亲事——州桥小娘子如今是多少人眼里的好亲事。舅母替你挡了：「这孩子的事，她自己做主。」","options":[{"text":"谢舅母，笑而不答","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"亲事自己做主——这句话比什么嫁妆都金贵。","source":"宋代市井女子自择婚配者渐多。"},{"text":"说自己有了人","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"话传得太快，七郎听说后手足无措了一整天。","source":"宋代市井女子自择婚配者渐多。"}],"difficulty":2,"npc":["舅母"],"foreshadow":"亲事自己做主，stage3 的题眼"},{"id":"E-050","branch":"E","stage":2,"day":50,"shichen":"辰时","checkpoint":"阶段二收官","scene":"开张前最后一天。摊子、茶坊食档、早市全部交底给陈伯和杏儿盯着，你和七郎在店里做最后的收拾。","options":[{"text":"把摊子规矩写成帖","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"用料几分、火候几成，写在纸上才传得下去。","source":"宋代食店手艺传承，多有口诀帖式。"},{"text":"口头交代一遍","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"口传的规矩，三天就走了样。","source":"宋代食店手艺传承，多有口诀帖式。"}],"difficulty":2,"npc":["老仆陈伯","丫头杏儿"],"foreshadow":"摊子交给班底，她腾出手开店"},{"id":"E-050-戌","branch":"E","stage":2,"day":50,"shichen":"戌时","checkpoint":"阶段二收官·二","scene":"夜里你独自回柴房收拾。包袱打开了：木梳还在，三贯钱已经变成了州桥的一间食店。五十天前桥洞边挨冻的姑娘，明日要开店了。","options":[{"text":"把木梳别进新衣襟","correct":true,"tags":["感情"],"dims":{"情缘":1,"自主":1},"feedback":"娘，汴京很大，容下了一双肯做事的手，还多了一个提灯的人。","source":"《东京梦华录》记汴京百业俱兴之盛。"},{"text":"对灯坐到天亮","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"这一夜不长，往后的日子还长得很。","source":"《东京梦华录》记汴京百业俱兴之盛。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"stage3 开启：食店开张，亲事待提"},{"id":"E-050-未","branch":"E","stage":2,"day":50,"shichen":"未时","checkpoint":"阶段二收官·三","scene":"老虞候、掌柜娘子、大嫂、舅父舅母……贺仪单子越写越长。你提笔在头一行写下：小豆子，帮手，无仪——带了三年力气。","options":[{"text":"给小豆子包个大封","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"孩子捧着封，半天憋出一句：「姐，我没白跟你。」","source":"宋代开业酬宾，亲疏皆有所酬。"},{"text":"让他当开店的头客","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"头客是好意，可封里的钱，孩子更缺。","source":"宋代开业酬宾，亲疏皆有所酬。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"checkpoint 收官：宾朋满座"},{"id":"E-051","branch":"E","stage":3,"day":51,"shichen":"辰时","checkpoint":"招牌落笔","scene":"开张前三日，招牌的事不能再拖。七郎请来街上写字最好的老童生，笔都蘸饱了，问你：「落什么字号？」","options":[{"text":"就叫「州桥汤记」","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一碗汤起的家，一块招牌认祖归宗。","source":"宋代食店多以地名姓氏为字号。"},{"text":"用七郎的姓氏","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"「陈记？」他挠头，「可这条街认的是小娘子。」","source":"宋代食店多以地名姓氏为字号。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"「汤记」二字，记住的是那碗赊来的汤"},{"id":"E-051-戌","branch":"E","stage":3,"day":51,"shichen":"戌时","checkpoint":"招牌落笔·二","scene":"入夜试灯。「州桥汤记」四个字在灯里透出暖光，半条街都看得见。小豆子仰着头：「姐，这字比我描的好看。」","options":[{"text":"说往后教他写","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"「练好了，分号的招牌归你写。」","source":"《东京梦华录》记夜市灯火彻夜通明。"},{"text":"让他认一遍这四个字","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子一个字一个字念，念得比唱的还好听。","source":"《东京梦华录》记夜市灯火彻夜通明。"}],"flavor":true,"difficulty":1,"npc":["小豆子"],"foreshadow":"分号的念头，悄悄种下了"},{"id":"E-051-未","branch":"E","stage":3,"day":51,"shichen":"未时","checkpoint":"招牌落笔·三","scene":"灯笼要写字了。七郎把梯子扶稳，老童生问：「灯笼上两个姓，谁先谁后？」","options":[{"text":"并排写，不分先后","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"两个姓氏一般大，并排挑在门楣下。","source":"宋代食店灯笼书字号，为夜市标识。"},{"text":"让他先，你随后","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"他急了：「这店是你的脸面，该你在前。」","source":"宋代食店灯笼书字号，为夜市标识。"}],"difficulty":2,"npc":["陈七郎","老童生"],"foreshadow":"留白两段的灯笼，终于落了字"},{"id":"E-052","branch":"E","stage":3,"day":52,"shichen":"辰时","checkpoint":"开张筹备","scene":"开张前两日，采买单子列了半页纸。七郎要去肉行谈长期供肉，问你要个章程：价压到几成，量定多少。","options":[{"text":"定量定价写清楚","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"立了长单，肉行掌柜主动又让了半分。","source":"宋代食店与行户立长单供货，常有。"},{"text":"让他看着谈","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他实诚，差点按市价签了一年。","source":"宋代食店与行户立长单供货，常有。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"长单立稳，开店成本就压住了"},{"id":"E-052-戌","branch":"E","stage":3,"day":52,"shichen":"戌时","checkpoint":"开张筹备·二","scene":"收拾店面到深夜，七郎从怀里掏出个小布包：两把新木勺，勺柄上一把刻「汤」，一把刻「记」。","options":[{"text":"收勺，夸他手巧","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「木匠铺学徒那磨的。」他不好意思，「不值钱。」","source":"宋代市井定情，多赠手作小物。"},{"text":"说该刻两个人的姓","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"他一拍脑门：「明儿就去磨！」","source":"宋代市井定情，多赠手作小物。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"两把木勺，是店里的定情物"},{"id":"E-052-未","branch":"E","stage":3,"day":52,"shichen":"未时","checkpoint":"开张筹备·三","scene":"老摊那边，陈伯和杏儿领了摊子，第一天独立支应就出了岔子：炭买潮了，火不旺，饼出得慢。","options":[{"text":"过去示范一遍再回","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"手把手带一天，往后他们自己能接住了。","source":"宋代手艺传承，口传心授带徒。"},{"text":"让他们自己摸索","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"摸索是长本事，可老客等不得。","source":"宋代手艺传承，口传心授带徒。"}],"difficulty":2,"npc":["老仆陈伯","丫头杏儿"],"foreshadow":"老摊顺利交接，她才能放手开店"},{"id":"E-053","branch":"E","stage":3,"day":53,"shichen":"辰时","checkpoint":"开张筹备·四","scene":"开张前一日，试灶宴客。老虞候、掌柜娘子、大嫂、舅父舅母都请了。菜单一早就贴在门板上。","options":[{"text":"亲自掌最后一遍勺","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"十二道菜尝过八道，你心里有了底。","source":"宋代食店开业前试灶，以定菜色。"},{"text":"全交给七郎练手","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"他手艺够，就是紧张得汤多放了盐。","source":"宋代食店开业前试灶，以定菜色。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"试灶顺利，就等明日开张大吉"},{"id":"E-053-戌","branch":"E","stage":3,"day":53,"shichen":"戌时","checkpoint":"开张筹备·五","scene":"开张前夜。你和七郎坐在新店门槛上，谁都没说话。州桥的灯火一路铺过来，像为你俩亮的。","options":[{"text":"说：明早我来生火","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「我生。」他说，「你掌勺，我烧火，一辈子的分工。」","source":"《东京梦华录》记州桥夜市灯火如昼。"},{"text":"靠着门框眯一会","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"他坐着没动，让你靠了半个时辰。","source":"《东京梦华录》记州桥夜市灯火如昼。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"「一辈子的分工」，说早了也不早"},{"id":"E-053-未","branch":"E","stage":3,"day":53,"shichen":"未时","checkpoint":"开张筹备·六","scene":"试灶席上，舅父吃得很少、看得很细。散席时他留下一句：「灶上缺什么，跟家里言语一声。」","options":[{"text":"谢过，只讨一坛酱","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"讨一坛酱，是认亲；不多讨，是分寸。","source":"宋代亲族馈赠，受之以礼还之以情。"},{"text":"列单子要什么给什么","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"舅父应了，可你这店，往后说话就矮了半截。","source":"宋代亲族馈赠，受之以礼还之以情。"}],"difficulty":2,"npc":["舅父"],"foreshadow":"舅家这根线，从翻险到帮衬"},{"id":"E-054","branch":"E","stage":3,"day":54,"shichen":"辰时","checkpoint":"开张大吉","scene":"开张日。五更生火，门口花红挂起，炮仗一响，半条街的人都涌来了。老虞候拄着杖，头一个到。","options":[{"text":"亲手奉上头碗汤","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人喝罢高声道：「这汤，值一块招牌！」","source":"宋代食店开业，耆老品题以扬名。"},{"text":"请他上座再奉汤","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"礼数是到了，可汤的热乎劲儿差了些。","source":"宋代食店开业，耆老品题以扬名。"}],"difficulty":2,"npc":["老虞候"],"foreshadow":"许出去的那碗汤，兑现了"},{"id":"E-054-戌","branch":"E","stage":3,"day":54,"shichen":"戌时","checkpoint":"开张大吉·二","scene":"打烊盘账，开张首日净入一贯二百文。你和七郎对着钱匣看了半天，谁都没伸手去数第二遍。","options":[{"text":"封一贯存店本","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"开张钱不动，讨个「存得住」的彩头。","source":"宋代开业首金封存，讨吉利之俗。"},{"text":"给伙计们发红包","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"人人有份，小豆子攥着钱睡不着。","source":"宋代开业首金封存，讨吉利之俗。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"「汤记」首日开门红"},{"id":"E-054-未","branch":"E","stage":3,"day":54,"shichen":"未时","checkpoint":"开张大吉·三","scene":"晌午客如潮。六张桌翻了三轮，小豆子报菜报到嗓子哑，杏儿端盘端得脚不沾地。","options":[{"text":"开张三天让利一成","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「汤记让利」的话风传出去，队排到了桥头。","source":"宋代新店开业，让利招徕为常法。"},{"text":"按原价稳住品质","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"品质是稳的，只是开张的热闹劲短了半分。","source":"宋代新店开业，让利招徕为常法。"}],"difficulty":2,"npc":["小豆子","丫头杏儿"],"foreshadow":"一炮而红，「汤记」立住了"},{"id":"E-055","branch":"E","stage":3,"day":55,"shichen":"辰时","checkpoint":"开张大吉·四","scene":"开张次日，州桥的老商户们联袂来吃早点——这是街面上的认可：「汤记」正式进了这条街的谱。","options":[{"text":"逐桌敬茶道谢","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"一圈茶敬下来，往后这条街都是你的帮衬。","source":"宋代商铺入行，邻里互访为礼。"},{"text":"忙生意顾不上","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"商户们不挑理，可心里记了一笔冷淡。","source":"宋代商铺入行，邻里互访为礼。"}],"difficulty":2,"npc":[],"foreshadow":"checkpoint 收官：「汤记」立稳"},{"id":"E-055-戌","branch":"E","stage":3,"day":55,"shichen":"戌时","checkpoint":"开张大吉·五","scene":"晚上打烊，七郎神神秘秘地从灶膛后摸出个陶罐——开张这几日他偷偷攒的「体己」：整整三百文。","options":[{"text":"笑他藏私房钱","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「攒着给你打支银簪。」他说得理直气壮。","source":"宋代市井赠簪，为定情常礼。"},{"text":"让他入账充公","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「充公也行。」他挠头，「簪子另攒。」","source":"宋代市井赠簪，为定情常礼。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"银簪的念想，亲事的先声"},{"id":"E-055-未","branch":"E","stage":3,"day":55,"shichen":"未时","checkpoint":"开张大吉·六","scene":"午后稍闲，舅母来访，绕着店里看了一圈，忽然压低声音：「你舅父想跟你合伙，把府里的宴席采买交给你办。」","options":[{"text":"按市价立契合作","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"亲是亲，账是账——立了契，谁都不亏。","source":"宋代亲族合伙，立契分明为常。"},{"text":"顾念亲情不收钱","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"不收钱的合作，做三次就变回使唤了。","source":"宋代亲族合伙，立契分明为常。"}],"difficulty":2,"npc":["舅母"],"foreshadow":"舅家从嫌贫到求合作，彻底翻转"},{"id":"E-056","branch":"E","stage":3,"day":56,"shichen":"辰时","checkpoint":"生意兴隆","scene":"「汤记」开业一周，州桥的脚店东家也来了——不是找茬，是低声下气来取经，问你愿不愿收他家的学徒。","options":[{"text":"收徒，但立规矩","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"不计前嫌是气度，立下规矩是章法。","source":"宋代食店收徒授艺，师徒相约为信。"},{"text":"记着酱方的仇，拒了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"拒得有理，可同行这道梁子就结下了。","source":"宋代食店收徒授艺，师徒相约为信。"}],"difficulty":2,"npc":["脚店东家"],"foreshadow":"以德报怨，同行的口碑也拿下了"},{"id":"E-056-戌","branch":"E","stage":3,"day":56,"shichen":"戌时","checkpoint":"生意兴隆·二","scene":"媒婆的事你没瞒七郎。他听完半天没吭声，闷头刷完所有锅，忽然说：「我……我明日让我娘来。」","options":[{"text":"心跳漏了一拍","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「嗯。」你只应了一个字，耳朵尖红了。","source":"宋代议婚，男方家长出面为提亲之始。"},{"text":"逗他：你娘知道么","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「早知道！」他急了，「我娘腌的辣菜就是给你的！」","source":"宋代议婚，男方家长出面为提亲之始。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"陈家要正式提亲了"},{"id":"E-056-未","branch":"E","stage":3,"day":56,"shichen":"未时","checkpoint":"生意兴隆·三","scene":"午后，一个衣着体面的媒婆进了店，点了最贵的菜，慢条斯理吃完，才开口：「小娘子，城南张员外家二公子……」","options":[{"text":"礼貌听完，婉拒","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「多谢好意。我的亲事，我自己做主。」","source":"宋代媒妁说亲，女家可辞。"},{"text":"当场赶人","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"媒婆臊眉耷眼走了，转头就把话说难听了。","source":"宋代媒妁说亲，女家可辞。"}],"difficulty":2,"npc":["媒婆"],"foreshadow":"媒婆上门，亲事这条线动起来了"},{"id":"E-057","branch":"E","stage":3,"day":57,"shichen":"辰时","checkpoint":"陈家提亲","scene":"一早，七郎的母亲来了——乡下打扮的老太太，挎着一篮子鸡蛋和自腌的辣菜，进门先拉着你的手看：「好孩子，手是做事的手。」","options":[{"text":"奉茶，留她用饭","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"老太太越看越欢喜，鸡蛋硬塞下才肯坐。","source":"宋代议婚，婆母相看媳妇之俗。"},{"text":"紧张得躲进灶间","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"老太太倒笑了：「害羞什么，我又不吃人。」","source":"宋代议婚，婆母相看媳妇之俗。"}],"difficulty":2,"npc":["陈母"],"foreshadow":"婆母这一关，过得暖暖和和"},{"id":"E-057-戌","branch":"E","stage":3,"day":57,"shichen":"戌时","checkpoint":"陈家提亲·二","scene":"送走陈母，七郎站在店门口不敢进来，你朝他晃晃手里的辣菜坛子：「你娘说了，往后这坛子归我管。」","options":[{"text":"让他进来帮着腌","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"一坛辣菜两个人腌，辣椒呛出眼泪也笑着。","source":"宋代家常腌菜，市井日常之景。"},{"text":"说坛子太沉拿不动","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「我来！」他三步并两步，差点撞上门框。","source":"宋代家常腌菜，市井日常之景。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"辣菜坛子，从定情到定亲"},{"id":"E-057-未","branch":"E","stage":3,"day":57,"shichen":"未时","checkpoint":"陈家提亲·三","scene":"陈母拉着你说体己话：「七郎爹去得早，家里就三间瓦房。你不嫌寒酸，老婆子就替他来提这个亲。」","options":[{"text":"应下：我有人有店","correct":true,"tags":["感情","自主"],"dims":{"情缘":2,"自主":1},"feedback":"「房子我有，店我有，就缺个烧火的。」老太太笑出泪来。","source":"宋代市井婚嫁，不重门第重实干者渐多。"},{"text":"说要再想想","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老太太点头说好，可七郎在灶间把锅铲掉地上了。","source":"宋代市井婚嫁，不重门第重实干者渐多。"}],"difficulty":2,"npc":["陈母","陈七郎"],"foreshadow":"亲事定了口，只等行礼"},{"id":"E-058","branch":"E","stage":3,"day":58,"shichen":"辰时","checkpoint":"陈家提亲·四","scene":"亲事要过明路。陈母请了街上最正派的官媒，按规矩先来「问名」——问你的生辰八字。","options":[{"text":"请掌柜娘子代为主持","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"你无长辈，娘子便当这个娘家人，体面周全。","source":"宋代婚六礼，问名为第二礼。"},{"text":"自己出面应对官媒","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"不是不行，可礼数上总差着一层。","source":"宋代婚六礼，问名为第二礼。"}],"difficulty":2,"npc":["官媒","掌柜娘子"],"foreshadow":"掌柜娘子成了她的'娘家人'"},{"id":"E-058-戌","branch":"E","stage":3,"day":58,"shichen":"戌时","checkpoint":"陈家提亲·五","scene":"晚上大嫂知道了信儿，拉着你的手直抹眼睛：「打从桥洞边见你头一面，我就知道你有这一天。」","options":[{"text":"请大嫂做全福人","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「我给你铺床挂帐！」大嫂破涕为笑。","source":"宋代婚俗，请全福妇人铺床。"},{"text":"抱着她一起掉泪","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"哭完笑完，这一年的酸甜苦辣都值了。","source":"宋代婚俗，请全福妇人铺床。"}],"flavor":true,"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"大嫂挂帐，婚礼有了张罗人"},{"id":"E-058-未","branch":"E","stage":3,"day":58,"shichen":"未时","checkpoint":"陈家提亲·六","scene":"官媒合了八字回来，满脸堆笑：「天作之合！」接下来是纳采——陈家要送定礼来。","options":[{"text":"定礼从简，心意到","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「礼轻情意重，日子是人过的。」官媒都点头。","source":"宋代纳采之礼，贫富各有其仪。"},{"text":"随陈家的规矩办","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"陈家寒酸，强撑排场反倒累了两家。","source":"宋代纳采之礼，贫富各有其仪。"}],"difficulty":2,"npc":["官媒"],"foreshadow":"纳采从简，是她自己定的调"},{"id":"E-059","branch":"E","stage":3,"day":59,"shichen":"辰时","checkpoint":"纳采议婚","scene":"纳采这日，陈家抬来雁礼和几色果子。按规矩你要回礼。你看着灶上的炉子，有了主意。","options":[{"text":"回一笼亲手做的饼","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「手艺人的回礼。」陈母捧着，比金子还看重。","source":"宋代纳采回礼，多以女红吃食为答。"},{"text":"回匹好布料","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"布料是好，可不如你的手艺贴心。","source":"宋代纳采回礼，多以女红吃食为答。"}],"difficulty":1,"npc":["陈母","官媒"],"foreshadow":"她的回礼，就是这个家的底色"},{"id":"E-059-戌","branch":"E","stage":3,"day":59,"shichen":"戌时","checkpoint":"纳采议婚·二","scene":"夜里七郎把那支银簪拿来了——攒了许久，簪头刻着一朵小小的炊饼花，憨得很。","options":[{"text":"让他亲手插上","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"他手抖，插了三次才插正，你俩都笑了。","source":"宋代定情赠簪，簪发及笄之喻。"},{"text":"收下先不戴","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「成亲那日戴。」他重重点头，「我等着。」","source":"宋代定情赠簪，簪发及笄之喻。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"炊饼花银簪，成亲日要戴"},{"id":"E-059-未","branch":"E","stage":3,"day":59,"shichen":"未时","checkpoint":"纳采议婚·三","scene":"纳采过后，消息长了腿。下午来道喜的络绎不绝，也有酸话：「厨子配厨娘，倒是天生一对市井夫妻。」","options":[{"text":"笑着应下这句话","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「市井夫妻，烟火日子，挺好。」说酸话的自讨没趣。","source":"宋人笔记记市井之婚，怡然自得。"},{"text":"拉下脸怼回去","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"怼赢了，大喜的日子里添了堵。","source":"宋人笔记记市井之婚，怡然自得。"}],"difficulty":2,"npc":[],"foreshadow":"「市井夫妻」四个字，她接得坦然"},{"id":"E-060","branch":"E","stage":3,"day":60,"shichen":"辰时","checkpoint":"纳采议婚·四","scene":"议婚期。官媒给了三个吉日：下月初八、十八、廿八。七郎急着要初八，你却看着店账犯了思量。","options":[{"text":"选廿八，攒够嫁妆","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"多二十天，店里进项和嫁妆都能从容些。","source":"宋代婚期择吉，亦需量力而行。"},{"text":"依他选初八","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"急是遂了他的愿，筹备却手忙脚乱。","source":"宋代婚期择吉，亦需量力而行。"}],"difficulty":2,"npc":["官媒","陈七郎"],"foreshadow":"婚期廿八，checkpoint 收官"},{"id":"E-060-戌","branch":"E","stage":3,"day":60,"shichen":"戌时","checkpoint":"纳采议婚·五","scene":"晚上盘账，你忽然想起来问七郎：「成亲后，这店算谁的？」他愣住：「啊？」","options":[{"text":"算俩人的，账照旧","correct":true,"tags":["感情","自主"],"dims":{"情缘":1,"自主":2},"feedback":"「店是俩人的，勺子是你的，火是我的。」他答得顺溜。","source":"宋代夫妻共营产业，市中常见。"},{"text":"说各管各的账","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他挠头：「都一家人了还分账？那我不管钱了。」","source":"宋代夫妻共营产业，市中常见。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"夫妻同店的章程，婚前先讲明"},{"id":"E-060-未","branch":"E","stage":3,"day":60,"shichen":"未时","checkpoint":"纳采议婚·六","scene":"定下婚期，你去相国寺上香还愿。回来路上买了两根红绳——一根给木梳换新，一根留着。","options":[{"text":"另一根留到成亲日","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"红绳系发，是娘知道的缘故。","source":"宋代女子以红绳系发为饰。"},{"text":"给七郎系在腕上","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"他举着腕子看了一路，差点撞树上。","source":"宋代女子以红绳系发为饰。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"两根红绳，一根念娘，一根系他"},{"id":"E-061","branch":"E","stage":3,"day":61,"shichen":"辰时","checkpoint":"备婚诸事","scene":"婚期定了，嫁妆要备。舅母带着表姐上门，抬来两箱绸缎：「娘家出的，不许推。」","options":[{"text":"收下，记进奁单","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"奁单上添了'舅府'一行，亲缘彻底续上了。","source":"宋代嫁妆置奁单，亲族添箱为礼。"},{"text":"坚持自己备","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"推回去容易，舅母眼圈却红了。","source":"宋代嫁妆置奁单，亲族添箱为礼。"}],"difficulty":2,"npc":["舅母","表姐"],"foreshadow":"舅家添箱，嫌贫的旧账翻了篇"},{"id":"E-061-戌","branch":"E","stage":3,"day":61,"shichen":"戌时","checkpoint":"备婚诸事·二","scene":"夜里清点奁单：绸缎、桌椅、碗碟、还有七郎那把刻着「汤」字的木勺——他红着脸说这也算聘礼。","options":[{"text":"把木勺记在头一行","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"头一件不是金不是银，是一把磨了三天的木勺。","source":"宋代奁单列嫁妆，贵贱皆可入册。"},{"text":"笑它上不了奁单","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「那也记。」他抢过笔自己写上了。","source":"宋代奁单列嫁妆，贵贱皆可入册。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"奁单头一行：一把木勺"},{"id":"E-061-未","branch":"E","stage":3,"day":61,"shichen":"未时","checkpoint":"备婚诸事·三","scene":"店里的事要安排：成亲那几日歇业，可老客的嘴不能断。你和七郎商量怎么办。","options":[{"text":"歇三日，赠老客券","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"歇业送饼券，复业那天客还回来。","source":"宋代商铺婚嫁歇业，酬客为常。"},{"text":"婚期照常营业","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"铁打的人也扛不住——七郎头一个反对。","source":"宋代商铺婚嫁歇业，酬客为常。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"歇业三日，婚后再开张"},{"id":"E-062","branch":"E","stage":3,"day":62,"shichen":"辰时","checkpoint":"备婚诸事·四","scene":"裁嫁衣。绸缎庄管事娘子亲自来量尺寸，问你绣什么花样：「并蒂莲？还是鸳鸯？」","options":[{"text":"绣一穗麦子","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"七郎家乡的麦子，也是他第一眼认你的缘故。","source":"宋代嫁衣刺绣，花样各取其意。"},{"text":"照时兴的绣鸳鸯","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"好看是好看，可满汴京的嫁衣都一样。","source":"宋代嫁衣刺绣，花样各取其意。"}],"difficulty":1,"npc":["管事娘子"],"foreshadow":"麦穗嫁衣，独一份的花样"},{"id":"E-062-戌","branch":"E","stage":3,"day":62,"shichen":"戌时","checkpoint":"备婚诸事·五","scene":"夜里你翻出嫁衣料子比划，大嫂在一旁絮絮叨叨讲婚礼的规矩：「跨火盆、拜天地、挑盖头……」","options":[{"text":"一条条记在心里","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"大嫂讲得细，你听得认真，心里渐渐有了画面。","source":"《东京梦华录》记汴京婚俗甚详。"},{"text":"听到一半脸红跑了","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"大嫂在后头笑：「跑什么，早晚的事！」","source":"《东京梦华录》记汴京婚俗甚详。"}],"flavor":true,"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"婚礼的规矩，大嫂包了"},{"id":"E-062-未","branch":"E","stage":3,"day":62,"shichen":"未时","checkpoint":"备婚诸事·六","scene":"午后小豆子扭扭捏捏来了，掏出一只草编的蚱蜢：「姐，成亲……我能去吗？」","options":[{"text":"让他当傧相跑腿","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子蹦起来：「我保管把红包都讨回来！」","source":"宋代婚礼傧相，多以亲近少年充任。"},{"text":"说到时给他留席","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"留席是好，可孩子想的是「有用」。","source":"宋代婚礼傧相，多以亲近少年充任。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"小豆子当傧相，婚礼有了少年气"},{"id":"E-063","branch":"E","stage":3,"day":63,"shichen":"辰时","checkpoint":"备婚诸事·七","scene":"一早，陈母从乡下赶来，带来一只包袱皮——里面是七郎爹当年留下的一对银镯：「给儿媳妇的。」","options":[{"text":"跪下接了","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"这一跪，是把两家跪成了一家。","source":"宋代婚俗，婆母赠媳以传家之物。"},{"text":"推说太贵重","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老太太急了：「不传给你传给谁！」","source":"宋代婚俗，婆母赠媳以传家之物。"}],"difficulty":1,"npc":["陈母"],"foreshadow":"银镯传家，婆心已属"},{"id":"E-063-戌","branch":"E","stage":3,"day":63,"shichen":"戌时","checkpoint":"备婚诸事·八","scene":"七郎听说你减了聘礼，打烊后站在你面前搓着手，半天憋出一句：「委屈你了。」","options":[{"text":"说：我的聘礼是你","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"他愣了半天，眼圈红了，转身去劈了一垛柴。","source":"宋人笔记记市井儿女朴挚之语。"},{"text":"让他往后好好干活","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「嗯！烧一辈子火！」他应得像发誓。","source":"宋人笔记记市井儿女朴挚之语。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"「我的聘礼是你」，全剧情话之最"},{"id":"E-063-未","branch":"E","stage":3,"day":63,"shichen":"未时","checkpoint":"备婚诸事·九","scene":"官媒来催纳征的聘礼单子。陈家底子薄，陈母愁得一晚没睡。你听说了，心里有了主张。","options":[{"text":"主动减单，只取其意","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「聘礼轻些，日子重些。」官媒都说没见过这么明理的。","source":"宋代纳征厚薄，两家相商为常。"},{"text":"按常例不忍破例","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"聘礼厚了，陈家要举债——婚后的担子还是你俩的。","source":"宋代纳征厚薄，两家相商为常。"}],"difficulty":2,"npc":["官媒","陈母"],"foreshadow":"她的底气：店面是自己的，不靠聘礼撑腰"},{"id":"E-064","branch":"E","stage":3,"day":64,"shichen":"辰时","checkpoint":"备婚诸事·十","scene":"婚前要挪窝。柴房小了，你在州桥后巷赁了间带小院的屋子——往后既是家，也能当店里的后灶。","options":[{"text":"亲手布置新房","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"窗纸新糊，炕席新铺，桌上摆了娘的梳子。","source":"宋代赁屋成婚，市井常态。"},{"text":"交给大嫂她们张罗","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"布置得是好，可总少了一点自己的意思。","source":"宋代赁屋成婚，市井常态。"}],"difficulty":1,"npc":[],"foreshadow":"小院新房，是婚后的大本营"},{"id":"E-064-戌","branch":"E","stage":3,"day":64,"shichen":"戌时","checkpoint":"备婚诸事·十一","scene":"在新房吃第一顿饭。七郎掌勺，你烧火——跟说好的正好反过来。两人笑作一团。","options":[{"text":"说往后轮换着来","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「行。」他说，「你烧火的日子，我多炒个菜。」","source":"宋代市井夫妻，灶上分工寻常。"},{"text":"夸他手艺又进了","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「那是。」他得意，「师父教得好。」","source":"宋代市井夫妻，灶上分工寻常。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"新房第一餐，烟火气落定"},{"id":"E-064-未","branch":"E","stage":3,"day":64,"shichen":"未时","checkpoint":"备婚诸事·十二","scene":"搬家这日，柴房里的东西一趟就搬完了。最后你站在空屋里，看墙皮上那一片密密麻麻的炭条账。","options":[{"text":"揭下一块带走","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"墙皮会碎，可那段日子，谁也拿不走。","source":"宋代民居多以墙皮记事。"},{"text":"拓下来收好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"看是看熟了，回头想留点念想却没了。","source":"宋代民居多以墙皮记事。"}],"difficulty":2,"npc":[],"foreshadow":"墙皮账，将来可以讲给孩子听"},{"id":"E-065","branch":"E","stage":3,"day":65,"shichen":"辰时","checkpoint":"婚前风波","scene":"婚前三天，风言风语起来了：有人说七郎「吃软饭」，图的是你的店。话传到七郎耳朵里。","options":[{"text":"当众把话说开","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「店是两人攒钱盘的，契上两个名字。」闲话噎了回去。","source":"宋代合伙契书，具名即为铁证。"},{"text":"不理会，随他们说","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"话不说不明，七郎心里那根刺还在。","source":"宋代合伙契书，具名即为铁证。"}],"difficulty":2,"npc":[],"foreshadow":"契上两个名字，堵住悠悠众口"},{"id":"E-065-戌","branch":"E","stage":3,"day":65,"shichen":"戌时","checkpoint":"婚前风波·二","scene":"夜里你把两把木勺并排挂在灶边——「汤」和「记」，挨在一起。七郎进来看见，站在那儿看了很久。","options":[{"text":"说：勺子都成双了","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「嗯。」他从背后把围裙递给你，「人也该成双了。」","source":"宋代市井以物寄情，朴拙动人。"},{"text":"问他还在意闲话吗","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「勺子不答话。」他说，「它俩挂着就挺好。」","source":"宋代市井以物寄情，朴拙动人。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"木勺成双，人也将成双"},{"id":"E-065-未","branch":"E","stage":3,"day":65,"shichen":"未时","checkpoint":"婚前风波·三","scene":"七郎蹲在河边生闷气。你找过去，他闷声说：「往后店里的进项，我那份全交给你管。」","options":[{"text":"说：管钱不如管我","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"他猛地抬头，河面上夕阳正好。","source":"宋人笔记记市井儿女言语之真。"},{"text":"应下，让他宽心","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"钱交了，心结却没解开——他怕的是配不上。","source":"宋人笔记记市井儿女言语之真。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"他的心结，要在婚礼上解开"},{"id":"E-066","branch":"E","stage":3,"day":66,"shichen":"辰时","checkpoint":"婚前风波·四","scene":"婚前两天，店里来了位意想不到的客人——张员外家的管家，说二公子「仰慕小娘子手艺」，订了五十人份的外送。","options":[{"text":"接单，按规矩办","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"生意是生意，钱是干净的，凭什么不接。","source":"宋代食店外送宴席，称'四司六局'之属。"},{"text":"疑有文章，推了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"推了单，闲话更多：「心虚才不敢接。」","source":"宋代食店外送宴席，称'四司六局'之属。"}],"difficulty":2,"npc":["张府管家"],"foreshadow":"张员外家的单子，婚前最后一场考"},{"id":"E-066-戌","branch":"E","stage":3,"day":66,"shichen":"戌时","checkpoint":"婚前风波·五","scene":"回来跟七郎学说张府的事，他听完松了口气，又有点得意：「五十人份……他们家人真能吃。」","options":[{"text":"说人家是冲手艺来的","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「那也是我媳妇的手艺。」他现在敢这么说了。","source":"《东京梦华录》记汴京食店声名远播之景。"},{"text":"问他吃醋没有","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「吃了。」他老实承认，「蘸着饼吃的。」","source":"《东京梦华录》记汴京食店声名远播之景。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"「我媳妇」，他叫顺口了"},{"id":"E-066-未","branch":"E","stage":3,"day":66,"shichen":"未时","checkpoint":"婚前风波·六","scene":"送货到张府，二公子果然亲自出来「验货」，言语间试探你的婚事。","options":[{"text":"坦然说已有婚约","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「下月廿八，嫁州桥陈七郎。」他拱手，心服口服。","source":"宋代女子自陈婚约，坦荡无碍。"},{"text":"含糊应付过去","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"越含糊，对方越觉得有缝可钻。","source":"宋代女子自陈婚约，坦荡无碍。"}],"difficulty":2,"npc":["张府二公子"],"foreshadow":"坦荡一句话，断了所有念想"},{"id":"E-067","branch":"E","stage":3,"day":67,"shichen":"辰时","checkpoint":"婚期将近","scene":"婚前一日，「上头」的仪式。大嫂执梳为你开脸梳头，一下一下，梳到第三下，她的手顿了顿。","options":[{"text":"说：嫂就是我娘家人","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"大嫂眼泪掉下来，手上的梳却很稳。","source":"宋代女子婚前开脸，全福妇人执梳。"},{"text":"忍着不回头","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"镜子里看见她抹眼睛，你也差点没忍住。","source":"宋代女子婚前开脸，全福妇人执梳。"}],"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"大嫂执梳，替的是娘的位置"},{"id":"E-067-戌","branch":"E","stage":3,"day":67,"shichen":"戌时","checkpoint":"婚期将近·二","scene":"婚前最后一夜。按规矩新人不能见面。七郎托小豆子捎来个纸包：一个还热乎的炊饼，夹着羊肠。","options":[{"text":"咬一口，留着明早吃","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"饼是甜的——他偷偷多放了蜜。","source":"宋代婚前新人不相见之俗。"},{"text":"让小豆子回送一碗汤","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"一碗热汤送过两条巷，还着当年的那碗。","source":"宋代婚前新人不相见之俗。"}],"flavor":true,"difficulty":1,"npc":["小豆子","陈七郎"],"foreshadow":"婚前夜的一饼一汤，还清了day8的旧账"},{"id":"E-067-未","branch":"E","stage":3,"day":67,"shichen":"未时","checkpoint":"婚期将近·三","scene":"午后你把娘留下的木梳取出来，用新红绳重新缠好，放进奁匣最上头——嫁妆再多，它是头一件。","options":[{"text":"对着梳子说会话","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「娘，女儿要嫁人了。嫁的是自己选的人。」","source":"宋代女子以母亲遗物入奁为念。"},{"text":"请大嫂放进奁匣","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"大嫂放得郑重，可总觉得该自己亲手来。","source":"宋代女子以母亲遗物入奁为念。"}],"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"木梳入奁，娘的念想陪嫁"},{"id":"E-068","branch":"E","stage":3,"day":68,"shichen":"辰时","checkpoint":"大喜之日","scene":"成亲日。天没亮，全院的人忙成一团。你穿上麦穗嫁衣，插上那支炊饼花银簪，镜子里的自己陌生又熟悉。","options":[{"text":"深吸气，盖上盖头","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"盖头落下的那一刻，外头炮仗响了。","source":"《东京梦华录》记新人冠帔盖头之仪。"},{"text":"再检查一遍簪子","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"簪子很好，是大嫂在外头催了第三遍。","source":"《东京梦华录》记新人冠帔盖头之仪。"}],"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"麦穗嫁衣+炊饼银簪，全副心事上身"},{"id":"E-068-戌","branch":"E","stage":3,"day":68,"shichen":"戌时","checkpoint":"大喜之日·二","scene":"洞房。盖头挑开，烛光里他看你，看了很久很久，说：「钗裙之下的你，比灶前的你还好看。」","options":[{"text":"说：往后都是你的","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"烛花爆了一声，窗外的州桥灯火通明。","source":"《东京梦华录》记挑盖头饮交杯之俗。"},{"text":"把合卺酒递给他","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"交杯一饮而尽，从赊汤到合卺，整七十天。","source":"《东京梦华录》记挑盖头饮交杯之俗。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"大喜礼成，从一碗汤到一杯酒"},{"id":"E-068-未","branch":"E","stage":3,"day":68,"shichen":"未时","checkpoint":"大喜之日·三","scene":"花轿到门，七郎一身新衣来接。拜天地，拜高堂——陈母坐在上首，你这一侧，坐着掌柜娘子、舅父舅母。","options":[{"text":"郑重三拜","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"夫妻对拜时，他在盖头下轻声说：「委屈你跟我了。」","source":"《东京梦华录》记拜堂之礼。"},{"text":"拜得快些怕误吉时","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"司仪直喊「慢些慢些」，满堂哄笑。","source":"《东京梦华录》记拜堂之礼。"}],"difficulty":1,"npc":["陈七郎","陈母","掌柜娘子","舅父","舅母"],"foreshadow":"高堂满座，孤女有了满堂亲"},{"id":"E-069","branch":"E","stage":3,"day":69,"shichen":"辰时","checkpoint":"新婚燕尔","scene":"新婚第一日。你天不亮醒了，习惯性地要起身去生火，被七郎按住：「今日你是新妇，火归我生。」","options":[{"text":"躺着看他生火","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"他生火的背影，比汴京的日头还暖。","source":"宋代新妇三日不下厨之俗。"},{"text":"还是起来搭把手","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他拗不过你，两人挤在灶间，倒像从前。","source":"宋代新妇三日不下厨之俗。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"新妇三日，是他给的体己"},{"id":"E-069-戌","branch":"E","stage":3,"day":69,"shichen":"戌时","checkpoint":"新婚燕尔·二","scene":"夜里对坐，两人把婚礼收的礼单理了一遍。七郎忽然说：「明日……回门。」","options":[{"text":"愣住：我回哪门","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「回舅家。」他说，「你如今是有娘家的人了。」","source":"宋代婚后三日回门之俗。"},{"text":"眼圈一热","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"投亲不遇的门，如今要风风光光回。","source":"宋代婚后三日回门之俗。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"回门，是day1那扇门的回响"},{"id":"E-069-未","branch":"E","stage":3,"day":69,"shichen":"未时","checkpoint":"新婚燕尔·三","scene":"午后陈母要回乡下了，拉着你的手交代：「店是你们俩的，好好过。生不生孩子……不急。」","options":[{"text":"应下，常接她来住","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"老太太上车前塞给你一包自己晒的干菜。","source":"宋代婆媳相处，以厚待为和。"},{"text":"说些场面话送行","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"话说得圆，可老人要的是贴心。","source":"宋代婆媳相处，以厚待为和。"}],"difficulty":1,"npc":["陈母"],"foreshadow":"婆媳这条线，开了个好头"},{"id":"E-070","branch":"E","stage":3,"day":70,"shichen":"辰时","checkpoint":"回门之礼","scene":"回门日。七郎换了新衣，挑着礼担——里面有你亲手做的饼、两坛酱、一匹绸子。你走在州桥上，街坊一路道喜。","options":[{"text":"一路笑着还礼","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"从桥洞边到回门客，这条路你走了七十天。","source":"《东京梦华录》记回门携礼之俗。"},{"text":"催他走快些","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"喜日里的人情，正是要慢慢走的。","source":"《东京梦华录》记回门携礼之俗。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"回门一路，是整条街的见证"},{"id":"E-070-戌","branch":"E","stage":3,"day":70,"shichen":"戌时","checkpoint":"回门之礼·二","scene":"回门宴散，表姐送你们到门口，塞给你一包东西：「你成亲我没能添箱，这是我绣的枕套，一对。」","options":[{"text":"收下，抱了抱她","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"「往后常来往。」她在你耳边说，「谢谢你当日那碗汤。」","source":"宋代亲眷馈赠，枕衾为贴心之礼。"},{"text":"说让她留着自己用","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"她执意塞过来：「绣的就是你们的。」","source":"宋代亲眷馈赠，枕衾为贴心之礼。"}],"flavor":true,"difficulty":1,"npc":["表姐"],"foreshadow":"一碗汤结下的缘，回了一对枕套"},{"id":"E-070-未","branch":"E","stage":3,"day":70,"shichen":"未时","checkpoint":"回门之礼·三","scene":"舅府门房远远迎出来，腰弯得极低。正厅里舅父亲自斟茶，当着全家说：「我这外甥女，是我最得意的晚辈。」","options":[{"text":"敬茶，叫一声舅父","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"这一声等了一年。舅父眼眶红了。","source":"宋人笔记记亲族释怨复和之事。"},{"text":"淡淡应着","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"茶是喝了，可那句'舅父'没出口，满座都觉出来了。","source":"宋人笔记记亲族释怨复和之事。"}],"difficulty":2,"npc":["舅父","舅母"],"foreshadow":"回门一声舅父，恩怨两清"},{"id":"E-071","branch":"E","stage":3,"day":71,"shichen":"辰时","checkpoint":"复业新张","scene":"婚假毕，「汤记」复业。门口贴了喜联，老客们拿着饼券回来，一进门就喊：「东家娘，恭喜！」","options":[{"text":"加送喜饼一对","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"复业变贺喜，店里比开张那日还热闹。","source":"宋代商铺喜事酬客，人情的常道。"},{"text":"照常营业不声张","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"喜气藏不住，可你不添一把，总淡了些。","source":"宋代商铺喜事酬客，人情的常道。"}],"difficulty":1,"npc":[],"foreshadow":"复业之喜，人气再涨一截"},{"id":"E-071-戌","branch":"E","stage":3,"day":71,"shichen":"戌时","checkpoint":"复业新张·二","scene":"打烊后小两口对账。你拨着算盘，他研墨记账，谁也不说话，可账目一分不差。","options":[{"text":"说：这就是过日子","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「嗯。」他头也没抬，「过一辈子那种。」","source":"宋代夫妻同店经营，账目清明为常。"},{"text":"考他一道算题","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"他算得慢，可对——手艺人的脑子都长在手上。","source":"宋代夫妻同店经营，账目清明为常。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"柴米夫妻，账目里过出情意"},{"id":"E-071-未","branch":"E","stage":3,"day":71,"shichen":"未时","checkpoint":"复业新张·三","scene":"午后盘账，成婚这几日店里歇业，但老摊和茶坊食档照转，进项竟没断。班底熟了。","options":[{"text":"给老摊涨工钱","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"陈伯摆手不要，你硬塞进他兜里：「该的。」","source":"宋代商铺酬劳得力伙计，常例。"},{"text":"按原数发就好","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"钱是省了，可人心是要焐的。","source":"宋代商铺酬劳得力伙计，常例。"}],"difficulty":2,"npc":["老仆陈伯","丫头杏儿"],"foreshadow":"摊子能自转了，她可谋划更大的局"},{"id":"E-072","branch":"E","stage":3,"day":72,"shichen":"辰时","checkpoint":"婚后经营","scene":"一早，老虞候拄杖来店里吃头汤。喝完放下碗，慢悠悠说：「南边要修桥，工匠上百号人，晌饭还没着落。」","options":[{"text":"当场应下包伙","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"百人的晌饭，一个月的稳进项，老人是特意留给你的。","source":"宋代官府工程包伙食，商铺争揽。"},{"text":"说店里忙不过来","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老人点点头没再说——机会递过来，接不接在你。","source":"宋代官府工程包伙食，商铺争揽。"}],"difficulty":2,"npc":["老虞候"],"foreshadow":"包伙生意，食店上台阶的跳板"},{"id":"E-072-戌","branch":"E","stage":3,"day":72,"shichen":"戌时","checkpoint":"婚后经营·二","scene":"入夜，两人把包伙的章程议定了。七郎合上账本，忽然说：「照这么干，年底能再盘一间铺子。」","options":[{"text":"说那就干","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「分号。」他眼睛亮，「就叫小豆子的字。」","source":"宋代汴京食店开设分号者渐多。"},{"text":"让他先把这家守好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"守成也对，可他眼里的火苗暗了暗。","source":"宋代汴京食店开设分号者渐多。"}],"flavor":false,"difficulty":2,"npc":["陈七郎"],"foreshadow":"分号的念想，stage4 的种子"},{"id":"E-072-未","branch":"E","stage":3,"day":72,"shichen":"未时","checkpoint":"婚后经营·三","scene":"包伙要添人手、添锅灶。你和七郎核计本钱，还差些。正发愁，大嫂来了：「我那摊子，想并进来。」","options":[{"text":"并摊入股，立契","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"摊子并进来，人手本钱都有了，大嫂成了股东。","source":"宋代商铺合伙并股，立契为凭。"},{"text":"婉谢，另想法子","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大嫂悻悻的：「嫌我摊子小？」","source":"宋代商铺合伙并股，立契为凭。"}],"difficulty":2,"npc":["邻摊大嫂"],"foreshadow":"大嫂入股，食店添了一条臂膀"},{"id":"E-073","branch":"E","stage":3,"day":73,"shichen":"辰时","checkpoint":"包伙开工","scene":"修桥工匠包伙第一天。百人份的菜，天不亮备料。你掌大勺，七郎切配，杏儿小豆子跑前跑后。","options":[{"text":"分量只多不少","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"工匠们吃得扎实，活儿干得也卖力，工头直夸。","source":"宋代包伙以量为先，厚道者赢口碑。"},{"text":"卡着分量省成本","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"省下几十文，落了个'抠门'的名声。","source":"宋代包伙以量为先，厚道者赢口碑。"}],"difficulty":2,"npc":["丫头杏儿","小豆子"],"foreshadow":"包伙厚道，又一条口碑传出去了"},{"id":"E-073-戌","branch":"E","stage":3,"day":73,"shichen":"戌时","checkpoint":"包伙开工·二","scene":"夜里两人在灯下核包伙的账。算完，七郎把笔一放：「这月净入，能顶从前半年。」","options":[{"text":"说存一半备分号","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「嗯。」他重新拿起笔，在账尾写：分号，存。","source":"宋代商铺盈余储积，以图扩展。"},{"text":"先添置家里物件","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"家底是要添，可钱生钱的道理他懂。","source":"宋代商铺盈余储积，以图扩展。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"分号存钱罐，正式启动"},{"id":"E-073-未","branch":"E","stage":3,"day":73,"shichen":"未时","checkpoint":"包伙开工·三","scene":"午后送货回来，撞见官媒又上门——这回是替别家小娘子来打听「汤记」的小伙计。","options":[{"text":"笑说伙计还小","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"官媒走后你乐：连伙计都有人惦记了。","source":"宋代市井说媒，商铺伙计亦在其列。"},{"text":"让官媒留意好人家","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"官媒认真记下：「杏儿大了，也该说亲了。」","source":"宋代市井说媒，商铺伙计亦在其列。"}],"difficulty":1,"npc":["官媒","丫头杏儿"],"foreshadow":"杏儿的亲事，stage4 可展开"},{"id":"E-074","branch":"E","stage":3,"day":74,"shichen":"辰时","checkpoint":"阶段回望","scene":"进城第七十四天。你一早在灶前忙活，恍惚想起第一天在州桥边冻得发抖的自己。","options":[{"text":"把这一感想说给七郎","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"他听完没说话，往你碗里多卧了个蛋。","source":"宋人笔记多言寒微起家之不易。"},{"text":"摇摇头继续干活","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"过去了就过去吧——可有些话，说出来更好。","source":"宋人笔记多言寒微起家之不易。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"回望起意，为收官蓄势"},{"id":"E-074-戌","branch":"E","stage":3,"day":74,"shichen":"戌时","checkpoint":"阶段回望·二","scene":"夜里收工早，两人坐在院里乘凉。七郎忽然问：「往后有了孩子，让不让他学厨？」","options":[{"text":"说先学认字","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「像小豆子那样。」他点头：「那就认字。」","source":"宋代市井人家，亦重子弟读书识字。"},{"text":"说随他自己选","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「像你。」他说，「你这辈子就是自己选的。」","source":"宋代市井人家，亦重子弟读书识字。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"孩子的话题，往后日子的影子"},{"id":"E-074-未","branch":"E","stage":3,"day":74,"shichen":"未时","checkpoint":"阶段回望·三","scene":"午后老虞候来吃茶，看着你忙里忙外，忽然说：「老夫在州桥四十年，看走眼过不少人。你，没看走眼。」","options":[{"text":"斟茶谢老人","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「谢您那碗头汤。」老人摆摆手，笑得皱纹都开了。","source":"宋代市井耆老，一言可立人之名。"},{"text":"请他为分号题字","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老人高兴应下，可分号八字还没一撇，急了些。","source":"宋代市井耆老，一言可立人之名。"}],"difficulty":2,"npc":["老虞候"],"foreshadow":"老人的认可，是州桥最高的'匾额'"},{"id":"E-075","branch":"E","stage":3,"day":75,"shichen":"辰时","checkpoint":"阶段三收官","scene":"收官日一早，你把娘的木梳从奁匣里取出来，换上新红绳，别回衣襟——往后天天带着。","options":[{"text":"带着它去开店","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"梳子贴着心口，娘跟着你过了这一天。","source":"宋代女子随身佩梳，念亲之习。"},{"text":"收进匣里供着","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"供起来是敬重，可念想该贴着心口。","source":"宋代女子随身佩梳，念亲之习。"}],"difficulty":1,"npc":[],"foreshadow":"木梳随身，念想化作日常"},{"id":"E-075-戌","branch":"E","stage":3,"day":75,"shichen":"戌时","checkpoint":"阶段三收官·二","scene":"入夜打烊，灯笼上的「州桥汤记」亮堂堂。你站在店门口，想起七十五天前州桥边那个抱着包袱的姑娘。","options":[{"text":"对她说：嫁出去了","correct":true,"tags":["感情"],"dims":{"情缘":2,"自主":1},"feedback":"嫁出去了——先嫁给了这双手，再嫁给了那个提灯的人。","source":"《东京梦华录》记汴京夜市灯火如昼。"},{"text":"对她说：站稳了","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"站稳了，往后就是往前走了。","source":"《东京梦华录》记汴京夜市灯火如昼。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"stage4 开启：分号、孩子、更大的汴京"},{"id":"E-075-未","branch":"E","stage":3,"day":75,"shichen":"未时","checkpoint":"阶段三收官·三","scene":"晌午店里最忙的时候，你在灶前抬头，看见七郎、陈伯、大嫂、杏儿、小豆子在各自的位子上忙，谁都不用喊。","options":[{"text":"心里默念一遍名字","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"这些人，是你的店，你的家，你的汴京。","source":"《东京梦华录》记汴京百业兴旺之盛。"},{"text":"扬声喊一句「开饭」","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"饭是喊开了，可你喉咙有点哽。","source":"《东京梦华录》记汴京百业兴旺之盛。"}],"difficulty":1,"npc":["陈七郎","老仆陈伯","邻摊大嫂","丫头杏儿","小豆子"],"foreshadow":"班底齐整，stage4 的根基"},{"id":"E-076","branch":"E","stage":4,"day":76,"shichen":"辰时","checkpoint":"分号谋划","scene":"开春，修桥包伙的尾款结了。分号存钱罐倒出来一数：连本带利，离再盘一间铺子只差三贯。","options":[{"text":"开始物色铺面","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"大相国寺东街有间小铺出让，位置正对庙门。","source":"《东京梦华录》记相国寺一带商铺林立。"},{"text":"再攒半年稳妥","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"稳妥是稳妥，好铺面可不等人。","source":"《东京梦华录》记相国寺一带商铺林立。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"相国寺东街的铺面，分号的候选"},{"id":"E-076-戌","branch":"E","stage":4,"day":76,"shichen":"戌时","checkpoint":"分号谋划·二","scene":"夜里算账，七郎忽然问：「分号开了，谁去守？」你俩同时想到了陈伯。","options":[{"text":"让陈伯当分号掌柜","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人守了一辈子灶，该有一间自己的店了。","source":"宋代商铺以老成伙计掌分号，常有。"},{"text":"再物色个年轻的","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"年轻的有的是，可信得过的没几个。","source":"宋代商铺以老成伙计掌分号，常有。"}],"difficulty":2,"npc":["陈七郎","老仆陈伯"],"foreshadow":"陈伯当掌柜，老将出马"},{"id":"E-076-未","branch":"E","stage":4,"day":76,"shichen":"未时","checkpoint":"分号谋划·三","scene":"午后你带七郎去看那间铺面。门板旧了，可灶台基脚结实，后院还有口甜水井。","options":[{"text":"相中，约东家谈价","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"甜水井是宝——做汤的水，比金子还紧要。","source":"《东京梦华录》记汴京饮食重井水。"},{"text":"嫌门面旧再看看","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"门面能翻新，水井可不是挖就有的。","source":"《东京梦华录》记汴京饮食重井水。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"甜水井，分号的命根子"},{"id":"E-077","branch":"E","stage":4,"day":77,"shichen":"辰时","checkpoint":"分号谋划·四","scene":"一早你去找陈伯说掌柜的事。老人听完，手在围裙上擦了三遍，半天说：「我这把年纪……」","options":[{"text":"说：店就要老成的","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「灶上认手艺，柜上认人。」老人眼圈红了。","source":"宋代商号以老成者为掌柜，重资历。"},{"text":"许他双份工钱","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"老人摆手：「不是钱的事，是怕误了你。」","source":"宋代商号以老成者为掌柜，重资历。"}],"difficulty":2,"npc":["老仆陈伯"],"foreshadow":"陈伯应承，分号有了主心骨"},{"id":"E-077-戌","branch":"E","stage":4,"day":77,"shichen":"戌时","checkpoint":"分号谋划·五","scene":"打烊后杏儿帮你收碗，忽然小声问：「姐，你说……认字的人，是不是挑婆家都挑得硬气些？」","options":[{"text":"笑：那就跟小豆子学","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"两个孩子在灯下比划字，你看着心里软。","source":"宋代市井女子识字渐多，以账用为先。"},{"text":"说嫁人是嫁人品","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"「人品加手艺，才硬气。」杏儿记下了。","source":"宋代市井女子识字渐多，以账用为先。"}],"flavor":true,"difficulty":1,"npc":["丫头杏儿","小豆子"],"foreshadow":"杏儿学认字，伏笔她和谁走得近"},{"id":"E-077-未","branch":"E","stage":4,"day":77,"shichen":"未时","checkpoint":"分号谋划·六","scene":"杏儿听说要开分号，干活更卖力了，可你看出她有心事——官媒又来了两回，说的是杏儿的亲事。","options":[{"text":"先问杏儿的意思","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「姐，我还想再跟你学两年。」丫头眼里有光。","source":"宋代女子及笄后议亲，本人亦可陈情。"},{"text":"替她应下官媒","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你替她做主，就像当年别人替你做主。","source":"宋代女子及笄后议亲，本人亦可陈情。"}],"difficulty":2,"npc":["丫头杏儿","官媒"],"foreshadow":"杏儿的亲事，她自己有主张"},{"id":"E-078","branch":"E","stage":4,"day":78,"shichen":"辰时","checkpoint":"分号谋划·七","scene":"铺面东家来谈价：连井带院要十二贯。你揣着九贯去的，还差三贯。","options":[{"text":"请舅父入股三成","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"舅父痛快出钱：「我出的不是钱，是信你。」","source":"宋代商铺合伙入股，亲族入伙常见。"},{"text":"借印子钱补齐","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孙三的教训就在眼前，这钱借不得。","source":"宋代商铺合伙入股，亲族入伙常见。"}],"difficulty":3,"npc":["舅父"],"foreshadow":"舅父入股，舅家合作正式落地"},{"id":"E-078-戌","branch":"E","stage":4,"day":78,"shichen":"戌时","checkpoint":"分号谋划·八","scene":"夜里小豆子听说招牌有了，急得直转：「姐，你说过分号的字给我写的！」","options":[{"text":"说灯笼归你写","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"匾是虞候的，灯笼是小豆子的，各得其所。","source":"宋代商铺灯笼字号，伙计亦可书写。"},{"text":"哄他下次再说","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子眼里的光暗了：「我字练得可好了……」","source":"宋代商铺灯笼字号，伙计亦可书写。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"小豆子的字，要挑上分号灯笼"},{"id":"E-078-未","branch":"E","stage":4,"day":78,"shichen":"未时","checkpoint":"分号谋划·九","scene":"契书立好，舅父临走时忽然问：「分号的招牌……题字之人可定了？」你想起老虞候的许诺。","options":[{"text":"去请老虞候题字","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人提笔写下「汤记贰号」，笔力遒劲。","source":"宋代商铺以名士题匾为荣。"},{"text":"让老童生再写一块","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"童生字好，可老虞候的字，是州桥的面子。","source":"宋代商铺以名士题匾为荣。"}],"difficulty":2,"npc":["老虞候","舅父"],"foreshadow":"题字兑现，「汤记贰号」有了名分"},{"id":"E-079","branch":"E","stage":4,"day":79,"shichen":"辰时","checkpoint":"分号筹备","scene":"一早，小豆子揣着一沓纸来找你——全是他练的字，一笔一划，从歪到正，足有三个月的功课。","options":[{"text":"一张张看完夸他","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「够格写灯笼了。」孩子蹦得比灶台还高。","source":"宋代市井童子习字，以记账书写为用。"},{"text":"挑几张好的就行","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"挑了好的，孩子把剩下的也宝贝似的收走了。","source":"宋代市井童子习字，以记账书写为用。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"小豆子练字有成，支线暖心推进"},{"id":"E-079-戌","branch":"E","stage":4,"day":79,"shichen":"戌时","checkpoint":"分号筹备·二","scene":"夜里收工，你有些乏，闻着油烟竟犯恶心。七郎紧张得要请大夫，你摆摆手，心里却咯噔一下。","options":[{"text":"请大嫂来悄悄问","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"大嫂听完笑了：「傻丫头，你这是有了。」","source":"宋代妇人有孕，家中妇人先察。"},{"text":"忍着不说","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"瞒是瞒不住的，七郎一宿没睡踏实。","source":"宋代妇人有孕，家中妇人先察。"}],"difficulty":2,"npc":["邻摊大嫂","陈七郎"],"foreshadow":"有孕之喜，添丁线开启"},{"id":"E-079-未","branch":"E","stage":4,"day":79,"shichen":"未时","checkpoint":"分号筹备·三","scene":"分号装修动工。木匠问灶眼砌几口、案板做多长，七郎蹲在工地上一一比划，比给自己家干活还上心。","options":[{"text":"让他全权拿主意","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"灶上的事他比谁都细——这间店是他的道场。","source":"宋代食店砌灶设案，匠人依东主之意。"},{"text":"事事都要过问","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你问得越细，他越束手束脚。","source":"宋代食店砌灶设案，匠人依东主之意。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"分号的灶，七郎一手把关"},{"id":"E-080","branch":"E","stage":4,"day":80,"shichen":"辰时","checkpoint":"分号筹备·四","scene":"一早你把消息告诉七郎。他愣在灶前，手里的锅铲当啷掉地上，捡了三次才捡起来。","options":[{"text":"笑他笨手笨脚","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「我要当爹了。」他跟灶台说了三遍。","source":"宋代民间报喜，丈夫闻信之态。"},{"text":"让他先别声张","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他憋了一上午，见谁都傻笑。","source":"宋代民间报喜，丈夫闻信之态。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"checkpoint 收官：添丁之喜落定"},{"id":"E-080-戌","branch":"E","stage":4,"day":80,"shichen":"戌时","checkpoint":"分号筹备·五","scene":"夜里你翻出那块墙皮账的拓片，给七郎讲柴房的日子。讲着讲着，他握住你的手：「往后讲给孩子听。」","options":[{"text":"说好，一起讲","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"拓片收进奁匣，和木梳放在一处。","source":"宋代民间以旧事训子弟，言传身教。"},{"text":"说孩子未必爱听","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「他爹娘的故事，怎么会不爱听。」他认真地说。","source":"宋代民间以旧事训子弟，言传身教。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"拓片与木梳，要传给下一代"},{"id":"E-080-未","branch":"E","stage":4,"day":80,"shichen":"未时","checkpoint":"分号筹备·六","scene":"午后七郎不让你沾手重活，你跟他争：「生意正忙，我歇着店里怎么办？」","options":[{"text":"分工：你管账他掌灶","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"柜上一坐，算盘一拨，照样是一店之主。","source":"宋代商铺妇人主柜管账，常见。"},{"text":"硬撑着照旧干","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大嫂听说了赶来骂你：「不要命了？」","source":"宋代商铺妇人主柜管账，常见。"}],"difficulty":2,"npc":["陈七郎","邻摊大嫂"],"foreshadow":"她转柜上，店务照旧运转"},{"id":"E-081","branch":"E","stage":4,"day":81,"shichen":"辰时","checkpoint":"添丁之喜","scene":"你有孕的消息传开，掌柜娘子头一个上门，拎来一篮子红皮鸡蛋：「店里柜上的事，我帮你盯着。」","options":[{"text":"谢她，托付账目","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"有娘子坐镇，你安心养胎，店里不乱。","source":"宋代商铺东主有孕，亲友代管账目。"},{"text":"说自己还能撑","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘子板起脸：「这不是逞强的时候。」","source":"宋代商铺东主有孕，亲友代管账目。"}],"difficulty":1,"npc":["掌柜娘子"],"foreshadow":"贵人齐上阵，她只需安心"},{"id":"E-081-戌","branch":"E","stage":4,"day":81,"shichen":"戌时","checkpoint":"添丁之喜·二","scene":"夜里七郎笨手笨脚地给未来的孩子做小木勺——比灶上那对还小一圈，勺柄刻了个歪歪扭扭的「三」。","options":[{"text":"问「三」是什么意","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「汤，记，三。」他憨笑，「一家三口。」","source":"宋代民间为新生儿备小物，父亲手作。"},{"text":"笑他刻得难看","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「孩子不嫌。」他把木勺揣回怀里接着磨。","source":"宋代民间为新生儿备小物，父亲手作。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"第三把木勺，「汤记三」凑齐"},{"id":"E-081-未","branch":"E","stage":4,"day":81,"shichen":"未时","checkpoint":"添丁之喜·三","scene":"舅母也得了信，送来一床百家被——舅府上下一百口人，一家讨了一块布头拼的。","options":[{"text":"郑重收下道谢","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"百家被盖的是百家福，舅家这份心到了。","source":"宋代民间以百家被贺孕妇，祈福之俗。"},{"text":"说太费心不必","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"舅母嗔怪：「一家人，说什么费心。」","source":"宋代民间以百家被贺孕妇，祈福之俗。"}],"difficulty":1,"npc":["舅母"],"foreshadow":"百家被，舅家彻底成了娘家"},{"id":"E-082","branch":"E","stage":4,"day":82,"shichen":"辰时","checkpoint":"分号上梁","scene":"分号装修到了上梁的日子。按规矩要祭梁，掌柜娘子说该请些体面人观礼，撑撑场面。","options":[{"text":"请老虞候来祭梁","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人欣然到场，撒梁钱时孩子们抢成一团。","source":"宋代上梁之礼，撒钱以祈吉。"},{"text":"简单办，不张扬","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"省事是省事，可新铺子的彩头短了些。","source":"宋代上梁之礼，撒钱以祈吉。"}],"difficulty":1,"npc":["老虞候","掌柜娘子"],"foreshadow":"上梁大吉，分号渐成型"},{"id":"E-082-戌","branch":"E","stage":4,"day":82,"shichen":"戌时","checkpoint":"分号上梁·二","scene":"夜里七郎跟你说：二公子私下找他喝了顿酒，说想参股分号的果子饮子生意。","options":[{"text":"让七郎自己拿主意","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「你信我？」他问。「不信你我信谁。」","source":"宋代商铺参股，伙友相商为定。"},{"text":"一口回绝","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"拒得急了，倒显得心里还有芥蒂。","source":"宋代商铺参股，伙友相商为定。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"果子饮子线，分号多一门生意"},{"id":"E-082-未","branch":"E","stage":4,"day":82,"shichen":"未时","checkpoint":"分号上梁·三","scene":"观礼人群里来了张员外家的二公子，贺仪是一架上好榉木的多宝格：「放碗碟正合适。」","options":[{"text":"大方收下回礼","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"体面人来往，讲的是有来有往，不欠不拒。","source":"宋代商铺间馈赠往来，礼尚往来。"},{"text":"坚辞不受","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他有些讪讪：「小娘子还记着我那点唐突？」","source":"宋代商铺间馈赠往来，礼尚往来。"}],"difficulty":2,"npc":["张府二公子"],"foreshadow":"二公子成体面朋友，对照组转正"},{"id":"E-083","branch":"E","stage":4,"day":83,"shichen":"辰时","checkpoint":"分号上梁·四","scene":"一早小豆子来请罪：昨夜偷偷在灯笼纸上写「贰号」二字练手，墨洇了，毁了一张好纸。","options":[{"text":"带他重写一张","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「悬腕，慢些。」你握着他的手写完，这张成了。","source":"宋代商铺灯笼书写，师徒相授。"},{"text":"说纸不要紧","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"纸是不紧，可孩子心里那股劲要紧。","source":"宋代商铺灯笼书写，师徒相授。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"小豆子的字终于挑上灯笼"},{"id":"E-083-戌","branch":"E","stage":4,"day":83,"shichen":"戌时","checkpoint":"分号上梁·五","scene":"夜里你问杏儿：「官媒说的那几家，你心里可有倾向？」丫头红着脸，半天挤出一个字：「豆。」","options":[{"text":"愣住，随即笑了","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"小豆子？你细想，竟觉得处处都对。","source":"宋代市井婚配，两小无猜成亲者常见。"},{"text":"说再帮你相看","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"丫头急得直摆手：「不是相看的事！」","source":"宋代市井婚配，两小无猜成亲者常见。"}],"flavor":true,"difficulty":1,"npc":["丫头杏儿"],"foreshadow":"杏儿中意小豆子，这对成了"},{"id":"E-083-未","branch":"E","stage":4,"day":83,"shichen":"未时","checkpoint":"分号上梁·六","scene":"午后杏儿的娘从乡下来看她，见女儿在柜上打算盘，惊得合不拢嘴：「我闺女会算账了？」","options":[{"text":"留她娘住几日","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人家看女儿样样都好，走时抹着泪谢你。","source":"宋代商铺伙计家眷探访，东主厚待。"},{"text":"招待顿饭就送回","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"饭是吃了，老人家夜里还是赶回了乡下。","source":"宋代商铺伙计家眷探访，东主厚待。"}],"difficulty":1,"npc":["丫头杏儿"],"foreshadow":"杏儿娘的认可，亲事伏笔加深"},{"id":"E-084","branch":"E","stage":4,"day":84,"shichen":"辰时","checkpoint":"杏儿心事","scene":"一早你把小豆子叫到柜上，旁敲侧击：「你今年也十四了，往后有什么打算？」","options":[{"text":"听他自己说","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「想跟七哥学厨，还想……」他耳朵红了，「再攒点钱。」","source":"宋代市井少年学徒立业，再议婚配。"},{"text":"直接问杏儿的事","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子吓得跑了，这事得他自己长明白。","source":"宋代市井少年学徒立业，再议婚配。"}],"difficulty":2,"npc":["小豆子"],"foreshadow":"小豆子也要立业，才配得上提亲"},{"id":"E-084-戌","branch":"E","stage":4,"day":84,"shichen":"戌时","checkpoint":"杏儿心事·二","scene":"夜里你有些害喜，想吃酸的。七郎翻遍厨房没找到话梅，披上衣服就出了门。","options":[{"text":"由他去，等他回来","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"半个时辰后他回来了，怀里揣着蜜煎梅子，跑热了。","source":"宋代夜市蜜煎果子，深夜亦有售。"},{"text":"拦他说不用","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「用的。」他人已在门外，「你等着。」","source":"宋代夜市蜜煎果子，深夜亦有售。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"夜寻梅子，他的疼法从不多说"},{"id":"E-084-未","branch":"E","stage":4,"day":84,"shichen":"未时","checkpoint":"杏儿心事·三","scene":"午后你跟七郎说杏儿和小豆子的事。七郎听完一拍大腿：「我说那小子最近怎么抢着洗碗！」","options":[{"text":"笑男人看事就是糙","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「糙是糙。」他挠头，「当年我不也抢着给你刷锅。」","source":"宋代市井男女，以帮工示好为常情。"},{"text":"商量怎么撮合","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"「别撮合。」七郎难得有主意，「让他们自己来。」","source":"宋代市井男女，以帮工示好为常情。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"当年刷锅的人，如今看穿了洗碗的人"},{"id":"E-085","branch":"E","stage":4,"day":85,"shichen":"辰时","checkpoint":"杏儿心事·四","scene":"一早小豆子正式来拜师：要拜七郎学厨。七郎看你，你点头。","options":[{"text":"行拜师礼，立帖","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"一盏拜师茶，孩子从此是有手艺前程的人了。","source":"宋代厨行拜师，立帖奉茶为礼。"},{"text":"说不用那么正式","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"小豆子认真得很：「拜师哪能不磕头。」","source":"宋代厨行拜师，立帖奉茶为礼。"}],"difficulty":1,"npc":["小豆子","陈七郎"],"foreshadow":"checkpoint 收官：小豆子出师有路"},{"id":"E-085-戌","branch":"E","stage":4,"day":85,"shichen":"戌时","checkpoint":"杏儿心事·五","scene":"夜里散了席，小豆子喝得脸通红（只许抿了一口），抱着拜师帖在门槛上睡着了。","options":[{"text":"给他盖上百家被角","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子梦里都在笑，帖抱得紧紧的。","source":"宋代民间小儿醉睡，长辈照拂之景。"},{"text":"让七郎抱他回屋","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"七郎抱起他，轻手轻脚像抱未来的孩子。","source":"宋代民间小儿醉睡，长辈照拂之景。"}],"flavor":true,"difficulty":1,"npc":["小豆子","陈七郎"],"foreshadow":"这一屋子的孩子，都是她的家人"},{"id":"E-085-未","branch":"E","stage":4,"day":85,"shichen":"未时","checkpoint":"杏儿心事·六","scene":"拜师酒上，大嫂多喝了两杯，拉着你说：「豆子这孩子，是从桥洞边捡回来的缘分。你成全他，比谁都值。」","options":[{"text":"说都是他自己争气","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「争气也要有处争。」大嫂抹眼睛，「你就是那处。」","source":"宋人笔记记市井相恤之义。"},{"text":"笑她喝多了","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"大嫂不依：「我没喝多，我说的是真的。」","source":"宋人笔记记市井相恤之义。"}],"difficulty":1,"npc":["邻摊大嫂"],"foreshadow":"善缘闭环：当年半块饼，如今一个徒弟"},{"id":"E-086","branch":"E","stage":4,"day":86,"shichen":"辰时","checkpoint":"分号试业","scene":"分号装修毕，试业三天。陈伯穿上新围裙站在「汤记贰号」门口，腰板挺得笔直。","options":[{"text":"头一锅汤你亲掌","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"头汤得正，往后一百锅都错不了。","source":"宋代食店开业，头汤定味以立本。"},{"text":"让陈伯自己来","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老人紧张得手抖，头锅汤咸了半分。","source":"宋代食店开业，头汤定味以立本。"}],"difficulty":2,"npc":["老仆陈伯"],"foreshadow":"头汤立本，分号味道要正"},{"id":"E-086-戌","branch":"E","stage":4,"day":86,"shichen":"戌时","checkpoint":"分号试业·二","scene":"晚上盘两边账：总店稳，分号试业三天净入八百文。七郎拨着算盘，手都在颤。","options":[{"text":"说：这才刚开始","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「嗯。」他深吸气，「往后会更忙，你顾好自己。」","source":"宋代商铺盈余核算，夫妇同计。"},{"text":"逗他：手别抖","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「是激动的。」他憨笑，「当年三贯钱你敢信今天吗？」","source":"宋代商铺盈余核算，夫妇同计。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"三贯钱到两间店，逆袭成章"},{"id":"E-086-未","branch":"E","stage":4,"day":86,"shichen":"未时","checkpoint":"分号试业·三","scene":"试业头天，相国寺的香客顺路进来尝，一碗汤下肚问：「州桥那家汤记，跟你们什么关系？」","options":[{"text":"说是一家，分号","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「难怪！」客人一传十，贰号的名头借势立起来了。","source":"宋代商铺分号，借总号声名而立。"},{"text":"只说新开的店","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"白放着现成的招牌不用，可惜了。","source":"宋代商铺分号，借总号声名而立。"}],"difficulty":2,"npc":[],"foreshadow":"「汤记」成了连锁的字号"},{"id":"E-087","branch":"E","stage":4,"day":87,"shichen":"辰时","checkpoint":"孕中岁月","scene":"你的肚子渐渐显了。柜上的活不累，可你闲不住，总想往灶间跑。","options":[{"text":"七郎设个「监工凳」","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"灶间门口一张矮凳，你坐着指点，他照做。","source":"宋代孕妇家中静养，家人照拂。"},{"text":"偷着上手被他抓","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他大惊小怪地叫，全店都来看你笑话。","source":"宋代孕妇家中静养，家人照拂。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"监工凳，掌柜娘子有了新岗位"},{"id":"E-087-戌","branch":"E","stage":4,"day":87,"shichen":"戌时","checkpoint":"孕中岁月·二","scene":"夜里你摸着肚子，跟七郎商量孩子的乳名。他想了一串：「饼儿、汤儿、豆儿……」","options":[{"text":"笑他全是灶上的","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「那叫'满儿'。」他说，「满仓满店，满门。」","source":"宋代民间乳名，多取吉意俗字。"},{"text":"说再想想","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「不急。」他替你掖被角，「慢慢想。」","source":"宋代民间乳名，多取吉意俗字。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"乳名「满儿」，待产线推进"},{"id":"E-087-未","branch":"E","stage":4,"day":87,"shichen":"未时","checkpoint":"孕中岁月·三","scene":"午后，表姐带着她夫婿来道喜——她成亲后气色极好，说话都有了底气。","options":[{"text":"留饭，两家叙亲","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"从前相看两厌的表姐妹，如今同坐一桌笑。","source":"宋代亲眷往来贺喜，常态。"},{"text":"乏了，改日再聚","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"表姐不恼，可眼里的热乎劲淡了些。","source":"宋代亲眷往来贺喜，常态。"}],"difficulty":1,"npc":["表姐"],"foreshadow":"表姐夫婿，后文或成生意臂助"},{"id":"E-088","branch":"E","stage":4,"day":88,"shichen":"辰时","checkpoint":"孕中岁月·四","scene":"一早店里来了位老客——当年第一个夸你饼香的轿夫，如今领了轿行的小管事，进门就要订百人喜宴。","options":[{"text":"接下，亲自拟单","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「当年俩饼的情分，我记到今天。」他说。","source":"宋代食店承办喜宴，老客引荐为常。"},{"text":"推荐给别家大店","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他急了：「我就要你家的，别家不去！」","source":"宋代食店承办喜宴，老客引荐为常。"}],"difficulty":1,"npc":["轿夫"],"foreshadow":"老客情分，生意的源头活水"},{"id":"E-088-戌","branch":"E","stage":4,"day":88,"shichen":"戌时","checkpoint":"孕中岁月·五","scene":"夜里你有些胎动，慌得喊七郎。他把手放上来，小家伙踢了一下，他吓得差点跳起来。","options":[{"text":"看他笑出眼泪","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"「他踢我。」他愣了半天，「他真的会踢。」","source":"宋代民间胎动之喜，夫妇同感。"},{"text":"说孩子在打招呼","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「那你告诉他，灶上的火，爹给他留着。」","source":"宋代民间胎动之喜，夫妇同感。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"胎动之夜，两口变三口的前奏"},{"id":"E-088-未","branch":"E","stage":4,"day":88,"shichen":"未时","checkpoint":"孕中岁月·六","scene":"喜宴单子大，要调动两家店的人手。你在柜上排班，陈伯管贰号，七郎管总店，杏儿管采买。","options":[{"text":"排得井井有条","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"大掌柜的派头出来了，众人领命而去。","source":"宋代商铺调派人手，东主统筹。"},{"text":"让七郎去排","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他排了半天，把自己排进了两班。","source":"宋代商铺调派人手，东主统筹。"}],"difficulty":2,"npc":["陈伯","丫头杏儿","陈七郎"],"foreshadow":"她已是运筹帷幄的大掌柜"},{"id":"E-089","branch":"E","stage":4,"day":89,"shichen":"辰时","checkpoint":"喜宴大单","scene":"喜宴前一日，备料堆满了后院。杏儿拿着单子一条条对，忽然发现少了一样：喜饼的红曲粉。","options":[{"text":"让小豆子快去买","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"孩子飞也似的去了，半个时辰就背回来了。","source":"宋代喜饼以红曲着色，应景之物。"},{"text":"说将就一下","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"喜饼不红，主家脸上不好看。","source":"宋代喜饼以红曲着色，应景之物。"}],"difficulty":1,"npc":["丫头杏儿","小豆子"],"foreshadow":"细节定成败，喜宴不能失手"},{"id":"E-089-戌","branch":"E","stage":4,"day":89,"shichen":"戌时","checkpoint":"喜宴大单·二","scene":"夜里你睡不着，起来再看一眼备料。七郎跟着起来，两人在院里对着单子又过了一遍。","options":[{"text":"说：像不像当年","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「像。」他笑，「当年咱俩对着一盘旋煎羊白肠。」","source":"宋人笔记记夫妇同心经营之景。"},{"text":"催他快睡","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「你也睡。」他替你披衣，「孩子困了。」","source":"宋人笔记记夫妇同心经营之景。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"大场面前夜，还是当年那两个人"},{"id":"E-089-未","branch":"E","stage":4,"day":89,"shichen":"未时","checkpoint":"喜宴大单·三","scene":"午后老虞候来巡视，看了一遍单子，点头：「稳。就是汤，老夫要盯着出。」","options":[{"text":"请他坐镇灶间","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"有老人压阵，灶上的人心都定了。","source":"宋代宴客以耆老监厨为荣。"},{"text":"说不敢劳烦他","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"老人吹胡子：「嫌我老了？」","source":"宋代宴客以耆老监厨为荣。"}],"difficulty":2,"npc":["老虞候"],"foreshadow":"老虞候监厨，喜宴的定心丸"},{"id":"E-090","branch":"E","stage":4,"day":90,"shichen":"辰时","checkpoint":"喜宴大单·四","scene":"喜宴日。天不亮两店齐动，蒸笼的雾气腾了半条街。你在柜上坐镇，七郎在灶间指挥。","options":[{"text":"井井有条，不出错","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"百人宴席，从开席到散场，一丝不乱。","source":"宋代食店承办宴席，调度为要。"},{"text":"亲自盯每道菜","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"盯得过来吗？你肚子一沉，被大嫂按回凳上。","source":"宋代食店承办宴席，调度为要。"}],"difficulty":3,"npc":["陈七郎","邻摊大嫂"],"foreshadow":"checkpoint 收官：喜宴大成功"},{"id":"E-090-戌","branch":"E","stage":4,"day":90,"shichen":"戌时","checkpoint":"喜宴大单·五","scene":"夜里清点进项，喜宴一单净入五贯。你把账合上，对七郎说：「孩子的摇车，有了。」","options":[{"text":"他说明日就去打","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「要榆木的，结实。」他已经开始比划尺寸了。","source":"宋代民间为新生儿制摇车，父职之始。"},{"text":"说先存着","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"「也行。」他挠头，「可我手痒，想先做点什么。」","source":"宋代民间为新生儿制摇车，父职之始。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"摇车未打，分号的钱又厚了"},{"id":"E-090-未","branch":"E","stage":4,"day":90,"shichen":"未时","checkpoint":"喜宴大单·六","scene":"宴席正酣，主家高声夸「汤记」手艺，满堂喝彩。二公子起身敬酒，敬的是你柜上这杯茶。","options":[{"text":"以茶代酒回敬","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「小娘子以茶代酒，我们心服口服。」","source":"宋代宴饮，妇人主家以茶代酒为礼。"},{"text":"让七郎代饮","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"七郎代了，可满堂要敬的是你。","source":"宋代宴饮，妇人主家以茶代酒为礼。"}],"difficulty":2,"npc":["张府二公子"],"foreshadow":"体面人做体面事，对照组彻底转正"},{"id":"E-091","branch":"E","stage":4,"day":91,"shichen":"辰时","checkpoint":"稳中有进","scene":"喜宴之后，「汤记」承办宴席的名声传开，订单排到了下个月。你坐在柜上，单子写满了一页。","options":[{"text":"按序接单，不滥接","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"宁可推掉几单，也不能砸了一单的口碑。","source":"宋代食店接单量力，信誉重于一时之利。"},{"text":"有多少接多少","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"接多了做不过来，坏的是招牌。","source":"宋代食店接单量力，信誉重于一时之利。"}],"difficulty":2,"npc":[],"foreshadow":"口碑是护城河，宁缺毋滥"},{"id":"E-091-戌","branch":"E","stage":4,"day":91,"shichen":"戌时","checkpoint":"稳中有进·二","scene":"夜里你把官媒的事学给七郎听，他挠头：「那小子……我得找他谈谈。」","options":[{"text":"让他别吓着孩子","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「我跟他学厨是师徒，谈心是男人对男人。」他挺认真。","source":"宋代市井师徒如父子，兼为媒保。"},{"text":"说让他俩自己来","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「也行。」他退一步，「我就看着。」","source":"宋代市井师徒如父子，兼为媒保。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"七郎要找小豆子'男人对男人'"},{"id":"E-091-未","branch":"E","stage":4,"day":91,"shichen":"未时","checkpoint":"稳中有进·三","scene":"午后官媒又来，这回正色说：是给杏儿提亲的——城南杂货铺的少东家，人她见过，不错。","options":[{"text":"先探杏儿的口风","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「姐，我心里有人了。」丫头这回说得斩钉截铁。","source":"宋代市井女子议亲，本人意愿渐重。"},{"text":"直接替杏儿回绝","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"回是回了，可官媒的话越传越离谱。","source":"宋代市井女子议亲，本人意愿渐重。"}],"difficulty":2,"npc":["官媒","丫头杏儿"],"foreshadow":"杏儿心有所属，官媒碰壁"},{"id":"E-092","branch":"E","stage":4,"day":92,"shichen":"辰时","checkpoint":"稳中有进·四","scene":"一早，小豆子红着脸来找你，手里攥着一张纸——他写的：「姐，我想……娶杏儿。」字歪歪扭扭，但每个都认真。","options":[{"text":"问他拿什么娶","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「我有手艺，有师傅，往后能养她。」孩子挺直了。","source":"宋代市井少年议婚，以立业为先。"},{"text":"直接应下","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"应得太快，孩子反而慌了：「我……我还没攒够。」","source":"宋代市井少年议婚，以立业为先。"}],"difficulty":2,"npc":["小豆子"],"foreshadow":"小豆子的婚书草稿，自己写的"},{"id":"E-092-戌","branch":"E","stage":4,"day":92,"shichen":"戌时","checkpoint":"稳中有进·五","scene":"夜里七郎对你说：「豆子那孩子像我，实诚。」你笑：「像你有什么好？」","options":[{"text":"说像你好","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「像我嘴笨。」他憨笑，「可心里热。」","source":"宋人笔记记市井师徒情谊之厚。"},{"text":"说比你会说话","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「那是。」他认真点头，「随他姐。」","source":"宋人笔记记市井师徒情谊之厚。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"两代人的婚事，一脉的实诚"},{"id":"E-092-未","branch":"E","stage":4,"day":92,"shichen":"未时","checkpoint":"稳中有进·六","scene":"午后你把两个孩子叫到一处，杏儿红脸，小豆子搓手。你说：「亲事我应，但先立业后成家，你俩自己挣。」","options":[{"text":"定下一年之约","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一年为期，两人眼睛都亮了：「姐你放心！」","source":"宋代民间婚约，以立业期为约者渐多。"},{"text":"说再考验考验","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"考验是好事，可别把两个孩子的热情磨凉了。","source":"宋代民间婚约，以立业期为约者渐多。"}],"difficulty":2,"npc":["小豆子","丫头杏儿"],"foreshadow":"一年之约，下一代的婚事定了调"},{"id":"E-093","branch":"E","stage":4,"day":93,"shichen":"辰时","checkpoint":"临盆将近","scene":"你身子渐重，柜上的事也渐渐交给了杏儿。这丫头如今独当一面，算盘打得比你还快。","options":[{"text":"放心让她管","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「姐你安心，柜上有我。」丫头眼里有光。","source":"宋代商铺以得力伙计掌柜台，常态。"},{"text":"每日还要过目","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"过目是仔细，可杏儿眼里的光暗了一分。","source":"宋代商铺以得力伙计掌柜台，常态。"}],"difficulty":1,"npc":["丫头杏儿"],"foreshadow":"杏儿独当一面，薪火相传"},{"id":"E-093-戌","branch":"E","stage":4,"day":93,"shichen":"戌时","checkpoint":"临盆将近·二","scene":"夜里你把两辆摇车并排摆在屋里，一辆七郎要亲手打（还没打完），一辆舅父送的。","options":[{"text":"说两辆都留着","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「一辆家里用，一辆店里用。」他点头，「都是心意。」","source":"宋代民间小儿摇车，实用之物。"},{"text":"笑这下不打架了","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「孩子睡哪辆？」你问。他愣住：「……轮着睡。」","source":"宋代民间小儿摇车，实用之物。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"摇车就位，只等孩子落地"},{"id":"E-093-未","branch":"E","stage":4,"day":93,"shichen":"未时","checkpoint":"临盆将近·三","scene":"午后舅父亲自送来一辆小儿摇车——榆木的，打磨得溜光，说是府上木匠做的。","options":[{"text":"收下，请他吃茶","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"舅父摸着摇车说：「比我们小时候用的好。」","source":"宋代亲族馈赠新生儿用具，常情。"},{"text":"说已经备了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"舅父的手停在半空：「多一辆不碍事。」","source":"宋代亲族馈赠新生儿用具，常情。"}],"difficulty":1,"npc":["舅父"],"foreshadow":"摇车两辆，人情两份"},{"id":"E-094","branch":"E","stage":4,"day":94,"shichen":"辰时","checkpoint":"临盆将近·四","scene":"一早羊水破了，比预计早了几天。大嫂飞奔去请稳婆，七郎在门外转得像热锅上的蚂蚁。","options":[{"text":"稳住自己深呼吸","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「别怕。」你对自己说，「娘当年也这么过来的。」","source":"宋代妇人生产，家人环伺为常。"},{"text":"喊着要七郎进来","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"稳婆拦住：「男人进产房，不吉利。」","source":"宋代妇人生产，家人环伺为常。"}],"difficulty":2,"npc":["邻摊大嫂","陈七郎"],"foreshadow":"生产这一关，是最硬的一仗"},{"id":"E-094-戌","branch":"E","stage":4,"day":94,"shichen":"戌时","checkpoint":"临盆将近·五","scene":"夜里七郎被放进屋，轻手轻脚凑到摇篮边。孩子的小手忽然抓住他的手指，他不敢动了。","options":[{"text":"看他僵在那笑","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"「她抓我。」他压低声音，「她是不是认识我？」","source":"宋代民间父子初见，舐犊之情。"},{"text":"说：叫爹","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「她才一天……」他喉头滚动，「……爹在。」","source":"宋代民间父子初见，舐犊之情。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"爹在——两个字说了一生"},{"id":"E-094-未","branch":"E","stage":4,"day":94,"shichen":"未时","checkpoint":"临盆将近·六","scene":"午后，一声啼哭划破院子。稳婆出来报喜：「母女平安，是个千金。」","options":[{"text":"泪一下子涌出来","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"你听见门外七郎的哭声，比孩子还响。","source":"宋代民间生子报喜，父母同庆。"},{"text":"问孩子像谁","correct":false,"tags":["感情"],"dims":{"情缘":2},"feedback":"稳婆笑：「眉眼像爹，哭声像娘，亮堂。」","source":"宋代民间生子报喜，父母同庆。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"母女平安，「满儿」落地"},{"id":"E-095","branch":"E","stage":4,"day":95,"shichen":"辰时","checkpoint":"喜添千金","scene":"洗三这日，亲眷都来了。舅母抱着孩子不撒手：「这眉眼，随她娘，将来是个美人胚子。」","options":[{"text":"笑着说随谁都好","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"满屋笑声，孩子的啼哭都显得喜庆。","source":"宋代洗三之礼，亲眷齐聚贺新生。"},{"text":"讨几句吉利话","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"吉利话听了满耳，可你心里最亮的是孩子。","source":"宋代洗三之礼，亲眷齐聚贺新生。"}],"difficulty":1,"npc":["舅母"],"foreshadow":"checkpoint 收官：洗三之喜"},{"id":"E-095-戌","branch":"E","stage":4,"day":95,"shichen":"戌时","checkpoint":"喜添千金·二","scene":"夜里孩子睡了，你和七郎并排看着摇篮。他忽然说：「得给闺女挣个大名。」","options":[{"text":"说叫「念慈」","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「念慈。」他念了两遍，「念着她娘，也念着这一街的人。」","source":"宋代民间取名，多取恩义吉意。"},{"text":"说请他娘来定","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"「也行。」他点头，「可我心里……就想叫念慈。」","source":"宋代民间取名，多取恩义吉意。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"女儿「念慈」，名字里全是这一路的人"},{"id":"E-095-未","branch":"E","stage":4,"day":95,"shichen":"未时","checkpoint":"喜添千金·三","scene":"午后老虞候拄杖来贺，看了孩子半天，从怀里摸出一枚旧银锁：「我孙女当年的，给你家丫头。」","options":[{"text":"郑重接过戴上","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"「戴了我的锁，就是我半个孙女。」老人笑了。","source":"宋代民间赠银锁于新生儿，祈福之俗。"},{"text":"说太贵重不敢收","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老人吹胡子：「再不收我生气了。」","source":"宋代民间赠银锁于新生儿，祈福之俗。"}],"difficulty":1,"npc":["老虞候"],"foreshadow":"银锁上身，孩子多了个'祖父'"},{"id":"E-096","branch":"E","stage":4,"day":96,"shichen":"辰时","checkpoint":"月子时光","scene":"月子里你闭门养身子，店里的事全靠七郎和大嫂。头一日七郎来报账，紧张得像交功课。","options":[{"text":"听他报，不插嘴","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"报完他松了口气：「你在听，我就有底。」","source":"宋代妇人月子中静养，家事暂托夫婿。"},{"text":"忍不住问东问西","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"问得他越报越乱，大嫂进来把他撵走了。","source":"宋代妇人月子中静养，家事暂托夫婿。"}],"difficulty":1,"npc":["陈七郎","邻摊大嫂"],"foreshadow":"月子是假，放权是真"},{"id":"E-096-戌","branch":"E","stage":4,"day":96,"shichen":"戌时","checkpoint":"月子时光·二","scene":"夜里孩子哭，七郎笨手笨脚地抱，抱得孩子哭得更凶。你接过来，小家伙立刻安静了。","options":[{"text":"教他怎么抱","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「手托住后颈……对，就这样。」他大气不敢出。","source":"宋代民间育婴，父母相授之法。"},{"text":"说让他歇着","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"他不肯走：「我再学学，往后夜里我抱。」","source":"宋代民间育婴，父母相授之法。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"抱孩子的手艺，他也在学"},{"id":"E-096-未","branch":"E","stage":4,"day":96,"shichen":"未时","checkpoint":"月子时光·三","scene":"午后小豆子偷偷溜进来，从怀里掏出个布包——他攒了三个月的工钱，全换成了红糖。","options":[{"text":"收下，给他留着娶亲","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「红糖我收了，钱你拿回去。」孩子急得直摆手。","source":"宋代民间以红糖赠产妇，贴心之礼。"},{"text":"板脸让他拿走","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孩子眼圈红了：「姐，你是不是嫌少……」","source":"宋代民间以红糖赠产妇，贴心之礼。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"小豆子的红糖，比金子还沉"},{"id":"E-097","branch":"E","stage":4,"day":97,"shichen":"辰时","checkpoint":"月子时光·四","scene":"一早大嫂来换班，带来个消息：贰号的陈伯昨夜咳得厉害，今早还硬撑着开了门。","options":[{"text":"让七郎去替班","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「老人的身子，比生意要紧。」七郎立刻去了。","source":"宋代商铺东主体恤老伙计，情义为先。"},{"text":"说请大夫看看","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"大夫是请了，可灶上没人，贰号乱了一上午。","source":"宋代商铺东主体恤老伙计，情义为先。"}],"difficulty":2,"npc":["邻摊大嫂","老仆陈伯"],"foreshadow":"陈伯身子骨，让人揪心"},{"id":"E-097-戌","branch":"E","stage":4,"day":97,"shichen":"戌时","checkpoint":"月子时光·五","scene":"夜里陈伯被接来，躺在收拾好的暖阁里，拉着你的手老泪纵横：「老奴这辈子，值了。」","options":[{"text":"说：您是我长辈","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「从脚店洗碗那天起，您就是我的贵人。」","source":"宋代市井养老，情义重于名分。"},{"text":"让他安心养着","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"「养好了还得给我看店。」你故意说，他笑了。","source":"宋代市井养老，情义重于名分。"}],"flavor":true,"difficulty":1,"npc":["老仆陈伯"],"foreshadow":"陈伯安度晚年，善有善报"},{"id":"E-097-未","branch":"E","stage":4,"day":97,"shichen":"未时","checkpoint":"月子时光·六","scene":"午后七郎回来，脸色不好：陈伯的老毛病犯了，大夫说不能再操劳，得静养。","options":[{"text":"接陈伯回家养","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"「贰号让豆子顶，您来我家，我给您养老。」","source":"宋代商铺东主奉养老伙计，义举也。"},{"text":"送回乡下调养","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老人无乡可回，这句话比病还伤人。","source":"宋代商铺东主奉养老伙计，义举也。"}],"difficulty":3,"npc":["陈七郎","老仆陈伯"],"foreshadow":"陈伯入家养老，情义最重的一笔"},{"id":"E-098","branch":"E","stage":4,"day":98,"shichen":"辰时","checkpoint":"出月复工","scene":"满月这日，你出了房门，日头正好。店里的人齐刷刷站在院里：「东家娘，满月大吉！」","options":[{"text":"给众人发红封","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"人人都有份，连烧火的老妈子都没落下。","source":"宋代商铺东主满月酬众，惯例。"},{"text":"说几句谢辞就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"谢辞是暖的，可封里的钱更实在。","source":"宋代商铺东主满月酬众，惯例。"}],"difficulty":1,"npc":[],"foreshadow":"满月出关，她重新掌局"},{"id":"E-098-戌","branch":"E","stage":4,"day":98,"shichen":"戌时","checkpoint":"出月复工·二","scene":"夜里你抱着孩子在院里走，七郎跟在后面，忽然说：「满月了，孩子的大名……」","options":[{"text":"说就叫念慈","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「陈念慈。」他念了一遍，眼圈红了，「好名字。」","source":"宋代民间满月命名，以恩义为字。"},{"text":"让他再想想","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「不用想了。」他说，「就叫这个，我求你了。」","source":"宋代民间满月命名，以恩义为字。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"「陈念慈」，名字落定"},{"id":"E-098-未","branch":"E","stage":4,"day":98,"shichen":"未时","checkpoint":"出月复工·三","scene":"午后查账，月子这一个月，两店进项竟比从前还涨——杏儿管柜管得滴水不漏。","options":[{"text":"给杏儿涨月钱","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「姐……」丫头攥着钱，「我没给你丢人。」","source":"宋代商铺酬劳得力伙计，按功加薪。"},{"text":"夸她两句就够","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"夸是夸了，可钱没涨，总觉得差点意思。","source":"宋代商铺酬劳得力伙计，按功加薪。"}],"difficulty":2,"npc":["丫头杏儿"],"foreshadow":"杏儿立起来了，分号后继有人"},{"id":"E-099","branch":"E","stage":4,"day":99,"shichen":"辰时","checkpoint":"复工理事","scene":"一早你抱着孩子去店里转了一圈，柜上的、灶上的都来逗孩子。小豆子挤在最前头：「让我抱抱！」","options":[{"text":"教他怎么抱","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"孩子在他怀里打了个哈欠，全店都笑了。","source":"宋代商铺东主携子视店，人情之常。"},{"text":"说怕摔了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"小豆子讪讪缩手，你后悔了——孩子总要被这些人抱着长大的。","source":"宋代商铺东主携子视店，人情之常。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"孩子在店里长大，众人的孩子"},{"id":"E-099-戌","branch":"E","stage":4,"day":99,"shichen":"戌时","checkpoint":"复工理事·二","scene":"夜里你奶完孩子，跟七郎核粥棚的账。他忽然说：「你如今是东家了，我还是个厨子。」","options":[{"text":"说：你是我的东家","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「店里你是二东家，家里你是大东家。」他笑了。","source":"宋代市井夫妇，相谑以取乐。"},{"text":"说别妄自菲薄","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"他点头，可眼底那点不自信，没全散。","source":"宋代市井夫妇，相谑以取乐。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"他的心结还在，需一个契机"},{"id":"E-099-未","branch":"E","stage":4,"day":99,"shichen":"未时","checkpoint":"复工理事·三","scene":"午后张府二公子来谈事：他家在南郊有处园子，想请「汤记」去设个粥棚，供游春的香客。","options":[{"text":"应下，算笔细账","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"游春季三个月，粥棚是细水长流的进项。","source":"宋代园林游春设粥棚，商铺承办。"},{"text":"说人手不够","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他有些失望：「那我只好找别家了。」","source":"宋代园林游春设粥棚，商铺承办。"}],"difficulty":2,"npc":["张府二公子"],"foreshadow":"南郊粥棚，生意版图再扩"},{"id":"E-100","branch":"E","stage":4,"day":100,"shichen":"辰时","checkpoint":"百日之庆","scene":"念慈百日，按规矩要办百日宴。你本想简单，可亲眷朋友太多，两店都坐不下。","options":[{"text":"在院里摆流水席","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"州桥半条街都来了，比过年还热闹。","source":"宋代百日之庆，亲眷邻里同贺。"},{"text":"只请至亲近友","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"清净是清净，可那份人情味淡了。","source":"宋代百日之庆，亲眷邻里同贺。"}],"difficulty":2,"npc":[],"foreshadow":"checkpoint 收官：百日之庆"},{"id":"E-100-戌","branch":"E","stage":4,"day":100,"shichen":"戌时","checkpoint":"百日之庆·二","scene":"夜里散了席，你抱着念慈站在门口，看灯笼上的「汤记」二字。百日前你还在月子里，百日后你已是两店之主。","options":[{"text":"对孩子说：这是家","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"她听不懂，可你说了，就作数。","source":"《东京梦华录》记汴京夜市灯火之盛。"},{"text":"对灯笼说声谢","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"灯笼无言，可它照亮了你的来路。","source":"《东京梦华录》记汴京夜市灯火之盛。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"「这是家」——一百天的答案"},{"id":"E-100-未","branch":"E","stage":4,"day":100,"shichen":"未时","checkpoint":"百日之庆·三","scene":"宴席上，老虞候把念慈抱过去，用胡子扎她的小脸。孩子咯咯笑，满堂都笑了。","options":[{"text":"敬老人一杯茶","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「这杯我替念慈敬您，往后她得叫您一声'公'。」","source":"宋代民间以长者抚儿为福，敬茶为礼。"},{"text":"说孩子怕生","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孩子笑得正欢，哪里怕生——你多虑了。","source":"宋代民间以长者抚儿为福，敬茶为礼。"}],"difficulty":1,"npc":["老虞候"],"foreshadow":"念慈认了'公'，州桥有了根"},{"id":"E-101","branch":"E","stage":4,"day":101,"shichen":"辰时","checkpoint":"稳中有忧","scene":"一早，南郊粥棚开工。你带念慈去巡视，孩子睁着眼看热闹，你看着工地，各看各的。","options":[{"text":"定下每日巡查章程","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"粥棚虽小，规矩不能少，你定了三条铁律。","source":"宋代商铺设分点，巡查定规为要。"},{"text":"交给伙计看着办","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"伙计是好伙计，可没章程，三天就走了样。","source":"宋代商铺设分点，巡查定规为要。"}],"difficulty":2,"npc":[],"foreshadow":"粥棚虽小，是检验班底的试金石"},{"id":"E-101-戌","branch":"E","stage":4,"day":101,"shichen":"戌时","checkpoint":"稳中有忧·二","scene":"夜里你跟七郎说：「娘想来就来，咱家院子大，热闹。」他松了口气，又有些犹豫：「可你……」","options":[{"text":"说我早当她是娘","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「真的？」「真的。」他眼眶一热，「我明日就去接。」","source":"宋代民间接婆母同住，孝养之常。"},{"text":"说先问问大嫂意见","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"大嫂能说什么？这是你们家的事。","source":"宋代民间接婆母同住，孝养之常。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"陈母进城，三代同堂将启"},{"id":"E-101-未","branch":"E","stage":4,"day":101,"shichen":"未时","checkpoint":"稳中有忧·三","scene":"午后回店，发现七郎一个人坐在空店堂里发呆。问你来了也不抬头。","options":[{"text":"坐他旁边等他说","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"半晌他开口：「我娘说，想来城里住，又怕添乱。」","source":"宋代民间婆媳相处，远近之度。"},{"text":"直接问怎么了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"「没事。」他站起来走了，可你知道有事。","source":"宋代民间婆媳相处，远近之度。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"陈母要来城，家事新课题"},{"id":"E-102","branch":"E","stage":4,"day":102,"shichen":"辰时","checkpoint":"婆母进城","scene":"七郎一早回乡接陈母。你在院里收拾出最亮的厢房，又把百家被晒了晒。","options":[{"text":"亲自下厨备接风","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人进门看见热汤热饭，眼泪差点下来。","source":"宋代民间接亲，备接风宴为礼。"},{"text":"让大嫂张罗就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大嫂张罗得再好，不是你做的，差一层。","source":"宋代民间接亲，备接风宴为礼。"}],"difficulty":1,"npc":["陈母"],"foreshadow":"婆母进城，家是越住越大了"},{"id":"E-102-戌","branch":"E","stage":4,"day":102,"shichen":"戌时","checkpoint":"婆母进城·二","scene":"夜里陈母抱着念慈哄睡，哼着乡下的摇篮曲。你和七郎在门外听，谁也没进去。","options":[{"text":"说：往后不用愁了","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「嗯。」他低声说，「娘在，孩子有人疼。」","source":"宋代民间三代同堂，含饴弄孙之乐。"},{"text":"悄悄退开","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"月光下你俩牵手回房，像新婚那夜。","source":"宋代民间三代同堂，含饴弄孙之乐。"}],"flavor":true,"difficulty":1,"npc":["陈母","陈七郎"],"foreshadow":"摇篮曲响起，家宅安宁"},{"id":"E-102-未","branch":"E","stage":4,"day":102,"shichen":"未时","checkpoint":"婆母进城·三","scene":"午后陈母到了，抱着念慈不撒手，忽然从怀里掏出个小银镯：「给孙女打的，攒了半年。」","options":[{"text":"替念慈戴上谢她","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「奶奶给的，戴着。」你替孩子收下，老人笑了。","source":"宋代民间祖母赠孙银饰，隔辈亲。"},{"text":"说太破费了","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"「破费什么。」老人摆手，「我孙女值得。」","source":"宋代民间祖母赠孙银饰，隔辈亲。"}],"difficulty":1,"npc":["陈母"],"foreshadow":"银镯一对，祖孙的情分"},{"id":"E-103","branch":"E","stage":4,"day":103,"shichen":"辰时","checkpoint":"风波暗起","scene":"一早州桥上传来消息：有外地客商看中了「汤记」的字号，想出钱买断，让你俩只管供货。","options":[{"text":"一口回绝","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「字号是命，卖了我俩还剩什么？」","source":"宋代商铺字号，东主性命所系。"},{"text":"听听价钱再说","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"价钱是诱人，可七郎的脸沉下来了。","source":"宋代商铺字号，东主性命所系。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"字号买断的诱惑，是场考验"},{"id":"E-103-戌","branch":"E","stage":4,"day":103,"shichen":"戌时","checkpoint":"风波暗起·二","scene":"夜里你跟七郎复盘，他说：「五十贯……说实话，我心动了一下。」","options":[{"text":"说：我也心动了","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「可心动完呢？」你问。「……还是咱俩的店好。」","source":"宋人笔记记市井夫妇同心守业。"},{"text":"说以后再议","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「再议什么？」他急了，「我就说说，你别当真。」","source":"宋人笔记记市井夫妇同心守业。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"心动过，但守住了——这才真实"},{"id":"E-103-未","branch":"E","stage":4,"day":103,"shichen":"未时","checkpoint":"风波暗起·三","scene":"午后那客商亲自上门，出价五十贯——够你们歇十年。他笑着说：「小娘子，识时务者为俊杰。」","options":[{"text":"请他喝茶，婉拒","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「茶是好茶，字号不卖。」他悻悻而去。","source":"宋代商贾议价，以茶会客后婉拒。"},{"text":"让七郎去应付","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"七郎嘴笨，差点被绕进去，多亏你及时出来。","source":"宋代商贾议价，以茶会客后婉拒。"}],"difficulty":2,"npc":["外地客商"],"foreshadow":"五十贯没打动，字号立得更稳"},{"id":"E-104","branch":"E","stage":4,"day":104,"shichen":"辰时","checkpoint":"风波暗起·四","scene":"一早发现粥棚那边出了岔子：有伙计偷工减料，香客投诉到二公子那里。","options":[{"text":"亲自去查，换人","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"换掉伙计，赔礼道歉，粥棚的名声保住了。","source":"宋代商铺分店管理，东主亲为查察。"},{"text":"让二公子看着办","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"二公子能怎么办？砸的是「汤记」的招牌。","source":"宋代商铺分店管理，东主亲为查察。"}],"difficulty":3,"npc":["张府二公子"],"foreshadow":"扩张的代价：管理跟不上的隐忧"},{"id":"E-104-戌","branch":"E","stage":4,"day":104,"shichen":"戌时","checkpoint":"风波暗起·五","scene":"夜里你有些累，靠在七郎肩上。他说：「要不……分号的事缓一缓，你太辛苦了。」","options":[{"text":"说：我能扛","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「我知道你能。」他搂紧你，「可我不想你扛。」","source":"宋人笔记记市井夫妇相恤之情。"},{"text":"说那就缓一缓","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"缓是缓了，可你俩都知道，心里那口气松不得。","source":"宋人笔记记市井夫妇相恤之情。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"扛还是缓，是个真问题"},{"id":"E-104-未","branch":"E","stage":4,"day":104,"shichen":"未时","checkpoint":"风波暗起·六","scene":"午后你召集两店一棚的人手训话，说到动情处，念慈在里屋哭了，你不得不停下来。","options":[{"text":"让杏儿接着训","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"丫头站出来，一板一眼，竟有你的风范。","source":"宋代商铺东主训众，得传人可代。"},{"text":"草草收场去哄孩子","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孩子要紧，可话说到一半，效果打了折扣。","source":"宋代商铺东主训众，得传人可代。"}],"difficulty":2,"npc":["丫头杏儿"],"foreshadow":"杏儿能独当一面训话，真立起来了"},{"id":"E-105","branch":"E","stage":4,"day":105,"shichen":"辰时","checkpoint":"阶段四收官","scene":"一早你想通了：生意要做，人也要顾。你定了新章程——每日只做半天柜，下午陪念慈。","options":[{"text":"跟众人说明白","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「店是我的，孩子也是我的，我都要。」","source":"宋代妇人经商持家，两顾为能。"},{"text":"先跟七郎商量","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"他当然说好，可你心里知道，这是你自己的决定。","source":"宋代妇人经商持家，两顾为能。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"半天柜半天娃，新的平衡"},{"id":"E-105-戌","branch":"E","stage":4,"day":105,"shichen":"戌时","checkpoint":"阶段四收官·二","scene":"夜里你站在院里，看三处灯火：总店的、贰号的、粥棚的。怀里念慈睡着了，手里攥着你的一缕头发。","options":[{"text":"轻声说：娘做到了","correct":true,"tags":["感情"],"dims":{"情缘":2,"自主":1},"feedback":"从桥洞到三处灯火，从孤女到一家之主，做到了。","source":"《东京梦华录》记汴京百业俱兴之盛。"},{"text":"对灯火许个愿","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"愿往后年年，灯火都亮，人都在。","source":"《东京梦华录》记汴京百业俱兴之盛。"}],"flavor":true,"difficulty":1,"npc":[],"foreshadow":"终章将启：更大的汴京，更多的灯火"},{"id":"E-105-未","branch":"E","stage":4,"day":105,"shichen":"未时","checkpoint":"阶段四收官·三","scene":"午后你抱着念慈在院里晒太阳，小豆子凑过来，神秘兮兮地说：「姐，我攒够钱了，想……提亲。」","options":[{"text":"问他跟谁提","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「杏儿。」他梗着脖子，「我明媒正娶，风风光光。」","source":"宋代市井少年攒资议亲，立业成家。"},{"text":"笑他终于开窍","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"「早开了！」他急了，「我这是攒聘礼呢！」","source":"宋代市井少年攒资议亲，立业成家。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"小豆子的提亲，下一代的喜事"},{"id":"E-106","branch":"E","stage":5,"day":106,"shichen":"辰时","checkpoint":"贰号开张大典","scene":"「汤记贰号」正式开张日。相国寺东街，老虞候题的匾挂上门头，小豆子写的灯笼挑在檐下。","options":[{"text":"让小豆子挂灯笼","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"孩子踮着脚挂上去，那盏灯比谁的都亮。","source":"《东京梦华录》记相国寺东街商铺之盛。"},{"text":"请七郎代挂","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"七郎抱起小豆子：「来，你挂，我托着你。」","source":"《东京梦华录》记相国寺东街商铺之盛。"}],"difficulty":1,"npc":["小豆子","陈七郎"],"foreshadow":"贰号开张，终章第一声锣"},{"id":"E-106-戌","branch":"E","stage":5,"day":106,"shichen":"戌时","checkpoint":"贰号开张大典·二","scene":"夜里两店同收市，你抱着念慈站在街口，看两盏「汤记」灯笼在两条街上同时亮着。","options":[{"text":"对念慈说：看灯","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"孩子咿咿呀呀伸手去抓光，你抱紧了些。","source":"《东京梦华录》记汴京夜市灯火如昼。"},{"text":"对七郎说：成了","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「成了。」他搂住你娘俩，「往后更成。」","source":"《东京梦华录》记汴京夜市灯火如昼。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"两盏灯，照亮终章"},{"id":"E-106-未","branch":"E","stage":5,"day":106,"shichen":"未时","checkpoint":"贰号开张大典·三","scene":"晌午香客如潮，贰号头一锅汤见底。陈伯坐镇柜台，腰板挺得笔直，拨算盘的手一点都不抖了。","options":[{"text":"给陈伯敬杯茶","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人接过茶，手一颤：「老奴……也有今天。」","source":"宋代商铺开业，东主敬掌柜为礼。"},{"text":"让他接着忙","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"忙是忙得好，可这杯茶，老人等了一辈子。","source":"宋代商铺开业，东主敬掌柜为礼。"}],"difficulty":1,"npc":["老仆陈伯"],"foreshadow":"陈伯坐镇贰号，老有所依"},{"id":"E-107","branch":"E","stage":5,"day":107,"shichen":"辰时","checkpoint":"贰号开张大典·四","scene":"开张次日，外地客商又来了——这次不是买字号，是带了一车果子，说要谈「合作」。","options":[{"text":"听听他的章程","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"他出了个点子：南货北运，借「汤记」的摊卖果子。","source":"宋代南北商贾合作，互通有无为常。"},{"text":"一口回绝","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"回得干脆，可他那车果子，确实是好货。","source":"宋代南北商贾合作，互通有无为常。"}],"difficulty":2,"npc":["外地客商"],"foreshadow":"资本觊觎转成合作契机"},{"id":"E-107-戌","branch":"E","stage":5,"day":107,"shichen":"戌时","checkpoint":"贰号开张大典·五","scene":"夜里客商走后，七郎挠头：「这人上次想买断，这次又来合作，靠谱吗？」","options":[{"text":"说：防人之心要有","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"「契书写死，款到发货。」他点头记下。","source":"宋代商贾合作，防人之心不可无。"},{"text":"说疑人不用","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"「先小批量试试。」你俩相视一笑，想到一块了。","source":"宋代商贾合作，防人之心不可无。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"合作试水，留了一手"},{"id":"E-107-未","branch":"E","stage":5,"day":107,"shichen":"未时","checkpoint":"贰号开张大典·六","scene":"午后你跟七郎商议：果子生意可以做，但招牌不能沾别人的手。","options":[{"text":"定规矩：货进我出","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"他供货，我卖货，字号不沾手——立契为凭。","source":"宋代商铺与客商立契，权责分明。"},{"text":"让他入股算了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"入股容易，退股难——招牌的事，不能含糊。","source":"宋代商铺与客商立契，权责分明。"}],"difficulty":2,"npc":["陈七郎","外地客商"],"foreshadow":"规矩立住，合作不丢主动权"},{"id":"E-108","branch":"E","stage":5,"day":108,"shichen":"辰时","checkpoint":"喜事将近","scene":"一早，小豆子换上新衣裳，在你面前转了三圈：「姐，今日……我去提亲。」","options":[{"text":"让七郎陪他去","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"师徒如父子，七郎去，比他一个人硬气。","source":"宋代提亲有媒保相伴，以壮声势。"},{"text":"让他自己去","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孩子走到门口又回来了：「姐，我腿软。」","source":"宋代提亲有媒保相伴，以壮声势。"}],"difficulty":1,"npc":["小豆子","陈七郎"],"foreshadow":"提亲这日，下一代的大日子"},{"id":"E-108-戌","branch":"E","stage":5,"day":108,"shichen":"戌时","checkpoint":"喜事将近·二","scene":"夜里杏儿来谢你，扭扭捏捏半天，忽然跪下磕了个头：「姐，没有你，就没有我。」","options":[{"text":"拉起她：叫姐就行","correct":true,"tags":["感情"],"dims":{"情缘":1,"名声":1},"feedback":"「往后你是他的人了。」你顿了顿，「也是我妹子。」","source":"宋代市井师徒如亲人，名分自在。"},{"text":"说快起来","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"拉是拉起来了，可这个头，该她磕。","source":"宋代市井师徒如亲人，名分自在。"}],"flavor":true,"difficulty":1,"npc":["丫头杏儿"],"foreshadow":"一声姐，师徒变亲缘"},{"id":"E-108-未","branch":"E","stage":5,"day":108,"shichen":"未时","checkpoint":"喜事将近·三","scene":"午后小豆子回来了，脸通红：杏儿爹娘应了，但要按规矩——三书六礼，一样不能少。","options":[{"text":"替他操办起来","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「你的婚事，就是我的事。」孩子眼泪下来了。","source":"宋代婚俗三书六礼，庶人亦从简备之。"},{"text":"说从简就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"「不能从简。」小豆子梗着脖子，「杏儿值当的。」","source":"宋代婚俗三书六礼，庶人亦从简备之。"}],"difficulty":2,"npc":["小豆子"],"foreshadow":"小豆子的婚事，要办得风风光光"},{"id":"E-109","branch":"E","stage":5,"day":109,"shichen":"辰时","checkpoint":"操办喜事","scene":"一早你开始给小豆子张罗纳采的礼。官媒进门就夸：「这孩子的聘礼单子，是我见过最实诚的。」","options":[{"text":"再加一对大雁","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"雁是忠贞，穷人家也要有这个讲究。","source":"宋代纳采以雁为礼，庶人以雉代。"},{"text":"按单子办就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"单子是实诚，可差了大雁，总觉得短了口气。","source":"宋代纳采以雁为礼，庶人以雉代。"}],"difficulty":1,"npc":["官媒"],"foreshadow":"小豆子的聘礼，她贴了一半"},{"id":"E-109-戌","branch":"E","stage":5,"day":109,"shichen":"戌时","checkpoint":"操办喜事·二","scene":"夜里粥棚的伙计来交割，你把账算清，多给了每人二十文：「辛苦一季，拿去喝酒。」","options":[{"text":"伙计们千恩万谢","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"散伙不散人心，往后有事，他们还来。","source":"宋代商铺散伙酬劳，人情留一线。"},{"text":"让账房按数结","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"账是清了，可伙计们走时的背影，淡了些。","source":"宋代商铺散伙酬劳，人情留一线。"}],"difficulty":1,"npc":[],"foreshadow":"规矩立完，人心也拢住"},{"id":"E-109-未","branch":"E","stage":5,"day":109,"shichen":"未时","checkpoint":"操办喜事·三","scene":"午后粥棚那边报来：游春旺季过了，香客少了三成。你核了核账，粥棚该收了。","options":[{"text":"到期收摊，不恋战","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"该赚时赚，该收时收——这就是你立的规矩。","source":"宋代商铺时令经营，见好即收。"},{"text":"再撑半个月","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"撑是撑了，人工料钱倒贴进去几百文。","source":"宋代商铺时令经营，见好即收。"}],"difficulty":2,"npc":[],"foreshadow":"粥棚收官，收缩聚焦总号"},{"id":"E-110","branch":"E","stage":5,"day":110,"shichen":"辰时","checkpoint":"念慈渐长","scene":"念慈快周岁了，已经会扶着摇篮站起来。一早你抱着她去店里，她冲着灶上的火直乐。","options":[{"text":"说：像爹，爱看火","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"七郎在灶间听见了，锅铲敲得叮当响。","source":"宋代民间小儿初长，父母相戏为乐。"},{"text":"怕她烫着","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"抱是抱开了，可孩子的眼睛还盯着那团火。","source":"宋代民间小儿初长，父母相戏为乐。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"念慈爱火，灶上的第三代"},{"id":"E-110-戌","branch":"E","stage":5,"day":110,"shichen":"戌时","checkpoint":"念慈渐长·二","scene":"夜里你把娘的梳子也放进了抓周的单子。七郎问：「这个也抓？」","options":[{"text":"说：让她认得根","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「抓不抓都得放。」他点头，「让她知道从哪来的。」","source":"宋代抓周杂以家传之物，念祖之意。"},{"text":"说放着好看","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「也是。」他笑，「娘的梳子，怎么都好看。」","source":"宋代抓周杂以家传之物，念祖之意。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"木梳入抓周，根脉传到第三代"},{"id":"E-110-未","branch":"E","stage":5,"day":110,"shichen":"未时","checkpoint":"念慈渐长·三","scene":"午后抓周的物件要开始备了。大嫂列单子：木梳、算盘、笔、剪刀、尺子、木勺……","options":[{"text":"加一把小木勺","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"七郎连夜磨的，比当年那把还精细。","source":"宋代抓周之俗，以物卜儿之志。"},{"text":"按单子备就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"单子是齐了，可你心里总觉得少一样。","source":"宋代抓周之俗，以物卜儿之志。"}],"difficulty":1,"npc":["邻摊大嫂","陈七郎"],"foreshadow":"抓周物件，每样都有来处"},{"id":"E-111","branch":"E","stage":5,"day":111,"shichen":"辰时","checkpoint":"风平浪静","scene":"一早店里来了位老客，说京里最近流行一种新吃食「旋切冰雪冷元子」，问你家做不做。","options":[{"text":"让七郎试做","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"他试了三天，做出来了，比外头的还细。","source":"《东京梦华录》记汴京夏日冷饮之盛。"},{"text":"说守好老本行","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老本行是根，可新花样是活水。","source":"《东京梦华录》记汴京夏日冷饮之盛。"}],"difficulty":2,"npc":["陈七郎"],"foreshadow":"冷元子成新招牌，夏日进项"},{"id":"E-111-戌","branch":"E","stage":5,"day":111,"shichen":"戌时","checkpoint":"风平浪静·二","scene":"夜里陈伯从贰号回来吃饭，气色好了许多，说大夫夸他「心宽」。他看着念慈，笑得满脸褶子。","options":[{"text":"让他多抱抱孩子","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人抱着念慈，哼起走调的曲子，孩子竟睡着了。","source":"宋代民间老人含饴弄孙，颐养之乐。"},{"text":"说老人该歇着","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「抱孩子就是歇着。」老人不肯撒手。","source":"宋代民间老人含饴弄孙，颐养之乐。"}],"flavor":true,"difficulty":1,"npc":["老仆陈伯"],"foreshadow":"陈伯的晚年，是抱着孩子过的"},{"id":"E-111-未","branch":"E","stage":5,"day":111,"shichen":"未时","checkpoint":"风平浪静·三","scene":"午后官媒来回话：小豆子纳征过了，杏儿家收了大雁，婚期定在下月。","options":[{"text":"着手备喜宴","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「汤记」自己人的喜宴，必须是最好的。","source":"宋代纳征之后，备婚诸事启动。"},{"text":"让大嫂张罗","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大嫂张罗是好，可你是他们的「娘家人」。","source":"宋代纳征之后，备婚诸事启动。"}],"difficulty":1,"npc":["官媒","邻摊大嫂"],"foreshadow":"小豆子婚期定了，支线收官在即"},{"id":"E-112","branch":"E","stage":5,"day":112,"shichen":"辰时","checkpoint":"总号规矩","scene":"一早你把两店的伙计召集起来，立下「汤记三条」：料真、量足、笑待客。","options":[{"text":"刻在木牌上挂起","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"小豆子刻的字，挂在两店门口，日日见得。","source":"宋代商铺立规训伙，悬牌为示。"},{"text":"口头交代就行","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"口说的规矩，三个月就淡忘了。","source":"宋代商铺立规训伙，悬牌为示。"}],"difficulty":2,"npc":["小豆子"],"foreshadow":"「汤记三条」，店魂立住"},{"id":"E-112-戌","branch":"E","stage":5,"day":112,"shichen":"戌时","checkpoint":"总号规矩·二","scene":"夜里你问七郎：「三条规矩，你最认哪条？」他想都没想：「料真。」","options":[{"text":"问他为什么","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「当年赊你汤，汤是真的。」他认真得可爱。","source":"宋人笔记记市井匠人以真为本。"},{"text":"说我最认笑待客","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"「那是。」他笑，「你笑起来，客人就多。」","source":"宋人笔记记市井匠人以真为本。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"三条规矩，一条是一句心里话"},{"id":"E-112-未","branch":"E","stage":5,"day":112,"shichen":"未时","checkpoint":"总号规矩·三","scene":"午后有伙计嘀咕：「料真量足，本大利薄，东家是傻吗？」你听见了，没恼。","options":[{"text":"当众算一笔长远账","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「老客回头、新客慕名——薄利里出厚利。」","source":"宋代商铺以信誉求长久，笔记屡见。"},{"text":"扣他半天工钱","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"扣钱堵嘴，堵不住心——规矩要服人才行。","source":"宋代商铺以信誉求长久，笔记屡见。"}],"difficulty":2,"npc":[],"foreshadow":"规矩立了，还得让人心服"},{"id":"E-113","branch":"E","stage":5,"day":113,"shichen":"辰时","checkpoint":"资本再至","scene":"一早那外地客商又来了，这次不是一个人——身后跟着个账房先生，抱着一摞契书。","options":[{"text":"请进来说话","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「谈可以，我的柜台我做主。」你先定调。","source":"宋代商贾谈判，东主先立章程。"},{"text":"让七郎去应付","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"七郎应付不来账房先生，你得亲自上。","source":"宋代商贾谈判，东主先立章程。"}],"difficulty":3,"npc":["外地客商"],"foreshadow":"资本第二波，谈的是真合作了"},{"id":"E-113-戌","branch":"E","stage":5,"day":113,"shichen":"戌时","checkpoint":"资本再至·二","scene":"契书立了，客商走后，七郎长出一口气：「跟他谈，比炒十个菜还累。」","options":[{"text":"给他烫壶酒","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「辛苦你了。」他一口干了，「往后我来谈。」","source":"宋代市井夫妇，夜酌以慰辛劳。"},{"text":"说往后我谈","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"「那不行。」他急了，「谈判是我的活。」","source":"宋代市井夫妇，夜酌以慰辛劳。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"一个管账一个管灶，分工更明"},{"id":"E-113-未","branch":"E","stage":5,"day":113,"shichen":"未时","checkpoint":"资本再至·三","scene":"午后谈判桌上，客商想控股五成。你拨着算盘，把果子生意的进项算给他听。","options":[{"text":"最多三成，要现钱","correct":true,"tags":["才华"],"dims":{"才华":3},"feedback":"他沉吟良久：「小娘子的算盘，比我账房还精。」","source":"宋代商铺控股谈判，以实为据。"},{"text":"让一步求安稳","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"让一步，他就想再进一步——你想起孙三。","source":"宋代商铺控股谈判，以实为据。"}],"difficulty":3,"npc":["外地客商"],"foreshadow":"三成现钱，底线守住"},{"id":"E-114","branch":"E","stage":5,"day":114,"shichen":"辰时","checkpoint":"喜事临门","scene":"小豆子成亲前三日，按规矩要「铺房」。你带着大嫂杏儿去他赁的小院布置。","options":[{"text":"亲手挂帐子","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「姐挂的帐，我们睡一辈子。」杏儿红着脸说。","source":"宋代婚前铺房，女眷挂帐为礼。"},{"text":"让她们弄，你看孩子","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"念慈是好看，可这帐子，该你挂。","source":"宋代婚前铺房，女眷挂帐为礼。"}],"difficulty":1,"npc":["邻摊大嫂","丫头杏儿"],"foreshadow":"铺房挂帐，她从受恩人到施恩人"},{"id":"E-114-戌","branch":"E","stage":5,"day":114,"shichen":"戌时","checkpoint":"喜事临门·二","scene":"夜里小豆子的话让你睡不着。你翻出娘的梳子，忽然明白了什么。","options":[{"text":"为他打一把新木梳","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"「新梳新人生。」娘那把是你的，念想可以再做。","source":"宋代民间以贴身之物赠后辈，念情之意。"},{"text":"说明日给他包红包","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"红包是厚，可孩子要的不是钱。","source":"宋代民间以贴身之物赠后辈，念情之意。"}],"difficulty":2,"npc":["小豆子"],"foreshadow":"木梳易主？不，是念想有了去处"},{"id":"E-114-未","branch":"E","stage":5,"day":114,"shichen":"未时","checkpoint":"喜事临门·三","scene":"午后小豆子紧张得直转，问你：「姐，拜堂的时候我手放哪？」","options":[{"text":"教他三遍","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"教到第三遍，他忽然说：「姐，我有点想我娘。」","source":"宋代婚礼仪节，司仪教导为常。"},{"text":"说别紧张","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"话是安慰，可孩子的手还是抖。","source":"宋代婚礼仪节，司仪教导为常。"}],"difficulty":1,"npc":["小豆子"],"foreshadow":"他没娘，你就是娘家人"},{"id":"E-115","branch":"E","stage":5,"day":115,"shichen":"辰时","checkpoint":"豆子大婚","scene":"小豆子成亲日。你给他备了花轿——租的，但扎了红绸。他站在轿前，忽然朝你跪下磕了三个头。","options":[{"text":"受一个，扶他起来","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"「姐，没有你，我还在桥洞要饭。」他哭了。","source":"宋代婚礼拜谢恩人，情义之礼。"},{"text":"全受了","correct":false,"tags":["名声"],"dims":{"名声":2},"feedback":"三个头都受了，你心里却想：该磕的是他爹娘。","source":"宋代婚礼拜谢恩人，情义之礼。"}],"difficulty":2,"npc":["小豆子"],"foreshadow":"checkpoint 收官：善缘开花结果"},{"id":"E-115-戌","branch":"E","stage":5,"day":115,"shichen":"戌时","checkpoint":"豆子大婚·二","scene":"夜里喜宴散，七郎抱着睡着的念慈，你看着空下来的院子，忽然有点舍不得这热闹。","options":[{"text":"说：再过几年就咱家","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「嗯。」他颠了颠孩子，「到时候比这还热闹。」","source":"宋代民间婚宴之后，家人闲话。"},{"text":"说：杏儿嫁人了","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「嫁人了也是咱家人。」他说得笃定。","source":"宋代民间婚宴之后，家人闲话。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"热闹散场，日子还在往前"},{"id":"E-115-未","branch":"E","stage":5,"day":115,"shichen":"未时","checkpoint":"豆子大婚·三","scene":"拜堂时，小豆子爹娘的位置空着。你和大嫂坐了上去——你坐左边，她坐右边。","options":[{"text":"坦然受这一拜","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「一拜高堂。」司仪喊得响，你眼泪下来了。","source":"宋代婚礼拜高堂，无父母者以尊长代。"},{"text":"推辞不敢坐","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"大嫂把你按下去：「你不坐，谁坐？」","source":"宋代婚礼拜高堂，无父母者以尊长代。"}],"difficulty":2,"npc":["小豆子","邻摊大嫂"],"foreshadow":"你坐上了高堂位——当年的孤女"},{"id":"E-116","branch":"E","stage":5,"day":116,"shichen":"辰时","checkpoint":"周岁将近","scene":"念慈周岁前两日，你开始备抓周的席面。陈伯非要从贰号回来帮忙，说「重孙女的席，我得看着」。","options":[{"text":"让他管点心","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"老人守在点心灶前，一坐就是半天，眼里全是笑。","source":"宋代周岁宴席，家中老人监厨为福。"},{"text":"说您歇着就好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"老人嘴上应着，还是挪到灶间门口坐着。","source":"宋代周岁宴席，家中老人监厨为福。"}],"difficulty":1,"npc":["老仆陈伯"],"foreshadow":"陈伯的「重孙女」，情分过三代"},{"id":"E-116-戌","branch":"E","stage":5,"day":116,"shichen":"戌时","checkpoint":"周岁将近·二","scene":"夜里你把抓周的物件一件件摆开：木梳、算盘、笔、尺、剪、木勺、银锣……七郎凑过来看。","options":[{"text":"问他猜抓哪个","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「木勺。」他笃定，「我闺女，灶上的料。」","source":"宋代抓周前夜，父母卜物为乐。"},{"text":"说抓了就是你的","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「抓算盘呢？」「那也是我闺女，算盘的料。」他改口飞快。","source":"宋代抓周前夜，父母卜物为乐。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"抓周悬念，明日揭晓"},{"id":"E-116-未","branch":"E","stage":5,"day":116,"shichen":"未时","checkpoint":"周岁将近·三","scene":"午后舅父舅母提前来送抓周的礼——一面小银锣，说「抓周抓了它，往后响亮」。","options":[{"text":"收下，请他们坐首席","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"舅父摸着银锣说：「这孩子的席，比我们当年的体面。」","source":"宋代抓周亲眷赠礼，银器为贵重。"},{"text":"说太破费了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"「破费什么。」舅母嗔怪，「这是我们欠她的。」","source":"宋代抓周亲眷赠礼，银器为贵重。"}],"difficulty":1,"npc":["舅父","舅母"],"foreshadow":"舅家的礼，从添箱到添锣"},{"id":"E-117","branch":"E","stage":5,"day":117,"shichen":"辰时","checkpoint":"念慈抓周","scene":"抓周日。亲朋满院，红毡铺地，物件摆了一圈。念慈穿着百家被改的小袄，被放到毡子中央。","options":[{"text":"屏息看她爬","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"小家伙左看右看，忽然加速——直奔那柄木勺。","source":"《东京梦华录》记抓周之俗甚详。"},{"text":"让七郎去引","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"七郎一引，孩子偏往反方向爬，满堂哄笑。","source":"《东京梦华录》记抓周之俗甚详。"}],"difficulty":1,"npc":["陈七郎"],"foreshadow":"抓周了，一年的句号"},{"id":"E-117-戌","branch":"E","stage":5,"day":117,"shichen":"戌时","checkpoint":"念慈抓周·二","scene":"夜里客散，你抱着睡熟的念慈，她手里还攥着那柄小木勺。七郎轻手轻脚收摊子。","options":[{"text":"把木勺收进奁匣","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"奁匣里：娘的梳、他的勺、孩子的锁——三代人。","source":"宋代民间珍藏小儿抓周之物为念。"},{"text":"让她攥着睡","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「让她攥着。」七郎说，「她抓的，就是她的。」","source":"宋代民间珍藏小儿抓周之物为念。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"奁匣三物，终章的传家箱"},{"id":"E-117-未","branch":"E","stage":5,"day":117,"shichen":"未时","checkpoint":"念慈抓周·三","scene":"念慈一手抓木勺，一手又去够娘的梳子——两样都抱在怀里，谁也拿不走。","options":[{"text":"笑：灶和根都要","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"满堂喝彩：「这丫头，往后是个掌灶又掌家的！」","source":"宋代抓周兼取两物，主兼得之象。"},{"text":"让她只留一样","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孩子抱得紧，谁掰跟谁急——像她娘。","source":"宋代抓周兼取两物，主兼得之象。"}],"difficulty":1,"npc":[],"foreshadow":"木勺+木梳，她的传承有了模样"},{"id":"E-118","branch":"E","stage":5,"day":118,"shichen":"辰时","checkpoint":"团圆渐近","scene":"一早陈母说想回乡下一趟——不是回去住，是把老屋的东西收拾来：「往后，这里就是家了。」","options":[{"text":"让七郎陪她去","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"「娘，往后清明，咱们一起回去看你。」","source":"宋代民间迁住，告祭祖屋为礼。"},{"text":"说东西不用搬","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"「不是东西的事。」老人说，「是做个了断。」","source":"宋代民间迁住，告祭祖屋为礼。"}],"difficulty":1,"npc":["陈母","陈七郎"],"foreshadow":"陈母了断乡下，根扎汴京"},{"id":"E-118-戌","branch":"E","stage":5,"day":118,"shichen":"戌时","checkpoint":"团圆渐近·二","scene":"夜里一家人围坐，陈伯抱着念慈，陈母纳鞋底，大嫂嗑瓜子，你拨算盘，七郎添炭。","options":[{"text":"忽然说：像不像画","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「什么画？」七郎问。「团圆图。」你说。","source":"宋代民间合家夜话，天伦之乐。"},{"text":"什么都不说","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"有些时刻，说了反而淡了。","source":"宋代民间合家夜话，天伦之乐。"}],"flavor":true,"difficulty":1,"npc":["老仆陈伯","陈母","邻摊大嫂","陈七郎"],"foreshadow":"团圆图，终章的画眼"},{"id":"E-118-未","branch":"E","stage":5,"day":118,"shichen":"未时","checkpoint":"团圆渐近·三","scene":"午后你盘这一年的总账：两间店、一处粥棚、果子合作、包伙、喜宴……净入过了八十贯。","options":[{"text":"在账尾写四个字","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"「安身立命。」你写完，自己看了很久。","source":"宋代商铺年终核账，东主自记。"},{"text":"合上账本不看了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"账是清了，可心里那笔账，还没落笔。","source":"宋代商铺年终核账，东主自记。"}],"difficulty":2,"npc":[],"foreshadow":"八十贯，从三贯钱到八十贯"},{"id":"E-119","branch":"E","stage":5,"day":119,"shichen":"辰时","checkpoint":"终局前夜","scene":"最后一日的前一天。你起得比谁都早，一个人走到州桥上，看天色从鱼肚白变成金红。","options":[{"text":"对着汴水说声谢","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"水声潺潺，像在说：不客气，你应得的。","source":"《东京梦华录》记汴河晨景。"},{"text":"只是看着","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"看是看了，可心里那句话，还是想说出来。","source":"《东京梦华录》记汴河晨景。"}],"difficulty":1,"npc":[],"foreshadow":"终章前，她与这条河道别又重逢"},{"id":"E-119-戌","branch":"E","stage":5,"day":119,"shichen":"戌时","checkpoint":"终局前夜·二","scene":"夜里七郎见你收拾奁匣，凑过来把「汤」「记」两把木勺也放进去，说：「凑个整。」","options":[{"text":"说还差一把","correct":true,"tags":["感情"],"dims":{"情缘":2},"feedback":"「念慈那把？」「嗯，等她长大自己放进来。」","source":"宋代民间夫妇共理奁匣，传家之意。"},{"text":"说就这样吧","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"「行。」他合上盖子，「往后年年添一件。」","source":"宋代民间夫妇共理奁匣，传家之意。"}],"flavor":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"奁匣待添，终章余韵"},{"id":"E-119-未","branch":"E","stage":5,"day":119,"shichen":"未时","checkpoint":"终局前夜·三","scene":"午后你把墙皮账的拓片、娘的梳子、两把木勺、银锁、银镯、百家被……一样样收进奁匣。","options":[{"text":"留一张白纸","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"往后念慈的故事，让她自己写在这张纸上。","source":"宋代民间珍藏传家之物，以启后人。"},{"text":"把奁匣锁上","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"锁是锁了，可总觉得还该留点什么。","source":"宋代民间珍藏传家之物，以启后人。"}],"difficulty":2,"npc":[],"foreshadow":"奁匣留白，故事未完"},{"id":"E-120","branch":"E","stage":5,"day":120,"shichen":"辰时","checkpoint":"大结局","scene":"第一百二十天。你站在「汤记」门口，怀里抱着念慈，身后是七郎、陈伯、陈母、大嫂、小豆子、杏儿。","options":[{"text":"说：开门","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"两扇木门打开，汴京的日头照进来。","source":"《东京梦华录》记汴京商铺晨开之景。"},{"text":"让念慈抓门环","correct":false,"tags":["感情"],"dims":{"情缘":1},"feedback":"孩子抓了抓，门没开，满堂都笑了。","source":"《东京梦华录》记汴京商铺晨开之景。"}],"difficulty":1,"npc":["陈七郎","老仆陈伯","陈母","邻摊大嫂","小豆子","丫头杏儿"],"foreshadow":"门开了，就是日子"},{"id":"E-120-戌","branch":"E","stage":5,"day":120,"shichen":"戌时","checkpoint":"大结局·二","scene":"入夜，两盏「汤记」灯笼亮着。你抱着念慈站在门口，七郎在灶间忙，灯火把三个人的影子投在州桥的石板上，长长的，连到桥那头——一百二十天前，那里有个抱着包袱、只有三贯钱和一把木梳的姑娘。","options":[{"text":"对念慈说：娘嫁出去了","correct":true,"tags":["感情"],"dims":{"情缘":3},"feedback":"「先嫁给了这双手，再嫁给了那个提灯的人。」汴京很大，容得下肯做事的手，也容得下慢慢来的情。","source":"《东京梦华录》记汴京夜市灯火如昼。"},{"text":"对汴京说声晚安","correct":true,"tags":["感情","自主"],"dims":{"情缘":2,"自主":1},"feedback":"晚安，汴京。明天灶上还有火，店里还有客，怀里还有个会抓木勺的孩子。日子，才刚开始。","source":"《东京梦华录》记汴京夜市灯火如昼。"}],"finale":true,"difficulty":1,"npc":["陈七郎"],"foreshadow":"E线终：手是自己的，灯是他的，夜是暖的"},{"id":"E-120-未","branch":"E","stage":5,"day":120,"shichen":"未时","checkpoint":"大结局·三","scene":"晌午，有外乡的小娘子进店，怯生生地问：「掌柜的，你们这……招学徒吗？我什么都能干。」","options":[{"text":"说：先吃碗热汤","correct":true,"tags":["名声"],"dims":{"名声":3},"feedback":"汤端上去，你看见了一年多前的自己。","source":"《东京梦华录》记汴京四方来投者众。"},{"text":"问她从哪来的","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"问是问了，可那碗汤，更该先上。","source":"《东京梦华录》记汴京四方来投者众。"}],"difficulty":1,"npc":[],"foreshadow":"轮回：又一双肯做事的手"}];
